UI_LANGUAGES = ('en', 'ar')


def _static_version(*names):
    """Cache-buster from the files' modification times, read once at start."""
    try:
        return str(int(max(os.path.getmtime(os.path.join(app.static_folder, n)) for n in names)))
    except OSError:
        return '0'


I18N_VERSION = _static_version('i18n/ar.js', 'js/bg-i18n.js', 'css/bg-rtl.css')


# Stored values a person typed. The Arabic interface never translates these,
# even when one happens to be a dictionary word ("Booth", "CASH", a job title).
I18N_DATA_COLUMNS = (
    ('client', 'client_name'), ('client', 'job_title'), ('company', 'company_name'),
    ('company', 'industry_sector'), ('supplier', 'company_name'), ('supplier', 'contact_person_name'),
    ('supplier', 'supplier_name'), ('supplier', 'job_title'), ('sales_request', 'title'),
    ('sales_request_items', 'name'), ('sales_request_items', 'unit'), ('item_catalog', 'name'),
    ('item_catalog', 'unit'), ('inventory_items', 'item_name'), ('items', 'item_name'),
    ('entities', 'entity_name'), ('approved_item_components', 'component_name'),
    ('payment_methods', 'method_name'), ('payment_methods', 'bank_name'),
    ('finance_categories', 'category_name'), ('user', 'name'), ('user', 'title'),
    ('user_expense_tracking', 'supplier_name'),
)
_i18n_protected_cache = {'at': 0.0, 'words': []}


def _i18n_dictionary_keys():
    """Lower-cased English keys of static/i18n/ar.js."""
    path = os.path.join(app.static_folder, 'i18n', 'ar.js')
    with open(path, encoding='utf-8') as fh:
        text = fh.read()
    return {k.strip().lower() for k in json.loads(text.split('window.BG_AR = ', 1)[1].rstrip().rstrip(';'))}


def i18n_protected_words():
    """
    Dictionary words that are also stored data, for the translator to skip.

    Only the overlap is sent, so the page learns nothing beyond words already
    in the public dictionary. Cached for ten minutes: a new item named like a
    dictionary word is protected within that window.
    """
    now = time.time()
    if now - _i18n_protected_cache['at'] < 600:
        return _i18n_protected_cache['words']
    words = []
    try:
        keys = _i18n_dictionary_keys()
        conn, cur = connection()
        try:
            found = set()
            for table, column in I18N_DATA_COLUMNS:
                cur.execute("SELECT DISTINCT LOWER(TRIM(`%s`)) AS v FROM `%s` WHERE `%s` IS NOT NULL"
                            % (column, table, column))
                found.update(r['v'] for r in cur.fetchall() if r['v'])
        finally:
            cur.close()
            conn.close()
        words = sorted(found & keys)
    except Exception as e:
        app.logger.warning('i18n protected words unavailable: %s', e)
        return _i18n_protected_cache['words']
    _i18n_protected_cache.update(at=now, words=words)
    return words


@app.context_processor
def inject_ui_language():
    """English unless the visitor chose Arabic; the pages read ui_lang for lang/dir."""
    lang = request.cookies.get('bg_lang') if has_request_context() else None
    lang = lang if lang in UI_LANGUAGES else 'en'
    return {'ui_lang': lang, 'i18n_version': I18N_VERSION,
            'i18n_protected': i18n_protected_words if lang == 'ar' else (lambda: [])}


@app.route('/lang/<code>', methods=['GET'])
def set_ui_language(code):
    """Switch the interface language and go back to the page it was chosen on."""
    back = '/home'
    ref = request.referrer
    if ref:
        parsed = urlparse(ref)
        # Only ever back to this site, never to wherever the Referer points.
        if parsed.netloc == request.host and parsed.path.startswith('/') and not parsed.path.startswith('/lang/'):
            back = parsed.path + ('?' + parsed.query if parsed.query else '')
    response = redirect(back)
    response.set_cookie('bg_lang', code if code in UI_LANGUAGES else 'en',
                        max_age=365 * 24 * 3600, samesite='Lax', secure=request.is_secure)
    return response


@app.context_processor
def inject_nav_sections():
    """The navbar menus and the home cards both read this one list."""
    current = rbac.sections(session.get('perms'))
    return {
        'nav_sections': current,
        'fcm_vapid_key': FCM_VAPID_KEY,
        # Everyone but the owner holds one of these, so they are a link each.
        # Four of them side by side pushed the navbar onto a second line, so
        # more than one collapses into a single menu.
        'nav_portals': [{'key': key, 'label': label, 'icon': icon, 'endpoint': endpoint}
                        for key, label, icon, endpoint in NAV_PORTALS if key in current],
    }


def visible_user_ids(code):
    """
    Owner ids the caller may see for this permission.

    Returns None when the scope is unrestricted, so callers can skip building a
    predicate. Aborts 403 when the permission is not held at all.
    """
    scope = rbac.resolve(session.get('perms') or {}, code)
    if scope is None:
        abort(403)
    if scope == 'all':
        return None

    me = session.get('user_id')
    if scope == 'own':
        return [me]

    # Only team and department scope need a lookup.
    conn, cur = connection()
    if scope == 'team':
        cur.execute("SELECT id FROM user WHERE manager_id = %s", (me,))
        others = [row['id'] for row in cur.fetchall()]
        cur.close()
        conn.close()
        return rbac.allowed_user_ids('team', me, direct_report_ids=others)

    cur.execute("""
        SELECT id FROM user
        WHERE department_id IS NOT NULL
          AND department_id = (SELECT department_id FROM user WHERE id = %s)
    """, (me,))
    others = [row['id'] for row in cur.fetchall()]
    cur.close()
    conn.close()
    return rbac.allowed_user_ids('department', me, department_member_ids=others)


def scope_clause(code, column):
    """
    Build a SQL fragment restricting `column` to the owner ids the caller may
    see. Returns ("", []) when the caller's scope is unrestricted.

    Usage:  clause, params = scope_clause('sales_request.view', 'sr.owner_user_id')
            cur.execute("SELECT ... WHERE 1=1 " + clause, [...] + params)
    """
    ids = visible_user_ids(code)
    if ids is None:
        return "", []
    if not ids:
        # Holds the permission but can see nobody; must not degrade to "all".
        return " AND 1=0", []
    placeholders = ",".join(["%s"] * len(ids))
    return " AND %s IN (%s)" % (column, placeholders), list(ids)


def item_outside_decide_scope(cur, item_id):
    """
    True when the caller may not decide on this item's client answer.

    The decide routes (approve, reject, negotiate) were gated on the
    permission alone, so anyone holding it at any scope could act on any item
    by id. The rule is the one the Client Approval list already applies to
    what the caller can see -- the request's owner inside their scope -- so
    "I can see it" and "I can decide on it" can never disagree. A missing item
    is not "outside": the route answers that with its own 404.
    """
    scope_sql, params = scope_clause('client_approval.decide', 'sr.owner_user_id')
    if not scope_sql:
        return False
    cur.execute("""
        SELECT 1 FROM sales_request_items i
        JOIN sales_request sr ON sr.id = i.request_id
        WHERE i.id = %s""" + scope_sql, [item_id] + params)
    if cur.fetchone():
        return False
    cur.execute("SELECT 1 FROM sales_request_items WHERE id = %s", (item_id,))
    return cur.fetchone() is not None


# The two heads who decide a client's counter-offer, by the department that
# owns the request: a line, the permission that decides it, who that is, and
# the page they do it on. The workflow behind both pages is the same one.
NEGOTIATION_LINES = {
    'sales':   ('negotiation.decide_sales_head', 'Sales Head', '/sales-head-approval'),
    'account': ('negotiation.decide_account_head', 'Account Director', '/account-head-approval'),
}


def negotiation_line_for(department_code):
    """The line a request belongs to: Account Management's own, or Sales'."""
    return 'account' if department_code == 'account' else 'sales'


def negotiation_decide_code():
    """
    The negotiation permission the caller decides with.

    A head holds one of the two, at department scope; the admin holds both at
    'all', where either gives the same answer.
    """
    return ('negotiation.decide_sales_head' if has('negotiation.decide_sales_head')
            else 'negotiation.decide_account_head')


def negotiation_line_clause(line, column='sr.owner_user_id'):
    """Restrict to requests owned inside one line. `line` is whitelisted."""
    if line not in NEGOTIATION_LINES:
        return ''
    return (" AND %s IN (SELECT u.id FROM user u JOIN department d ON d.id = u.department_id"
            " WHERE d.code = '%s')" % (column, line))


def negotiation_outside_scope(cur, negotiation_id):
    """
    True when the caller may not decide on this negotiation.

    The Sales Head list and its approve / decline routes were gated on the
    permission alone and listed every negotiation in the company. With the
    account director holding it too, that would have put Sales' negotiations
    in front of Account Management and the reverse. The rule is the request
    owner inside the caller's scope -- the same one the requests themselves
    use. A missing negotiation is not "outside": the route answers that.
    """
    scope_sql, params = scope_clause(negotiation_decide_code(), 'sr.owner_user_id')
    if not scope_sql:
        return False
    cur.execute("""
        SELECT 1 FROM negotiation_requests nr
        JOIN sales_request sr ON sr.id = nr.request_id
        WHERE nr.id = %s""" + scope_sql, [negotiation_id] + params)
    if cur.fetchone():
        return False
    cur.execute("SELECT 1 FROM negotiation_requests WHERE id = %s", (negotiation_id,))
    return cur.fetchone() is not None


NEGOTIATION_OUTSIDE_SCOPE = ('This negotiation is on a request outside your department, '
                             'so it is not yours to decide.')


DECIDE_OUTSIDE_SCOPE = ('This item belongs to a request outside the ones you look after, '
                        'so you cannot record the client\'s answer on it.')


def claim_sales_request(cur, request_id, owner_username=None):
    """
    Stamp the owner on a newly created sales request.

    Every list of requests is scoped on `sr.owner_user_id`. A request written
    without one is invisible to everybody whose scope is not 'all' -- which is
    how a request raised by Sales vanished from Sales the moment it was saved.
    The inserts only ever wrote `created_by`, a username, which no scope reads.

    Takes the creator's username so the admin-approval path can name whoever
    asked rather than whoever approved. Writes inside the caller's transaction
    and does not commit.
    """
    owner_id = None
    if owner_username:
        # username or display name: the approvals table holds whichever the
        # creating route wrote, the same way notify_username() reads it.
        cur.execute("SELECT id FROM user WHERE username = %s OR name = %s LIMIT 1",
                    (owner_username, owner_username))
        row = cur.fetchone()
        owner_id = row['id'] if row else None
    if not owner_id:
        owner_id = session.get('user_id')
    if not owner_id:
        return None
    cur.execute("""UPDATE sales_request SET owner_user_id = %s
                   WHERE id = %s AND owner_user_id IS NULL""", (owner_id, request_id))
    return owner_id


def assert_scope(code, owner_user_id):
    """Abort 403 unless the caller's scope covers this record's owner."""
    ids = visible_user_ids(code)
    if ids is not None and owner_user_id not in ids:
        abort(403)


def perm(*codes):
    """
    Decorator gating a route on one or more permissions, any of which suffices.
    Sets `_perms` on the wrapper so the default-deny backstop can see the gate.
    """
    for code in codes:
        if code not in rbac.PERMISSIONS:
            raise rbac.UnknownPermission(code)

    def decorator(f):
        @wraps(f)
        def decorated_function(*args, **kwargs):
            if not session.get('user_id'):
                if request.path.startswith('/api/'):
                    return jsonify(error='Not authenticated'), 401
                return redirect(url_for('login'))
            if any(has(code) for code in codes):
                return f(*args, **kwargs)
            fresh_perms = refresh_session_permissions()
            if any(rbac.resolve(fresh_perms, code) is not None for code in codes):
                return f(*args, **kwargs)
            # Who was refused what. A 403 used to leave no trace at all, so
            # "it says error when I save" could not be answered from the log:
            # the access log records the refusal but never the account, and on
            # a shared proxy address one person's 403 looks like another's.
            app.logger.warning(
                'Refused %s for user %s (role %s) on %s %s',
                '/'.join(codes), session.get('user_id'),
                session.get('role_code'), request.method, request.path)
            if request.path.startswith('/api/'):
                return jsonify(error='Your account does not hold the permission '
                                     'this needs (%s).' % '/'.join(codes),
                               permission=list(codes)), 403
            return abort(403)
        decorated_function._perms = codes
        return decorated_function
    return decorator


# Coarse notification audiences, expressed as the permission that defines them.
NOTIFICATION_AUDIENCE = {
    'admin': 'user.create',
    'sales': 'sales_request.create',
    'operation': 'sales_item.cost',
    'pricing': 'sales_item.price',
    'finance': 'finance_txn.approve',
    'sales_head': 'negotiation.decide_sales_head',
}


class Audience(list):
    """
    Recipient ids, plus `fyi`: the ones on the list only because the admin role
    holds every permission while the work belongs to another desk. They are
    told, but for them it is an announcement, not something waiting on them.
    """
    fyi = frozenset()

    @classmethod
    def of(cls, ids, fyi=()):
        audience = cls(ids)
        audience.fyi = frozenset(fyi)
        return audience

    def __add__(self, other):
        return Audience.of(list(self) + list(other), self.fyi | getattr(other, 'fyi', frozenset()))

    # [owner] + users_holding(...) keeps the marks too.
    def __radd__(self, other):
        return Audience.of(list(other) + list(self), self.fyi)


def _admin_ids(cur, user_ids):
    if not user_ids:
        return set()
    cur.execute("SELECT u.id FROM user u JOIN rbac_role r ON r.id = u.rbac_role_id "
                "WHERE r.code = 'admin' AND u.id IN (%s)" % ",".join(["%s"] * len(user_ids)),
                list(user_ids))
    return {row['id'] for row in cur.fetchall()}


def get_users_by_role(role_name):
    """
    Return user ids to notify for a workflow role.

    The legacy `role` table is gone; notification call sites still speak in
    coarse terms ('admin', 'sales', 'operation'), so map those onto the
    permission that actually defines the audience.
    """
    permission = NOTIFICATION_AUDIENCE.get(role_name)
    if not permission:
        return []
    role_codes = [code for code, grants in rbac.SEED_MATRIX.items() if permission in grants]
    if not role_codes:
        return []
    conn, cur = connection()
    placeholders = ",".join(["%s"] * len(role_codes))
    # The CEO is out of every fan-out, for the reason in users_holding() --
    # except when the audience is the admins: the CEO is one, and what is sent
    # to admins (an urgent request to approve) is theirs to act on.
    cur.execute(
        "SELECT u.id FROM user u JOIN rbac_role r ON r.id = u.rbac_role_id "
        "WHERE r.code IN (%s) AND u.is_active = 1" % placeholders
        + ("" if role_name == 'admin' else " AND u.manager_id IS NOT NULL"),
        role_codes,
    )
    user_ids = [row['id'] for row in cur.fetchall()]
    # Sent to 'operation' or 'finance', an admin is there by holding everything.
    fyi = _admin_ids(cur, user_ids) if role_name != 'admin' else set()
    cur.close()
    conn.close()
    return Audience.of(user_ids, fyi)


def notifications_disabled():
    """
    True when a notification would be noise rather than news.

    The tests roll MySQL back but Mongo is not in that transaction, so every run
    used to leave its notifications behind for ever: 1757 of the 1825 in the
    tray were fixtures telling real people about 'Costing test item'. That is
    the whole of the "it goes up when nobody did anything" complaint.
    """
    return bool(os.environ.get('BG_NO_NOTIFICATIONS')) or 'unittest' in sys.modules


# A notification is Important when the reader is being asked to do something:
# approve, cost, price, review, post, source, confirm. Everything else -- an
# outcome, a status change, "X was added" -- is an Announcement. Decided from
# the title because it is the one thing every sender writes, and the same
# rule classifies the notifications already stored. Matched at the start of
# the title, case-insensitively.
IMPORTANT_TITLES = re.compile(r"""^(
      approval\ needed
    | new\ sales\ request\ \#                 # operations: add costing
    | new\ items\ on\ request\ \#              # operations: cost the added items
    | request\ \#\d+\ (re-)?costing\ completed  # pricing: set the price
    | re-costing\ done                         # pricing: re-price
    | costing\ assigned
    | new\ costing\ to\ decide
    | costing\ re-submitted
    | re-costing\ needed
    | re-pricing\ needed
    | negotiation\ to\ review
    | client\ approved:                        # operations: source and deliver
    | invoice\ to\ post
    | invoice\ returned
    | expenses\ to\ approve
    | عهدة\ request\ from
    | عهدة\ request:
    | عهدة\ request\ approved\ by               # finance decides next
    | تسوية\ عهدة\ from                        # confirm the cash
    | new\ (client|company|supplier)\ request
    | out\ of\ stock
    | below\ minimum
    | .*\ mentioned\ you
)""", re.IGNORECASE | re.VERBOSE)

NOTIFICATION_CATEGORIES = ('important', 'announcement')


def notification_category(title):
    """'important' when the title asks the reader to act, else 'announcement'."""
    return 'important' if IMPORTANT_TITLES.match((title or '').strip()) else 'announcement'


def notify_users(user_ids, title, content, link=None, category=None, action=None):
    """
    Send one notification to each of these people.

    The one place a notification is written. A notification is a hint: it must
    never take down the work that earned it, so every failure here is swallowed
    and counted as nothing sent.

    `link` is where the work is. A notification that says something needs doing
    and then leaves the reader to find the page is half a notification, so the
    destination travels with it. Senders that do not pass one still work: the
    tray falls back to guessing from the words, which is all it could ever do
    for the notifications already in the database.
    """
    if notifications_disabled():
        return 0
    try:
        fyi = getattr(user_ids, 'fyi', frozenset())
        recipients = sorted({int(user_id) for user_id in (user_ids or []) if user_id})
        if not recipients:
            return 0
        if category not in NOTIFICATION_CATEGORIES:
            category = notification_category(title)

        def category_for(user_id):
            # Important means waiting on *this* reader.
            return 'announcement' if user_id in fyi else category

        added_by = session.get('name', 'System')
        added_uid = session.get('user_id', 0)
        now = datetime.now()
        documents = [{
            'uid': user_id,
            'title': title,
            'content': content,
            'link': link or None,
            'category': category_for(user_id),
            # An approval this person can decide from the tray: {kind, id, stage}.
            'action': action if category_for(user_id) == 'important' else None,
            'added_by': added_by,
            'added_uid': int(added_uid),
            'added_date': now,
            'triggered': False,
            'read': False,
        } for user_id in recipients]
        written = mongo_safe(
            lambda: len(mongo().notifications.insert_many(documents).inserted_ids),
            fallback=0, label='notify users')
        # Phones buzz for work, not for news -- except Operations, who asked
        # to hear everything (a chat they muted stays quiet).
        everything = push_everything_ids(recipients, link)
        movers = [user_id for user_id in recipients
                  if category_for(user_id) == 'important' or user_id in everything]
        if movers:
            push_to_users(movers, title, content, link)
        return written
    except Exception as e:
        print(f"Error sending notifications: {e}")
        return 0


CHAT_LINK = re.compile(r'^/home\?chat=(sr:\d+|g:[\w-]+)$')


def push_everything_ids(user_ids, link=None):
    """
    Of these people, the ones whose phones get every notification, not only
    the Important ones: the Operations department. Someone who muted the chat
    a notification links to is left out for that one.
    """
    # ponytail: department rule; a per-person setting if other teams ask too.
    if not user_ids:
        return set()
    try:
        conn, cur = connection()
        try:
            marks = ','.join(['%s'] * len(user_ids))
            cur.execute("SELECT u.id FROM user u JOIN department d ON d.id = u.department_id "
                        "WHERE d.code = 'operations' AND u.id IN (%s)" % marks, list(user_ids))
            people = {r['id'] for r in cur.fetchall()}
            thread = CHAT_LINK.match(link or '')
            if people and thread:
                cur.execute("SELECT user_id FROM chat_mute WHERE thread = %s "
                            "AND (muted_until IS NULL OR muted_until > NOW())", (thread.group(1),))
                people -= {r['user_id'] for r in cur.fetchall()}
            return people
        finally:
            cur.close()
            conn.close()
    except Exception as e:
        print(f"Push-everything lookup failed: {e}")
        return set()


def push_to_users(user_ids, title, content, link=None):
    """
    The same notification on the recipients' phones, through Firebase Cloud
    Messaging, to every device registered for them (fcm_tokens, by user id).
    Best effort: a dead token is dropped, any other failure is logged and the
    bell notification stands.
    """
    if not FCM_VAPID_KEY or not user_ids:
        return 0
    try:
        rows = mongo_safe(lambda: list(mongo().fcm_tokens.find({'uid': {'$in': list(user_ids)}})),
                          fallback=[], label='device tokens')
        # The home-screen icon's badge: what the bell would show (unread Important).
        badges = {}
        sent = 0
        for row in rows:
            token = row.get('fcm_token')
            if not token:
                continue
            uid = row.get('uid')
            if uid not in badges:
                badges[uid] = mongo_safe(lambda: mongo().notifications.count_documents(
                    {'uid': uid, 'read': False, 'category': 'important'}), fallback=0, label='badge')
            try:
                # Data only: the service worker (firebase-messaging-sw.js) shows it
                # and opens `link` on a tap. With a `notification` block as well,
                # Firebase also showed its own copy (two on the phone), and its
                # fcm_options.link refuses the relative links every caller passes
                # -- each send raised and only the log knew.
                messaging.send(messaging.Message(
                    data={'title': str(title or 'Branding Gate')[:200], 'body': str(content or '')[:500],
                          'link': link or '/notifications', 'badge': str(badges[uid] or 0)},
                    webpush=messaging.WebpushConfig(headers={'Urgency': 'high', 'TTL': '86400'}),
                    token=token))
                sent += 1
            except messaging.UnregisteredError:
                mongo_safe(lambda: mongo().fcm_tokens.delete_one({'_id': row['_id']}), fallback=None, label='drop token')
            except Exception as e:
                print(f"Push failed for uid {row.get('uid')}: {e}")
        return sent
    except Exception as e:
        print(f"Push error: {e}")
        return 0


def notify_user(user_id, title, content, link=None, action=None):
    """Tell one person. Named so a caller cannot mistake it for a role."""
    return notify_users([user_id], title, content, link=link, action=action)


def notify_username(username, title, content, link=None):
    """
    Tell one person named by their username.

    sales_request_approvals.requested_by holds a username rather than an id, and
    two call sites handed it to send_notification_to_role, which looks its
    argument up as a workflow role and quietly found nobody -- so the requester
    was never told their request had been approved or rejected.
    """
    if not username:
        return 0
    conn, cur = connection()
    # The session's username is the mobile number for most people.
    cur.execute("SELECT id FROM user WHERE username = %s OR name = %s OR mobile = %s LIMIT 1",
                (username, username, username))
    row = cur.fetchone()
    cur.close()
    conn.close()
    return notify_user(row['id'], title, content, link=link) if row else 0


def send_notification_to_role(role_name, title, content, link=None, action=None):
    """
    Send notification to all users with the specified role.
    """
    try:
        return notify_users(get_users_by_role(role_name), title, content, link=link, action=action)
    except Exception as e:
        print(f"Error sending notifications to role {role_name}: {e}")
        return 0


def users_holding(permission, include_root=False):
    """
    Everyone whose role grants this permission, for telling a desk that
    something has landed on it. Audiences follow the grant matrix rather than a
    hand-kept list of role names, so a role that gains the permission later is
    told without anybody remembering to add it.

    The CEO is left out. They hold every permission, so every fan-out in the
    system landed on them -- two hundred of them, most about work they were
    never going to do. Anything genuinely theirs is sent to them by name
    through notify_user, which does not go through here.

    `include_root` is for the one case where leaving them out is wrong: when the
    audience *is* the admins, and the CEO is one. A client or supplier waiting
    on an admin signature is exactly that, and excluding them would tell
    everybody except the person most likely to sign it.
    """
    role_codes = [code for code, grants in rbac.SEED_MATRIX.items() if permission in grants]
    if not role_codes:
        return []
    conn, cur = connection()
    placeholders = ",".join(["%s"] * len(role_codes))
    cur.execute(
        "SELECT u.id FROM user u JOIN rbac_role r ON r.id = u.rbac_role_id "
        "WHERE r.code IN (%s) AND u.is_active = 1%s" % (
            placeholders, "" if include_root else " AND u.manager_id IS NOT NULL"),
        role_codes,
    )
    user_ids = [row['id'] for row in cur.fetchall()]
    # When another role holds this too, the desk is theirs: admins are on the
    # list only because the admin role holds everything.
    fyi = _admin_ids(cur, user_ids) if set(role_codes) - {'admin'} else set()

    # Extras given from People & Access: a person handed an approval should
    # also hear that something is waiting for it.
    cur.execute(
        "SELECT DISTINCT u.id FROM user u JOIN permission_grant g ON g.permission_code = %s AND "
        + _GRANT_MATCH + " WHERE u.is_active = 1"
        + ("" if include_root else " AND u.manager_id IS NOT NULL"), (permission,))
    granted = {row['id'] for row in cur.fetchall()}
    fyi -= granted
    user_ids = sorted(granted | set(user_ids))

    # Pricing is held two ways. Beside the Pricing roles there is a per-account
    # flag, and load_permissions() grants the same set to anyone carrying it --
    # so a flagged account prices and decides negotiations, and heard about
    # neither. The desk here was the roles alone, and with every Pricing role
    # account inactive that left an audience of one.
    if permission in rbac.PRICING_FLAG_PERMISSIONS:
        cur.execute(
            "SELECT id FROM user WHERE is_pricing = 1 AND is_active = 1%s"
            % ("" if include_root else " AND manager_id IS NOT NULL"))
        flagged = {row['id'] for row in cur.fetchall()}
        fyi -= flagged
        user_ids = sorted(flagged | set(user_ids))

    cur.close()
    conn.close()
    return Audience.of(user_ids, fyi)
def calculate_duration_days(start_date, end_date):
    """Calculate duration in days between two dates (inclusive)"""
    if not start_date:
        return 0
    
    # Convert string dates to date objects if needed
    if isinstance(start_date, str):
        start_date = datetime.strptime(start_date, '%Y-%m-%d').date()
    if isinstance(end_date, str) and end_date:
        end_date = datetime.strptime(end_date, '%Y-%m-%d').date()
    elif not end_date:
        end_date = start_date
    
    # Ensure end date is not before start date
    if end_date < start_date:
        return 0
    
    # Calculate inclusive days (+1 to include both start and end)
    return (end_date - start_date).days + 1

def log_request_change(request_id, action_type, action_by, field_name=None, old_value=None, new_value=None, change_description=None, conn=None, cur=None):
    """
    Log changes to sales requests in the change log table
    
    Parameters:
    - request_id: The ID of the request being changed
    - action_type: Type of action (CREATE, UPDATE, DELETE, STATUS_CHANGE, COST_UPDATE, etc.)
    - action_by: Username of the person making the change
    - field_name: Name of the field being changed (optional for CREATE/DELETE)
    - old_value: Previous value of the field (optional)
    - new_value: New value of the field (optional)
    - change_description: Human-readable description of the change (optional)
    - conn: Existing database connection (optional, creates new if not provided)
    - cur: Existing database cursor (optional, creates new if not provided)
    """
    # OPTIMIZATION: Use existing connection if provided to prevent lock contention
    own_connection = False
    try:
        if conn is None or cur is None:
            conn, cur = connection()
            own_connection = True
        
        # Get IP address from request context
        ip_address = None
        try:
            if request and hasattr(request, 'remote_addr'):
                ip_address = request.remote_addr
        except:
            pass
        
        # Convert complex values to JSON strings for storage
        if old_value and not isinstance(old_value, str):
            old_value = json.dumps(old_value) if isinstance(old_value, (dict, list)) else str(old_value)
        if new_value and not isinstance(new_value, str):
            new_value = json.dumps(new_value) if isinstance(new_value, (dict, list)) else str(new_value)
        
        # Insert log entry
        cur.execute("""
            INSERT INTO sales_request_change_log 
            (request_id, action_type, action_by, field_name, old_value, new_value, change_description, ip_address)
            VALUES (%s, %s, %s, %s, %s, %s, %s, %s)
        """, (
            request_id,
            action_type,
            action_by,
            field_name,
            old_value,
            new_value,
            change_description,
            ip_address
        ))
        
        # Only commit and close if we created our own connection
        if own_connection:
            conn.commit()
            cur.close()
            conn.close()
        
    except Exception as e:
        print(f"Error logging request change: {str(e)}")
        traceback.print_exc()

def log_item_change(request_id, item_id, item_name, request_type, action_type, action_by, old_data=None, new_data=None, change_description=None, conn=None, cur=None):
    """
    Log changes to items within a sales request using the main sales_request_change_log table
    
    Parameters:
    - request_id: The ID of the sales request
    - item_id: The ID of the item
    - item_name: Name of the item
    - request_type: Request type the item belongs to (Event, Production, etc.)
    - action_type: Type of action (ITEM_ADD, ITEM_UPDATE, ITEM_DELETE, ATTACHMENT_ADD, ATTACHMENT_REMOVE)
    - action_by: Username of the person making the change
    - old_data: Dict of old item data (for updates)
    - new_data: Dict of new item data (for adds/updates)
    - change_description: Human-readable description (auto-generated if not provided)
    - conn: Existing database connection (optional, creates new if not provided)
    - cur: Existing database cursor (optional, creates new if not provided)
    """
    try:
        # Detect individual field changes for granular logging
        field_changes = []
        if action_type == 'ITEM_UPDATE' and old_data and new_data:
            # Check all possible item fields for changes
            for field in ['name', 'qty', 'quantity', 'unit', 'description', 'comment', 'width', 'height', 'depth', 'cost_per_item', 'sell_per_item', 'total_cost', 'total_sell']:
                old_val = old_data.get(field)
                new_val = new_data.get(field)
                
                # Skip if both are None or empty
                if not old_val and not new_val:
                    continue
                    
                # Convert to string for comparison
                old_str = str(old_val) if old_val is not None else ''
                new_str = str(new_val) if new_val is not None else ''
                
                if old_str != new_str:
                    field_changes.append({
                        'field': field,
                        'old': old_val,
                        'new': new_val
                    })
        
        # If we have specific field changes, log each one separately
        if field_changes:
            for change in field_changes:
                # Format field-specific description
                field_display = change['field'].replace('_', ' ').title()
                if request_type:
                    full_desc = f"[{request_type}] Item '{item_name}': {field_display} changed from '{change['old']}' to '{change['new']}'"
                else:
                    full_desc = f"Item '{item_name}': {field_display} changed from '{change['old']}' to '{change['new']}'"
                
                # Use the main logging function WITH SAME CONNECTION
                log_request_change(
                    request_id=request_id,
                    action_type='ITEM_UPDATE',
                    action_by=action_by,
                    field_name=f"item_{item_id}_{change['field']}",
                    old_value=str(change['old']) if change['old'] is not None else None,
                    new_value=str(change['new']) if change['new'] is not None else None,
                    change_description=full_desc,
                    conn=conn,
                    cur=cur
                )
        else:
            # No specific field changes or non-UPDATE action, log as single entry
            # Auto-generate description if not provided
            if not change_description:
                if action_type == 'ITEM_ADD':
                    qty_info = f" (Qty: {new_data.get('qty', new_data.get('quantity', 'N/A'))} {new_data.get('unit', 'pcs')})" if new_data else ""
                    if request_type:
                        change_description = f"[{request_type}] Added item '{item_name}'{qty_info}"
                    else:
                        change_description = f"Added item '{item_name}'{qty_info}"
                elif action_type == 'ITEM_DELETE':
                    qty_info = f" (Qty: {old_data.get('qty', old_data.get('quantity', 'N/A'))} {old_data.get('unit', 'pcs')})" if old_data else ""
                    if request_type:
                        change_description = f"[{request_type}] Deleted item '{item_name}'{qty_info}"
                    else:
                        change_description = f"Deleted item '{item_name}'{qty_info}"
                elif action_type == 'ATTACHMENT_ADD':
                    attach_info = f" ({new_data.get('filename', 'file')})" if new_data and new_data.get('filename') else ""
                    if request_type:
                        change_description = f"[{request_type}] Added attachment{attach_info} to item '{item_name}'"
                    else:
                        change_description = f"Added attachment{attach_info} to item '{item_name}'"
                elif action_type == 'ATTACHMENT_REMOVE':
                    attach_info = f" ({old_data.get('filename', 'file')})" if old_data and old_data.get('filename') else ""
                    if request_type:
                        change_description = f"[{request_type}] Removed attachment{attach_info} from item '{item_name}'"
                    else:
                        change_description = f"Removed attachment{attach_info} from item '{item_name}'"
                else:
                    if request_type:
                        change_description = f"[{request_type}] {action_type} for item '{item_name}'"
                    else:
                        change_description = f"{action_type} for item '{item_name}'"
            
            # Convert data to JSON strings for old/new values
            # default=str: prices arrive from MySQL as Decimal, which json
            # cannot encode, and the exception below swallowed the whole entry
            # -- so a client negotiation never reached the item's Activity Flow.
            old_value = json.dumps(old_data, default=str) if old_data and len(json.dumps(old_data, default=str)) < 1000 else None
            new_value = json.dumps(new_data, default=str) if new_data and len(json.dumps(new_data, default=str)) < 1000 else None
            
            # Use the main logging function WITH SAME CONNECTION
            log_request_change(
                request_id=request_id,
                action_type=action_type,
                action_by=action_by,
                field_name=f"item_{item_id}",
                old_value=old_value,
                new_value=new_value,
                change_description=change_description,
                conn=conn,
                cur=cur
            )
        
        print(f"DEBUG: Logged item change for request {request_id}, item {item_id} ({item_name}): {action_type}")
        
    except Exception as e:
        print(f"ERROR: Failed to log item change: {str(e)}")
        traceback.print_exc()
        # Don't fail the main operation if logging fails

PASSWORD_HASH_PREFIXES = ('scrypt:', 'pbkdf2:', 'argon2')
EGYPT_MOBILE_RE = re.compile(r'^01[0125]\d{8}$')
CONTACT_PHONE_FIELDS = frozenset((
    'mobile', 'mobile_number', 'secondary_mobile_number', 'primary_phone',
    'secondary_phone', 'whatsapp_number', 'phone_number', 'contact_phone',
))
CONTACT_EMAIL_FIELDS = frozenset(('email', 'email_address', 'contact_email'))
EMAIL_RE = re.compile(r'^[^@\s]+@[^@\s]+\.[^@\s]+$')


def normalize_egypt_mobile(value, label='Mobile', required=True):
    text = '' if value is None else str(value).strip()
    text = re.sub(r'[\s\-\(\)\.]', '', text)
    if text.startswith('+'):
        text = text[1:]
    if text.startswith('0020'):
        text = '0' + text[4:]
    elif text.startswith('20') and len(text) == 12:
        text = '0' + text[2:]
    elif text.startswith('1') and len(text) == 10:
        text = '0' + text
    if not text:
        if required:
            raise ValueError('%s is required' % label)
        return ''
    if not EGYPT_MOBILE_RE.match(text):
        raise ValueError('%s must be a valid Egyptian mobile number' % label)
    return text


def normalize_email(value, label='Email', required=True):
    text = '' if value is None else str(value).strip().lower()
    if not text:
        if required:
            raise ValueError('%s is required' % label)
        return ''
    if not EMAIL_RE.match(text):
        raise ValueError('%s must be a valid email address' % label)
    return text


def _normalize_contact_fields(data, phone_fields=(), email_fields=(),
                              required_phone_fields=(), required_email_fields=()):
    normalized = dict(data or {})
    required_phone_fields = set(required_phone_fields)
    required_email_fields = set(required_email_fields)
    for field in set(phone_fields) | required_phone_fields:
        if field in normalized or field in required_phone_fields:
            normalized[field] = normalize_egypt_mobile(
                normalized.get(field), field.replace('_', ' ').title(),
                field in required_phone_fields)
    for field in set(email_fields) | required_email_fields:
        if field in normalized or field in required_email_fields:
            normalized[field] = normalize_email(
                normalized.get(field), field.replace('_', ' ').title(),
                field in required_email_fields)
    return normalized


def verify_password(user, password, conn, cur):
    """
    Check a submitted password against the stored value.
    Rows still holding a legacy plaintext password are upgraded to a hash
    on the first successful login, so no flag day is needed.
    """
    stored = user.get('password') or ''
    if stored.startswith(PASSWORD_HASH_PREFIXES):
        return check_password_hash(stored, password)
    if not password or stored != password:
        return False
    cur.execute(
        "UPDATE user SET password = %s WHERE id = %s",
        (generate_password_hash(password), user['id'])
    )
    conn.commit()
    return True


@app.route('/login', methods=['GET', 'POST'])
@app.route('/', methods=['GET', 'POST'])
def login():
    if request.method == "POST" and "add_login" in request.args:
        mobile     = request.form.get("mobile")      # we treat username as phone
        password  = request.form.get("password")
        try:
            mobile = normalize_egypt_mobile(mobile)
        except ValueError:
            return jsonify(
                state   = "error",
                message = "Invalid username or password"
            )
        # — 1) Verify your own MySQL user/password —
        # mobile is UNIQUE on user, so this returns at most one row.
        conn, cur = connection()
        exist=cur.execute("SELECT * FROM user WHERE mobile = %s", (mobile,))
        user = cur.fetchone() if int(exist) == 1 else None
        if user is None or not verify_password(user, password, conn, cur):
            cur.close()
            conn.close()
            return jsonify(
                state   = "error",
                message = "Invalid username or password"
            )
        # A disabled account keeps its place in the reporting line and loses
        # only this. Checked after the password so the answer does not tell an
        # outsider which mobile numbers exist.
        if not user.get('is_active', 1):
            cur.close()
            conn.close()
            return jsonify(
                state   = "error",
                message = "This account has been disabled. Ask an administrator."
            )
        cur.close()
        conn.close()
        # user is now a dict, use column names
        session.permanent = True
        session['user_id'] = user['id']
        session['mobile'] = user['mobile']
        session['email'] = user['email']
        session['username'] = user['username']
        session['name'] = user['name']
        session['team_id'] = user['team_id']
        session['title'] = user['title']
        # Use the new function to get roles
        session['roles'] = get_user_roles(user['id'])
        # RBAC: permission set and role code, refreshed by /api/refresh-roles.
        session['perms'], session['role_code'] = load_permissions(user['id'])
        session['perms_loaded_at'] = datetime.now().isoformat()
        # The first page after signing in offers to turn on notifications.
        session['ask_push'] = True
        # — 2) Ensure a Firebase Auth user exists for this phone number —
        fb_mobile = "+20" + user['mobile'].lstrip('0')  # Ensure all leading zeros are stripped
        # Validate Egyptian phone number (E.164: +20XXXXXXXXXX)
        def is_valid_egyptian_phone(phone):
            return re.match(r'^\+201[0-9]{9}$', phone) is not None
        if not is_valid_egyptian_phone(fb_mobile):
            return jsonify(state="error", message="Invalid phone number format for Firebase"), 400
        try:
            fb_user = auth.get_user_by_phone_number(fb_mobile)
        except auth.UserNotFoundError:
            # Create a new Firebase user with this phone as UID
            fb_user = auth.create_user(
                uid         = fb_mobile,
                phone_number= fb_mobile
            )
        # — 4) Mint a Firebase Custom Token so the client can sign in —
        custom_token = auth.create_custom_token(fb_user.uid).decode("utf-8")
        session['fb_uid'] = fb_user.uid  # Store Firebase UID in session
        session['token'] = custom_token
        session['fb_mobile'] = fb_mobile  # Store Firebase token in session
        # — 3) Optionally, store the phone number in the Firebase user profile —
        # — 5) Return success, the custom token, and any redirect info —
        return jsonify(
            state          = "success",
            message        = "Login successful",
            firebase_token = custom_token,
            redirect       = url_for("home")    # or wherever
        )
    # GET → render the login page
    return render_template("login.html")





@app.route('/api/push/register', methods=['POST'])
def register_push_token():
    """The browser's FCM token for this person, one row per device."""
    if 'user_id' not in session:
        return jsonify(success=False, error='Not authenticated'), 401
    token = ((request.get_json(silent=True) or {}).get('token') or '').strip()
    if len(token) < 20:
        return jsonify(success=False, error='No token'), 400
    doc = {'uid': int(session['user_id']), 'phone_number': session.get('mobile'), 'email': session.get('email'),
           'fcm_token': token, 'updated_at': datetime.now(), 'agent': (request.user_agent.string or '')[:200]}
    mongo_safe(lambda: mongo().fcm_tokens.update_one({'fcm_token': token}, {'$set': doc}, upsert=True),
               fallback=None, label='register push')
    return jsonify(success=True)


@app.route('/api/push/unregister', methods=['POST'])
def unregister_push_token():
    token = ((request.get_json(silent=True) or {}).get('token') or '').strip()
    if token:
        mongo_safe(lambda: mongo().fcm_tokens.delete_one({'fcm_token': token}), fallback=None, label='unregister push')
    return jsonify(success=True)


