@app.route('/api/users', methods=['GET'])
@perm('user.view')
def get_users():
    """API endpoint to fetch users data from MySQL"""
    if 'user_id' not in session:
        return jsonify(error="Not authenticated"), 401

    try:
        conn, cur = connection()

        # Passwords are never returned to the client.
        cur.execute("""
            SELECT u.id, u.mobile, u.email, u.date, u.name, u.modified_date, u.added_by, u.username, u.title,
                   u.department_id, u.rbac_role_id, u.manager_id, u.is_pricing, u.is_active,
                   u.reports_to_vacancy_id,
                   d.name AS rbac_department_name, d.code AS rbac_department_code,
                   r.code AS role_code, r.name AS role_name, r.level AS role_level,
                   m.name AS manager_name
            FROM user u
            LEFT JOIN department d ON d.id = u.department_id
            LEFT JOIN rbac_role r ON r.id = u.rbac_role_id
            LEFT JOIN user m ON m.id = u.manager_id
            ORDER BY u.id DESC
        """)
        users_data = cur.fetchall()
        # Convert to list of dictionaries for JSON response
        users_list = []
        for user in users_data:
            users_list.append({
                'id': user['id'],
                'mobile': user['mobile'],
                'email': user['email'],
                'name': user['name'],
                'date': user['date'].strftime('%Y-%m-%d %H:%M:%S') if user['date'] else 'N/A',
                'modified_date': user['modified_date'].strftime('%Y-%m-%d %H:%M:%S') if user['modified_date'] else 'N/A',
                'added_by': user['added_by'],
                'username': user['username'],
                'title': user['title'],
                # RBAC hierarchy
                'department_id': user['department_id'],
                'rbac_department_name': user['rbac_department_name'],
                'rbac_department_code': user['rbac_department_code'],
                'rbac_role_id': user['rbac_role_id'],
                'role_code': user['role_code'],
                'role_name': user['role_name'],
                'role_level': user['role_level'],
                'manager_id': user['manager_id'],
                'manager_name': user['manager_name'],
                'is_pricing': bool(user['is_pricing']),
                'is_active': bool(user['is_active']),
                'reports_to_vacancy_id': user['reports_to_vacancy_id'],
            })
        cur.close()
        conn.close()
        return jsonify({
            'success': True,
            'users': users_list
        })
    except Exception as e:
        print(e)
        return jsonify({
            'success': False,
            'error': str(e)
        }), 500

@app.route('/api/users/add', methods=['POST'])
@perm('user.create')
def add_user():
    """API endpoint to add a new user"""
    if 'user_id' not in session:
        return jsonify(error="Not authenticated"), 401
    
    try:
        data = request.get_json() or {}
        try:
            data = _normalize_contact_fields(
                data,
                required_phone_fields=('mobile',),
                required_email_fields=('email',),
            )
        except ValueError as e:
            return jsonify({'success': False, 'error': str(e)}), 400
        
        # Validate required fields
        required_fields = ['name', 'mobile', 'email', 'password', 'username', 'title']
        for field in required_fields:
            if not data.get(field):
                return jsonify({
                    'success': False,
                    'error': f'Missing required field: {field}'
                }), 400
        print(data.get('team_id'))
        conn, cur = connection()
        
        # Check if mobile already exists
        cur.execute("SELECT id FROM user WHERE mobile = %s", (data['mobile'],))
        if cur.fetchone():
            return jsonify({
                'success': False,
                'error': 'Mobile number already exists'
            }), 400
            
        # Check if email already exists
        cur.execute("SELECT id FROM user WHERE email = %s", (data['email'],))
        if cur.fetchone():
            return jsonify({
                'success': False,
                'error': 'Email already exists'
            }), 400
        
        # Check if username already exists
        cur.execute("SELECT id FROM user WHERE username = %s", (data['username'],))
        if cur.fetchone():
            return jsonify({
                'success': False,
                'error': 'Username already exists'
            }), 400
        
        # Convert team_id to int or None
        team_id = data.get('team_id')
        if team_id in [None, '', 'undefined']:
            team_id = None
        else:
            try:
                team_id = int(team_id)
            except Exception:
                team_id = None
        
        # RBAC hierarchy: department, role and reporting line.
        hierarchy, hierarchy_error = _hierarchy_fields(data)
        if hierarchy_error:
            return jsonify({'success': False, 'error': hierarchy_error}), 400
        validation_error = _validate_hierarchy(cur, hierarchy)
        if validation_error:
            return jsonify({'success': False, 'error': validation_error}), 400

        # Insert new user with username, title, and team_id
        cur.execute("""
            INSERT INTO user (name, mobile, email, password, username, title, team_id, date, added_by)
            VALUES (%s, %s, %s, %s, %s, %s, %s, NOW(), %s)
        """, (
            data['name'],
            data['mobile'],
            data['email'],
            generate_password_hash(data['password']),
            data['username'],
            data['title'],
            team_id,
            session['username']
        ))
        
        conn.commit()
        
        # Get the new user's ID
        new_user_id = cur.lastrowid

        if hierarchy:
            assignments = ", ".join("%s = %%s" % key for key in hierarchy)
            cur.execute(
                "UPDATE user SET %s WHERE id = %%s" % assignments,
                list(hierarchy.values()) + [new_user_id]
            )
            conn.commit()

        cur.close()
        conn.close()
        
        return jsonify({
            'success': True,
            'message': 'User added successfully'
        })
    except Exception as e:
        return jsonify({
            'success': False,
            'error': str(e)
        }), 500

@app.route('/api/users/<int:user_id>/active', methods=['POST'])
@perm('user.edit')
def set_user_active(user_id):
    """
    Turn an account on or off without touching where it sits.

    Disabling is what to do instead of deleting: people report to this person,
    scopes are computed from them, and removing the row would move everybody
    underneath. The login is refused; the tree is untouched.
    """
    try:
        data = request.get_json(silent=True) or {}
        active = 1 if data.get('active') else 0
        if user_id == session.get('user_id') and not active:
            return jsonify(success=False,
                           error='You cannot disable your own account'), 400
        conn, cur = connection()
        cur.execute("SELECT manager_id FROM user WHERE id = %s", (user_id,))
        row = cur.fetchone()
        if not row:
            cur.close()
            conn.close()
            return jsonify(success=False, error='No such user'), 404
        if row['manager_id'] is None and not active:
            cur.close()
            conn.close()
            return jsonify(success=False,
                           error='The root of the tree cannot be disabled'), 400
        cur.execute("UPDATE user SET is_active = %s WHERE id = %s", (active, user_id))
        conn.commit()
        cur.close()
        conn.close()
        return jsonify(success=True, is_active=bool(active))
    except HTTPException:
        raise
    except Exception as e:
        print("DEBUG: set user active failed: %s" % e)
        return jsonify(success=False, error=str(e)), 500


@app.route('/api/users/delete/<int:user_id>', methods=['DELETE'])
@perm('user.delete')
def delete_user(user_id):
    """API endpoint to delete a user"""
    if 'user_id' not in session:
        return jsonify(error="Not authenticated"), 401
    
    try:
        conn, cur = connection()
        
        # Check if user exists
        cur.execute("SELECT id FROM user WHERE id = %s", (user_id,))
        if not cur.fetchone():
            return jsonify({
                'success': False,
                'error': 'User not found'
            }), 404

        # Nobody may delete their own account, and user 1 is the recovery account.
        if user_id == session.get('user_id') or user_id == 1:
            return jsonify({
                'success': False,
                'error': 'This account cannot be deleted'
            }), 400

        # Delete user
        cur.execute("DELETE FROM user WHERE id = %s", (user_id,))
        conn.commit()
        
        cur.close()
        conn.close()
        
        return jsonify({
            'success': True,
            'message': 'User deleted successfully'
        })
        
    except Exception as e:
        return jsonify({
            'success': False,
            'error': str(e)
        }), 500

@app.route('/api/users/edit/<int:user_id>', methods=['POST'])
@perm('user.edit')
def edit_user(user_id):
    """API endpoint to edit an existing user"""
    if 'user_id' not in session:
        return jsonify(error="Not authenticated"), 401

    try:
        data = request.get_json() or {}
        try:
            data = _normalize_contact_fields(
                data,
                required_phone_fields=('mobile',),
                required_email_fields=('email',),
            )
        except ValueError as e:
            return jsonify({'success': False, 'error': str(e)}), 400

        # Validate required fields
        required_fields = ['name', 'mobile', 'email', 'username', 'title']
        for field in required_fields:
            if not data.get(field):
                return jsonify({
                    'success': False,
                    'error': f'Missing required field: {field}'
                }), 400

        conn, cur = connection()

        # Check for duplicate mobile number
        cur.execute("SELECT id FROM user WHERE mobile = %s AND id != %s", (data['mobile'], user_id))
        if cur.fetchone():
            return jsonify({
                'success': False,
                'error': 'Mobile number already exists'
            }), 400

        # Check for duplicate email
        cur.execute("SELECT id FROM user WHERE email = %s AND id != %s", (data['email'], user_id))
        if cur.fetchone():
            return jsonify({
                'success': False,
                'error': 'Email already exists'
            }), 400

        # Check for duplicate username
        cur.execute("SELECT id FROM user WHERE username = %s AND id != %s", (data['username'], user_id))
        if cur.fetchone():
            return jsonify({
                'success': False,
                'error': 'Username already exists'
            }), 400

        # Update user details
        cur.execute("""
            UPDATE user
            SET name = %s, mobile = %s, email = %s, username = %s, title = %s,
                modified_date = NOW(), modified_by = %s
            WHERE id = %s
        """, (
            data['name'],
            data['mobile'],
            data['email'],
            data['username'],
            data['title'],
            session['username'],
            user_id
        ))

        # RBAC hierarchy, same rule: only keys the client actually sent are applied.
        hierarchy, hierarchy_error = _hierarchy_fields(data)
        if hierarchy_error:
            return jsonify({'success': False, 'error': hierarchy_error}), 400
        validation_error = _validate_hierarchy(cur, hierarchy, user_id=user_id)
        if validation_error:
            return jsonify({'success': False, 'error': validation_error}), 400
        if hierarchy:
            assignments = ", ".join("%s = %%s" % key for key in hierarchy)
            cur.execute(
                "UPDATE user SET %s WHERE id = %%s" % assignments,
                list(hierarchy.values()) + [user_id]
            )

        # team_id is only touched when the client actually sends the key, so an
        # edit form that omits it does not silently unassign the user's team.
        if 'team_id' in data:
            team_id = data.get('team_id')
            if team_id in [None, '', 'undefined']:
                team_id = None
            else:
                try:
                    team_id = int(team_id)
                except Exception:
                    team_id = None
            cur.execute("UPDATE user SET team_id = %s WHERE id = %s", (team_id, user_id))

        # The password field is optional on edit; an empty value leaves it unchanged.
        new_password = (data.get('password') or '').strip()
        if new_password:
            cur.execute(
                "UPDATE user SET password = %s WHERE id = %s",
                (generate_password_hash(new_password), user_id)
            )

        conn.commit()
        cur.close()
        conn.close()

        return jsonify({
            'success': True,
            'message': 'User updated successfully'
        })
    except Exception as e:
        return jsonify({
            'success': False,
            'error': str(e)
        }), 500

