@app.route('/api/rbac/permissions', methods=['GET'])
@perm('role.view')
def list_rbac_permissions():
    """The permission vocabulary, for the extra-permission picker."""
    return jsonify(success=True, permissions=[
        {'code': code, 'description': text, 'scopeless': code in rbac.SCOPELESS_PERMISSIONS}
        for code, text in sorted(rbac.PERMISSIONS.items())])


def _permission_grants(cur, target_type=None, target_id=None):
    where, params = '', ()
    if target_type:
        where, params = ' WHERE g.target_type = %s AND g.target_id = %s', (target_type, target_id)
    cur.execute("""
        SELECT g.id, g.target_type, g.target_id, g.permission_code, g.scope, g.granted_at,
               p.description,
               CASE g.target_type
                    WHEN 'role' THEN (SELECT name FROM rbac_role WHERE id = g.target_id)
                    WHEN 'department' THEN (SELECT name FROM department WHERE id = g.target_id)
                    ELSE (SELECT name FROM user WHERE id = g.target_id) END AS target_name,
               (SELECT name FROM user WHERE id = g.granted_by) AS granted_by_name
        FROM permission_grant g
        JOIN permission p ON p.code = g.permission_code""" + where + """
        ORDER BY g.target_type, target_name, g.permission_code""", params)
    rows = cur.fetchall()
    for row in rows:
        row['granted_at'] = row['granted_at'].strftime('%Y-%m-%d %H:%M') if row['granted_at'] else None
    return rows


@app.route('/api/rbac/grants', methods=['GET'])
@perm('role.view')
def list_permission_grants():
    """Extra permissions, all of them or one target's."""
    target_type = request.args.get('target_type') or None
    if target_type and target_type not in GRANT_TARGETS:
        return jsonify(success=False, error='Unknown target'), 400
    conn, cur = connection()
    try:
        return jsonify(success=True, grants=_permission_grants(
            cur, target_type, request.args.get('target_id', type=int)))
    finally:
        cur.close()
        conn.close()


@app.route('/api/rbac/grants', methods=['POST'])
@perm('role.grant')
def add_permission_grant():
    """
    Give a role, department, team or person one extra permission. Granting
    the same permission again changes its scope rather than adding a row.
    """
    data = request.get_json(silent=True) or {}
    target_type = data.get('target_type')
    permission_code = data.get('permission_code')
    scope = data.get('scope') or 'all'
    try:
        target_id = int(data.get('target_id'))
    except (TypeError, ValueError):
        return jsonify(success=False, error='Pick who gets it'), 400
    if target_type not in GRANT_TARGETS:
        return jsonify(success=False, error='Unknown target'), 400
    if permission_code not in rbac.PERMISSIONS:
        return jsonify(success=False, error='Unknown permission'), 400
    if permission_code in rbac.SCOPELESS_PERMISSIONS:
        scope = 'all'
    if scope not in rbac.SCOPES:
        return jsonify(success=False, error='Unknown scope'), 400

    table = {'role': 'rbac_role', 'department': 'department'}.get(target_type, 'user')
    conn, cur = connection()
    try:
        cur.execute("SELECT id FROM " + table + " WHERE id = %s", (target_id,))
        if not cur.fetchone():
            return jsonify(success=False, error='Not found'), 404
        cur.execute("""
            INSERT INTO permission_grant (target_type, target_id, permission_code, scope, granted_by)
            VALUES (%s, %s, %s, %s, %s)
            ON DUPLICATE KEY UPDATE scope = VALUES(scope), granted_by = VALUES(granted_by),
                                    granted_at = NOW()
        """, (target_type, target_id, permission_code, scope, session.get('user_id')))
        conn.commit()
        app.logger.info('User %s granted %s (%s) to %s %s', session.get('user_id'),
                        permission_code, scope, target_type, target_id)
        return jsonify(success=True, grants=_permission_grants(cur, target_type, target_id))
    finally:
        cur.close()
        conn.close()


@app.route('/api/rbac/grants/<int:grant_id>', methods=['DELETE'])
@perm('role.grant')
def remove_permission_grant(grant_id):
    conn, cur = connection()
    try:
        cur.execute("DELETE FROM permission_grant WHERE id = %s", (grant_id,))
        conn.commit()
        if not cur.rowcount:
            return jsonify(success=False, error='Not found'), 404
        app.logger.info('User %s removed permission grant %s', session.get('user_id'), grant_id)
        return jsonify(success=True)
    finally:
        cur.close()
        conn.close()


# ---- vacant positions -------------------------------------------------------
# A box on the org chart that nobody holds yet. People can sit under one
# (user.reports_to_vacancy_id); their manager_id stays the nearest real person
# above it, because approval chains and scopes need a person.

def vacancy_manager(cur, vacancy_id):
    """The nearest real person above this vacant position, or None."""
    seen = set()
    while vacancy_id and vacancy_id not in seen:
        seen.add(vacancy_id)
        cur.execute("SELECT parent_user_id, parent_vacancy_id FROM org_vacancy WHERE id = %s", (vacancy_id,))
        row = cur.fetchone()
        if not row:
            return None
        if row['parent_user_id']:
            return row['parent_user_id']
        vacancy_id = row['parent_vacancy_id']
    return None


def _vacancies(cur):
    cur.execute("""SELECT v.id, v.title, v.rbac_role_id, v.department_id, v.parent_user_id, v.parent_vacancy_id,
                          r.name AS role_name, r.level AS role_level, d.name AS department_name
                   FROM org_vacancy v JOIN rbac_role r ON r.id = v.rbac_role_id
                   LEFT JOIN department d ON d.id = v.department_id
                   ORDER BY r.level, v.title""")
    return list(cur.fetchall())


@app.route('/api/org/vacancies', methods=['GET'])
@perm('user.view')
def list_vacancies():
    conn, cur = connection()
    try:
        return jsonify(success=True, vacancies=_vacancies(cur))
    finally:
        cur.close()
        conn.close()


@app.route('/api/org/vacancies', methods=['POST'])
@perm('user.create')
def add_vacancy():
    """A position nobody holds yet: role, department, and who or what it sits under."""
    data = request.get_json(silent=True) or {}
    try:
        role_id = int(data.get('rbac_role_id'))
    except (TypeError, ValueError):
        return jsonify(success=False, error='Pick the role of the position'), 400
    department_id = data.get('department_id') or None
    reports_to = str(data.get('reports_to') or '')
    parent_user_id = parent_vacancy_id = None
    if reports_to.startswith('v:'):
        parent_vacancy_id = int(reports_to[2:])
    elif reports_to:
        parent_user_id = int(reports_to)
    conn, cur = connection()
    try:
        cur.execute("SELECT name, level, department_id FROM rbac_role WHERE id = %s", (role_id,))
        role = cur.fetchone()
        if not role:
            return jsonify(success=False, error='Unknown role'), 400
        parent_level = None
        if parent_vacancy_id:
            cur.execute("""SELECT r.level FROM org_vacancy v JOIN rbac_role r ON r.id = v.rbac_role_id
                           WHERE v.id = %s""", (parent_vacancy_id,))
            row = cur.fetchone()
            if not row:
                return jsonify(success=False, error='Unknown vacant position'), 400
            parent_level = row['level']
        elif parent_user_id:
            cur.execute("""SELECT r.level FROM user u JOIN rbac_role r ON r.id = u.rbac_role_id
                           WHERE u.id = %s""", (parent_user_id,))
            row = cur.fetchone()
            if not row:
                return jsonify(success=False, error='Unknown manager'), 400
            parent_level = row['level']
        if parent_level is not None and parent_level >= role['level']:
            return jsonify(success=False, error='It must sit under someone more senior'), 400
        title = (data.get('title') or '').strip() or role['name']
        cur.execute("""INSERT INTO org_vacancy (rbac_role_id, department_id, title, parent_user_id,
                                                parent_vacancy_id, created_by)
                       VALUES (%s, %s, %s, %s, %s, %s)""",
                    (role_id, department_id or role['department_id'], title[:120], parent_user_id,
                     parent_vacancy_id, session.get('user_id')))
        conn.commit()
        return jsonify(success=True, id=cur.lastrowid)
    finally:
        cur.close()
        conn.close()


@app.route('/api/org/vacancies/<int:vacancy_id>', methods=['DELETE'])
@perm('user.edit')
def remove_vacancy(vacancy_id):
    """Take a position off the chart; whatever sat under it moves up a level."""
    conn, cur = connection()
    try:
        cur.execute("SELECT * FROM org_vacancy WHERE id = %s", (vacancy_id,))
        seat = cur.fetchone()
        if not seat:
            return jsonify(success=False, error='Not found'), 404
        cur.execute("UPDATE user SET reports_to_vacancy_id = %s WHERE reports_to_vacancy_id = %s",
                    (seat['parent_vacancy_id'], vacancy_id))
        cur.execute("""UPDATE org_vacancy SET parent_vacancy_id = %s, parent_user_id = %s
                       WHERE parent_vacancy_id = %s""",
                    (seat['parent_vacancy_id'], seat['parent_user_id'], vacancy_id))
        cur.execute("DELETE FROM org_vacancy WHERE id = %s", (vacancy_id,))
        conn.commit()
        return jsonify(success=True)
    finally:
        cur.close()
        conn.close()


@app.route('/api/org/vacancies/<int:vacancy_id>/fill', methods=['POST'])
@perm('user.edit')
def fill_vacancy(vacancy_id):
    """
    Put a person in the seat: they take its role, department and place, and
    the people and empty seats under it now sit under them.
    """
    try:
        user_id = int((request.get_json(silent=True) or {}).get('user_id'))
    except (TypeError, ValueError):
        return jsonify(success=False, error='Pick the person'), 400
    conn, cur = connection()
    try:
        cur.execute("SELECT * FROM org_vacancy WHERE id = %s", (vacancy_id,))
        seat = cur.fetchone()
        if not seat:
            return jsonify(success=False, error='Not found'), 404
        cur.execute("SELECT id, is_active FROM user WHERE id = %s", (user_id,))
        person = cur.fetchone()
        if not person or not person['is_active']:
            return jsonify(success=False, error='Pick an active person'), 400
        cur.execute("""UPDATE user SET rbac_role_id = %s, department_id = COALESCE(%s, department_id),
                                       manager_id = %s, reports_to_vacancy_id = %s, modified_date = NOW()
                       WHERE id = %s""",
                    (seat['rbac_role_id'], seat['department_id'], vacancy_manager(cur, vacancy_id),
                     seat['parent_vacancy_id'], user_id))
        cur.execute("""UPDATE user SET manager_id = %s, reports_to_vacancy_id = NULL
                       WHERE reports_to_vacancy_id = %s AND id <> %s""", (user_id, vacancy_id, user_id))
        cur.execute("""UPDATE org_vacancy SET parent_user_id = %s, parent_vacancy_id = NULL
                       WHERE parent_vacancy_id = %s""", (user_id, vacancy_id))
        cur.execute("DELETE FROM org_vacancy WHERE id = %s", (vacancy_id,))
        conn.commit()
        return jsonify(success=True)
    finally:
        cur.close()
        conn.close()


@app.route('/api/org-chart/pdf', methods=['GET'])
@perm('user.view')
def export_org_chart_pdf():
    """
    Draw the organisation chart as a PDF.

    Printing the CSS chart from the browser either shrank it to a quarter size
    or dropped the connectors, because both are at the mercy of the print
    pipeline. org_chart_pdf lays it out and strokes the lines itself.
    """
    try:
        conn, cur = connection()
        cur.execute("""
            SELECT u.id, u.name, u.manager_id, u.is_pricing, u.reports_to_vacancy_id,
                   r.name AS role_name, r.level AS role_level,
                   d.name AS rbac_department_name
            FROM user u
            LEFT JOIN rbac_role r ON r.id = u.rbac_role_id
            LEFT JOIN department d ON d.id = u.department_id
            WHERE u.is_active = 1
            ORDER BY r.level, u.name
        """)
        people = list(cur.fetchall())
        # Empty seats are boxes too; whoever sits under one hangs from it.
        for person in people:
            if person['reports_to_vacancy_id']:
                person['manager_id'] = 'v%d' % person['reports_to_vacancy_id']
        for seat in _vacancies(cur):
            people.append({'id': 'v%d' % seat['id'], 'name': 'Vacant', 'vacant': True,
                           'manager_id': ('v%d' % seat['parent_vacancy_id']) if seat['parent_vacancy_id']
                                         else seat['parent_user_id'],
                           'role_name': seat['title'], 'role_level': seat['role_level'],
                           'rbac_department_name': seat['department_name']})
        cur.execute("SELECT COUNT(*) AS n FROM department")
        departments = cur.fetchone()['n']
        cur.close()
        conn.close()

        subtitle = '%d people  ·  %d departments  ·  %s' % (
            sum(1 for p in people if not p.get('vacant')), departments, datetime.now().strftime('%d %B %Y'))
        pdf = org_chart_pdf.build(people, subtitle=subtitle)

        response = make_response(pdf)
        response.headers['Content-Type'] = 'application/pdf'
        response.headers['Content-Disposition'] = \
            'attachment; filename="organisation-chart.pdf"'
        return response
    except HTTPException:
        raise
    except Exception as e:
        print("DEBUG: org chart PDF failed: %s" % e)
        return jsonify(success=False, error=str(e)), 500


# ---------------------------------------------------------------------------
# Sales targets
#
# The CEO gives the Sales Head a number, the Sales Head splits it across their
# team leaders, each leader splits their slice across their members. Splits are
# free-form: 200,000 and 800,000 out of 1,000,000 is the intended shape, and a
# remainder may be left unassigned. The arithmetic and the invariants live in
# targets.py; these routes only fetch, authorise and persist.
#
# Who may see what falls out of the existing scope machinery: target.view is
# held at 'own' by a member, 'team' by a team leader and 'department' by the
# Sales Head. Who may *set* a number is narrower than scope and is checked
# here: only the person's own manager, or an unrestricted holder.
# ---------------------------------------------------------------------------

def _target_period(raw):
    """Validate a requested period, falling back to the current quarter."""
    if not raw:
        return targets_lib.current_period()
    targets_lib.parse_period(raw)      # raises InvalidPeriod
    return raw.strip().upper()


def _target_people(cur):
    """
    Everyone, with their reporting line, role and the team they lead.

    The whole table is 38 rows, so it is cheaper to read it once and build the
    tree in Python than to walk it with a recursive query per request.
    """
    cur.execute("""
        SELECT u.id, u.name, u.manager_id,
               r.name AS role_name, r.code AS role_code,
               t.team_name
        FROM user u
        LEFT JOIN rbac_role r ON r.id = u.rbac_role_id
        LEFT JOIN team t ON t.leader_id = u.id
        WHERE u.is_active = 1
           OR EXISTS (SELECT 1 FROM sales_target st WHERE st.user_id = u.id)
           OR EXISTS (SELECT 1 FROM sales_request sr WHERE sr.owner_user_id = u.id)
    """)
    # A switched-off account is left out (Gamal saw "Account Team Leader 2 -- 0
    # of no target", a placeholder, beside Sarah), unless it ever had a target
    # or owned a request: someone who left keeps their numbers in the totals.
    return list(cur.fetchall())


def _target_amounts(cur, period):
    """{user_id: amount} for one quarter."""
    cur.execute("SELECT user_id, amount FROM sales_target WHERE period = %s", (period,))
    return {row['user_id']: row['amount'] for row in cur.fetchall()}


def _target_details(cur, period):
    """
    {user_id: {'set_by', 'set_on'}} — who put the number there and when.

    The cascade is only auditable if each step names its author, so the page and
    the PDF both carry it rather than showing a number from nowhere.
    """
    cur.execute("""
        SELECT t.user_id, t.modified_date, u.name AS set_by
        FROM sales_target t
        LEFT JOIN user u ON u.id = t.assigned_by
        WHERE t.period = %s
    """, (period,))
    return {
        row['user_id']: {
            'set_by': row['set_by'],
            'set_on': row['modified_date'].strftime('%d %b %Y') if row['modified_date'] else None,
        }
        for row in cur.fetchall()
    }


def _target_achieved(cur, period):
    """
    {user_id: approved sell value} for the quarter.

    Attribution is by request date, not by the date the client signed off:
    sales_added_date is null on most rows, and created_at is the only date
    every request carries.
    """
    start, end = targets_lib.period_bounds(period)
    cur.execute("""
        SELECT owner_user_id, COALESCE(SUM(total_sell), 0) AS total
        FROM sales_request
        WHERE approval_status = 'approved'
          AND owner_user_id IS NOT NULL
          AND DATE(created_at) BETWEEN %s AND %s
        GROUP BY owner_user_id
    """, (start, end))
    return {row['owner_user_id']: (row['total'] or targets_lib.ZERO)
            for row in cur.fetchall()}


def _target_achieved_by_quarter(cur, year):
    """{'2026-Q1': {user_id: total}, ...} in one pass over the year."""
    cur.execute("""
        SELECT owner_user_id, QUARTER(created_at) AS q,
               COALESCE(SUM(total_sell), 0) AS total
        FROM sales_request
        WHERE approval_status = 'approved'
          AND owner_user_id IS NOT NULL
          AND YEAR(created_at) = %s
        GROUP BY owner_user_id, QUARTER(created_at)
    """, (year,))
    out = {'%d-Q%d' % (year, q): {} for q in (1, 2, 3, 4)}
    for row in cur.fetchall():
        out['%d-Q%d' % (year, row['q'])][row['owner_user_id']] = (
            row['total'] or targets_lib.ZERO)
    return out


def _target_amounts_for(cur, periods):
    """{period: {user_id: amount}} for several quarters at once."""
    placeholders = ','.join(['%s'] * len(periods))
    cur.execute(
        "SELECT user_id, period, amount FROM sales_target WHERE period IN (%s)"
        % placeholders, list(periods))
    out = {p: {} for p in periods}
    for row in cur.fetchall():
        out[row['period']][row['user_id']] = row['amount']
    return out


def _money_out(value):
    """Decimal is not JSON. Send a number, or null when there is no target."""
    return None if value is None else float(value)


@app.route('/targets', methods=['GET'])
@perm('target.view')
def targets_page():
    """The target cascade for one quarter."""
    if 'user_id' not in session:
        return redirect(url_for('login'))
    return render_template("targets.html")


@app.route('/api/targets', methods=['GET'])
@perm('target.view')
def get_targets():
    """The rows the caller may see, in reporting order, with their numbers."""
    try:
        period = _target_period(request.args.get('period'))
    except targets_lib.InvalidPeriod as e:
        return jsonify(success=False, error=str(e)), 400

    try:
        visible = visible_user_ids('target.view')
        me = session.get('user_id')
        can_assign_all = rbac.resolve(session.get('perms') or {}, 'target.assign') == 'all'
        can_name_teams = has('team.edit')

        conn, cur = connection()
        people = _target_people(cur)
        amounts = _target_amounts(cur, period)
        details = _target_details(cur, period)
        achieved = _target_achieved(cur, period)
        cur.close()
        conn.close()

        rows = targets_lib.build_tree(people, amounts, achieved, visible_ids=visible)
        by_id = {p['id']: p for p in people}
        out = []
        for row in rows:
            person = by_id.get(row['id'], {})
            detail = details.get(row['id']) or {}
            # Scope decides what you read; the reporting line decides what you
            # set. An unrestricted holder is not bound by the second rule.
            assignable = can_assign_all or person.get('manager_id') == me
            out.append({
                'id': row['id'],
                'name': row['name'],
                'role_name': row['role_name'],
                'role_code': person.get('role_code'),
                'team_name': row['team_name'],
                # Only when the manager is visible too, so a row whose manager is
                # out of scope is a root of the caller's own tree.
                'manager_id': (person.get('manager_id')
                               if visible is None or person.get('manager_id') in (visible or [])
                               else None),
                'depth': row['depth'],
                'is_leader': row['is_leader'],
                'target': _money_out(row['target']),
                'assigned': _money_out(row['assigned']),
                'unassigned': _money_out(row['unassigned']),
                'own_achieved': _money_out(row['own_achieved']),
                'team_achieved': _money_out(row['team_achieved']),
                'progress': row['progress'],
                'set_by': detail.get('set_by'),
                'set_on': detail.get('set_on'),
                'can_assign': bool(assignable),
                'can_name_team': bool(can_name_teams and row['is_leader']),
            })
        return jsonify(
            success=True,
            period=period,
            periods=targets_lib.period_choices(),
            years=_target_years(),
            rows=out,
        )
    except HTTPException:
        raise
    except Exception as e:
        print("DEBUG: targets fetch failed: %s" % e)
        return jsonify(success=False, error=str(e)), 500


def _target_years():
    """The years the period picker covers, newest last."""
    years = sorted({int(p.split('-')[0]) for p in targets_lib.period_choices()})
    return years


@app.route('/api/targets/year', methods=['GET'])
@perm('target.view')
def get_targets_by_year():
    """
    The same people, but every quarter of one year side by side.

    Built by running the same tree four times rather than by a second set of
    rules, so a quarter column can never disagree with the quarter page.
    """
    try:
        year = int(request.args.get('year') or targets_lib.current_period().split('-')[0])
        if year < 2000 or year > 2999:
            raise ValueError
    except (TypeError, ValueError):
        return jsonify(success=False, error='Pick a year'), 400

    periods = ['%d-Q%d' % (year, q) for q in (1, 2, 3, 4)]
    try:
        visible = visible_user_ids('target.view')
        me = session.get('user_id')
        can_assign_all = rbac.resolve(session.get('perms') or {}, 'target.assign') == 'all'

        conn, cur = connection()
        people = _target_people(cur)
        amounts = _target_amounts_for(cur, periods)
        achieved = _target_achieved_by_quarter(cur, year)
        cur.close()
        conn.close()

        merged = {}
        order = []
        for period in periods:
            for row in targets_lib.build_tree(
                    people, amounts[period], achieved[period], visible_ids=visible):
                entry = merged.get(row['id'])
                if entry is None:
                    person = next((p for p in people if p['id'] == row['id']), {})
                    entry = {
                        'id': row['id'],
                        'name': row['name'],
                        'role_name': row['role_name'],
                        'team_name': row['team_name'],
                        'depth': row['depth'],
                        'is_leader': row['is_leader'],
                        'can_assign': bool(can_assign_all
                                           or person.get('manager_id') == me),
                        'quarters': {},
                        'year_target': 0.0,
                        'year_achieved': 0.0,
                    }
                    merged[row['id']] = entry
                    order.append(row['id'])
                entry['quarters'][period] = {
                    'target': _money_out(row['target']),
                    'unassigned': _money_out(row['unassigned']),
                    'achieved': _money_out(row['team_achieved']),
                    'progress': row['progress'],
                }
                entry['year_target'] += float(row['target'] or 0)
                entry['year_achieved'] += float(row['team_achieved'] or 0)

        return jsonify(success=True, year=year, periods=periods,
                       years=_target_years(),
                       rows=[merged[i] for i in order])
    except HTTPException:
        raise
    except Exception as e:
        print("DEBUG: targets year fetch failed: %s" % e)
        return jsonify(success=False, error=str(e)), 500


@app.route('/api/targets/pdf', methods=['GET'])
@perm('target.view')
def export_targets_pdf():
    """
    The cascade as a PDF, for whatever the page is currently showing.

    Drawn server-side for the reason the org chart is: printing the grid from
    the browser loses the connectors. The rows come from the same scoped query
    as the page, so the export can never contain more than the caller may see.
    """
    year = request.args.get('year')
    try:
        periods = ([('%s-Q%d' % (int(year), q)) for q in (1, 2, 3, 4)] if year
                   else [_target_period(request.args.get('period'))])
    except (targets_lib.InvalidPeriod, TypeError, ValueError) as e:
        return jsonify(success=False, error=str(e)), 400

    try:
        visible = visible_user_ids('target.view')
        conn, cur = connection()
        people = _target_people(cur)
        pages = []
        for period in periods:
            amounts = _target_amounts(cur, period)
            details = _target_details(cur, period)
            achieved = _target_achieved(cur, period)
            rows = targets_lib.build_tree(people, amounts, achieved, visible_ids=visible)
            by_id = {p['id']: p for p in people}
            flat = []
            for row in rows:
                person = by_id.get(row['id'], {})
                detail = details.get(row['id']) or {}
                manager_id = person.get('manager_id')
                flat.append({
                    'id': row['id'],
                    'name': row['name'],
                    'role_name': row['role_name'],
                    'team_name': row['team_name'],
                    'manager_id': (manager_id
                                   if visible is None or manager_id in (visible or [])
                                   else None),
                    'depth': row['depth'],
                    'is_leader': row['is_leader'],
                    'target': row['target'],
                    'assigned': row['assigned'],
                    'unassigned': row['unassigned'],
                    'team_achieved': row['team_achieved'],
                    'progress': row['progress'],
                    'set_by': detail.get('set_by'),
                    'set_on': detail.get('set_on'),
                })
            pages.append((period, flat))
        cur.close()
        conn.close()

        # A year export is four sections of one document, so what the page shows
        # is what lands in the file.
        pdf = target_pdf.build(
            [(period.replace('-Q', ' Q'), flat) for period, flat in pages],
            title='Sales targets',
            subtitle='%s  ·  %s' % (
                session.get('name') or '', datetime.now().strftime('%d %B %Y')),
        )

        label = year if year else periods[0]
        response = make_response(pdf)
        response.headers['Content-Type'] = 'application/pdf'
        response.headers['Content-Disposition'] = \
            'attachment; filename="sales-targets-%s.pdf"' % label
        return response
    except HTTPException:
        raise
    except Exception as e:
        print("DEBUG: targets PDF failed: %s" % e)
        return jsonify(success=False, error=str(e)), 500


@app.route('/api/targets/assign', methods=['POST'])
@perm('target.assign')
def assign_target():
    """Set one person's target for one quarter, within what their manager holds."""
    data = request.get_json(silent=True) or request.form or {}
    try:
        user_id = int(data.get('user_id'))
    except (TypeError, ValueError):
        return jsonify(success=False, error='Pick a person'), 400
    try:
        period = _target_period(data.get('period'))
        amount = targets_lib.to_amount(data.get('amount'))
    except (targets_lib.InvalidPeriod, ValueError) as e:
        return jsonify(success=False, error=str(e)), 400

    note = (data.get('note') or '').strip()[:255] or None
    me = session.get('user_id')

    try:
        # Readable scope first, then the narrower rule: their manager sets it.
        assert_scope('target.assign', user_id)

        conn, cur = connection()
        cur.execute("SELECT id, name, manager_id FROM user WHERE id = %s", (user_id,))
        person = cur.fetchone()
        if not person:
            cur.close()
            conn.close()
            return jsonify(success=False, error='No such person'), 404

        unrestricted = rbac.resolve(session.get('perms') or {}, 'target.assign') == 'all'
        if not unrestricted and person['manager_id'] != me:
            cur.close()
            conn.close()
            return jsonify(
                success=False,
                error='Only %s\'s own manager can set their target.' % person['name'],
            ), 403

        manager_id = person['manager_id']
        parent_amount = None
        siblings_total = targets_lib.ZERO
        if manager_id:
            cur.execute(
                "SELECT amount FROM sales_target WHERE user_id = %s AND period = %s",
                (manager_id, period),
            )
            parent = cur.fetchone()
            parent_amount = parent['amount'] if parent else None
            cur.execute("""
                SELECT COALESCE(SUM(t.amount), 0) AS total
                FROM sales_target t
                JOIN user u ON u.id = t.user_id
                WHERE u.manager_id = %s AND t.period = %s AND t.user_id != %s
            """, (manager_id, period, user_id))
            siblings_total = cur.fetchone()['total'] or targets_lib.ZERO

        cur.execute("""
            SELECT COALESCE(SUM(t.amount), 0) AS total
            FROM sales_target t
            JOIN user u ON u.id = t.user_id
            WHERE u.manager_id = %s AND t.period = %s
        """, (user_id, period))
        child_committed = cur.fetchone()['total'] or targets_lib.ZERO

        error = targets_lib.validate_assignment(
            amount, parent_amount, siblings_total, child_committed)
        if error:
            cur.close()
            conn.close()
            return jsonify(success=False, error=error), 400

        cur.execute("""
            INSERT INTO sales_target (user_id, period, amount, assigned_by, note)
            VALUES (%s, %s, %s, %s, %s)
            ON DUPLICATE KEY UPDATE
                amount = VALUES(amount),
                assigned_by = VALUES(assigned_by),
                note = VALUES(note)
        """, (user_id, period, amount, me, note))
        conn.commit()
        cur.close()
        conn.close()
        return jsonify(success=True, user_id=user_id, period=period,
                       amount=float(amount))
    except HTTPException:
        raise
    except Exception as e:
        print("DEBUG: target assign failed: %s" % e)
        return jsonify(success=False, error=str(e)), 500


@app.route('/api/teams/name', methods=['POST'])
@perm('team.edit')
def name_team():
    """
    Name the branch under one leader. Membership is never stored: the team is
    whoever reports to them, so a transfer moves people between teams by
    itself. An empty name clears it.
    """
    data = request.get_json(silent=True) or request.form or {}
    try:
        leader_id = int(data.get('leader_id'))
    except (TypeError, ValueError):
        return jsonify(success=False, error='Pick a team leader'), 400
    team_name = (data.get('team_name') or '').strip()[:255]

    try:
        assert_scope('team.edit', leader_id)

        conn, cur = connection()
        cur.execute("""
            SELECT u.id, u.name, d.name AS department_name,
                   (SELECT COUNT(*) FROM user r WHERE r.manager_id = u.id) AS reports
            FROM user u
            LEFT JOIN department d ON d.id = u.department_id
            WHERE u.id = %s
        """, (leader_id,))
        leader = cur.fetchone()
        if not leader:
            cur.close()
            conn.close()
            return jsonify(success=False, error='No such person'), 404
        if not leader['reports']:
            cur.close()
            conn.close()
            return jsonify(
                success=False,
                error='%s has nobody reporting to them, so there is no team to name.'
                      % leader['name'],
            ), 400

        if not team_name:
            cur.execute("DELETE FROM team WHERE leader_id = %s", (leader_id,))
        else:
            cur.execute(
                "SELECT team_id FROM team WHERE team_name = %s AND "
                "(leader_id IS NULL OR leader_id != %s)",
                (team_name, leader_id),
            )
            if cur.fetchone():
                cur.close()
                conn.close()
                return jsonify(success=False,
                               error='Another team already uses that name.'), 400
            cur.execute("""
                INSERT INTO team (team_name, department_name, leader_id, added_by)
                VALUES (%s, %s, %s, %s)
                ON DUPLICATE KEY UPDATE team_name = VALUES(team_name),
                                        modified_by = VALUES(added_by)
            """, (team_name, leader['department_name'] or '', leader_id,
                  session.get('username')))
        conn.commit()
        cur.close()
        conn.close()
        return jsonify(success=True, leader_id=leader_id, team_name=team_name or None)
    except HTTPException:
        raise
    except Exception as e:
        print("DEBUG: team naming failed: %s" % e)
        return jsonify(success=False, error=str(e)), 500


@app.route('/api/rbac/managers', methods=['GET'])
@perm('user.view')
def get_manager_candidates():
    """
    Candidate managers for a role: anyone holding a role at a higher level
    (numerically lower). Passing no role_id returns everyone with a role.
    """
    try:
        role_id = request.args.get('role_id')
        exclude_user_id = request.args.get('exclude_user_id')

        conn, cur = connection()
        sql = """
            SELECT u.id, u.name, u.username, r.name AS role_name, r.level,
                   d.name AS department_name
            FROM user u
            JOIN rbac_role r ON r.id = u.rbac_role_id
            LEFT JOIN department d ON d.id = u.department_id
            WHERE 1=1
        """
        params = []
        own_level = 99
        if role_id:
            cur.execute("SELECT level FROM rbac_role WHERE id = %s", (role_id,))
            row = cur.fetchone()
            if row:
                sql += " AND r.level < %s"
                params.append(row['level'])
                own_level = row['level']
        if exclude_user_id:
            sql += " AND u.id != %s"
            params.append(exclude_user_id)
        sql += " AND u.is_active = 1 ORDER BY r.level, u.name"

        cur.execute(sql, params)
        managers = list(cur.fetchall())
        # Vacant positions senior enough, so a new person can sit under an
        # empty seat; the value "v:<id>" is resolved when saved.
        cur.execute("""SELECT v.id, v.title, r.name AS role_name, r.level, d.name AS department_name
                       FROM org_vacancy v JOIN rbac_role r ON r.id = v.rbac_role_id
                       LEFT JOIN department d ON d.id = v.department_id
                       WHERE r.level < %s ORDER BY r.level, v.title""",
                    (own_level,))
        managers += [{'id': 'v:%d' % v['id'], 'name': 'Vacant seat', 'role_name': v['title'],
                      'level': v['level'], 'department_name': v['department_name'], 'vacant': True}
                     for v in cur.fetchall()]
        cur.close()
        conn.close()
        return jsonify(success=True, managers=managers)
    except Exception as e:
        return jsonify(success=False, error=str(e)), 500


def _hierarchy_fields(data):
    """
    Pull department_id / rbac_role_id / manager_id off a request payload.
    Returns (fields, error). Only keys actually present are returned, so a
    form that omits them leaves the stored values alone.
    """
    fields = {}
    # Pricing is a flag rather than a role, so it rides along with the other
    # position fields and follows the same only-if-sent rule.
    if 'is_pricing' in data:
        fields['is_pricing'] = 1 if data.get('is_pricing') in (True, 1, '1', 'true', 'on') else 0
    # Someone who leaves is switched off, not deleted: their history stays.
    if 'is_active' in data:
        fields['is_active'] = 1 if data.get('is_active') in (True, 1, '1', 'true', 'on') else 0
    for key in ('department_id', 'rbac_role_id', 'manager_id'):
        if key not in data:
            continue
        value = data.get(key)
        if key == 'manager_id':
            # "v:12" is a vacant position; _validate_hierarchy turns it into the
            # nearest real person above that position.
            fields['reports_to_vacancy_id'] = None
            if isinstance(value, str) and value.startswith('v:'):
                try:
                    fields['reports_to_vacancy_id'] = int(value[2:])
                except ValueError:
                    return None, 'Invalid manager_id'
                fields['manager_id'] = None
                continue
        if value in (None, '', 'undefined', 'null'):
            fields[key] = None
            continue
        try:
            fields[key] = int(value)
        except (TypeError, ValueError):
            return None, 'Invalid %s' % key
    return fields, None


def _validate_hierarchy(cur, fields, user_id=None):
    """Reject a role/department mismatch, a missing manager, or a reporting cycle."""
    role_id = fields.get('rbac_role_id')
    vacancy_id = fields.get('reports_to_vacancy_id')
    if vacancy_id:
        cur.execute("""SELECT r.level FROM org_vacancy v JOIN rbac_role r ON r.id = v.rbac_role_id
                       WHERE v.id = %s""", (vacancy_id,))
        seat = cur.fetchone()
        if not seat:
            return 'Unknown vacant position'
        if role_id:
            cur.execute("SELECT level FROM rbac_role WHERE id = %s", (role_id,))
            own = cur.fetchone()
            if own and seat['level'] >= own['level']:
                return 'A position must be more senior than the people under it'
        # Under an empty seat, the person reports to whoever is above the seat.
        fields['manager_id'] = vacancy_manager(cur, vacancy_id)
    manager_id = fields.get('manager_id')
    if fields.get('is_active') == 0 and user_id in (1, session.get('user_id')):
        return 'This account cannot be switched off'

    if role_id:
        cur.execute("SELECT id, level, department_id FROM rbac_role WHERE id = %s", (role_id,))
        if not cur.fetchone():
            return 'Unknown role'

    if manager_id:
        if manager_id == user_id:
            return 'A user cannot report to themselves'
        cur.execute("""
            SELECT r.level FROM user u
            LEFT JOIN rbac_role r ON r.id = u.rbac_role_id
            WHERE u.id = %s
        """, (manager_id,))
        manager = cur.fetchone()
        if not manager:
            return 'Unknown manager'
        if role_id and manager['level'] is not None:
            cur.execute("SELECT level FROM rbac_role WHERE id = %s", (role_id,))
            own_level = cur.fetchone()['level']
            if manager['level'] >= own_level:
                return 'A manager must hold a more senior role than their report'

        # Walk the reporting line upward; a cycle would make team scope loop.
        if user_id:
            seen = {user_id}
            cursor_id = manager_id
            for _ in range(20):
                if cursor_id in seen:
                    return 'That manager would create a reporting cycle'
                seen.add(cursor_id)
                cur.execute("SELECT manager_id FROM user WHERE id = %s", (cursor_id,))
                row = cur.fetchone()
                cursor_id = row['manager_id'] if row else None
                if not cursor_id:
                    break
    return None


# Endpoints that legitimately carry no permission gate. Everything here except
# login and static still sits behind the session check below. Kept next to
# require_login so the two are read together; tests/test_route_coverage.py
# asserts every other route is gated.
PUBLIC_ENDPOINTS = {
    'static',
    'login', 'logout', 'main', 'home',
    'subscribe', 'firebase_messaging_sw', 'refresh_user_roles',
    'get_notifications', 'mark_notifications_read', 'all_notifications',
    'add_notification',
    # This person's own phone, for push: any signed-in user, no permission.
    'register_push_token', 'unregister_push_token',
    # Group chats: login only; membership of each room is checked inside.
    'chat_groups', 'chat_group_messages', 'chat_group_post', 'chat_group_read',
    # Any chat's members, message info and media: access is checked inside.
    'chat_thread_members', 'chat_message_info', 'chat_media',
    # My own muted chats (access to the chat checked inside).
    'chat_mutes', 'chat_mute',
    # The company sticker pack: any signed-in user; removal checked inside.
    'chat_stickers', 'chat_sticker_add', 'chat_sticker_remove', 'chat_sticker_image',
    # Names / roles for @mentions (group rooms are open to people with no
    # request-chat permission), and per-item approval counts that check each
    # permission themselves and are zero for everyone else.
    'mention_users', 'approvals_waiting_counts',
    'sales_requests_lookup',
    'set_ui_language',
}


@app.teardown_request
def close_open_connections(exception=None):
    """
    Close any database connection the handler left open, however it left.

    Handlers close their own on the way out, but 228 routes had an error path
    that returned a 500 without closing -- and a few hundred of those exhausts
    MySQL's connection limit, at which point every page hangs waiting for a
    connection that is never coming back.
    """
    for conn in getattr(g, '_open_connections', ()):
        try:
            conn.close()
        except Exception:
            # Already closed by the handler, which is the normal case.
            pass
    if hasattr(g, '_open_connections'):
        g._open_connections = []


@app.after_request
def no_stale_api_reads(response):
    """
    A JSON read is never served from the browser cache.

    Every list on the site is a GET that some page reloads after a write --
    delete an inventory item, then reload the table. With no cache headers the
    browser is free to answer that reload out of its own cache, so the row that
    was just deleted comes back, and the next reload shows it gone: the page
    looked like it was flickering between two versions of the truth.

    Only /api/ and only GET: pages and static files keep their own caching.
    """
    if request.method == 'GET' and request.path.startswith('/api/'):
        response.headers['Cache-Control'] = 'no-store, no-cache, must-revalidate, max-age=0'
        response.headers['Pragma'] = 'no-cache'
        response.headers['Expires'] = '0'
    return response


# What a job costs is for the desks that cost it (Operations), price from it
# (Pricing) and account for it (Finance), and the admin. Account Management
# and Sales see what the client is quoted, never the cost (Gamal, 2026-10-29:
# Sarah Gaber's level saw item cost on the request details page).
COST_API_PREFIXES = ('/api/sales/', '/api/sales-requests', '/api/workflow/', '/api/client-approval')
COST_KEY = re.compile(r'cost|profit|margin', re.I)
COST_KEY_KEEP = re.compile(r'costed|has_cost|cost_status', re.I)   # counts and flags, no money
COST_EVENT = re.compile(r'\b(costs?|costed|costing|re-?cost\w*|cost_\w+|\w+_cost\w*|profit\w*|margin\w*)\b', re.I)
COST_EVENT_FIELDS = ('action_type', 'field_name', 'change_description', 'change_type')


def may_see_cost():
    return any(has(code) for code in ('sales_item.cost', 'sales_item.price', 'finance_txn.approve'))


app.jinja_env.globals['may_see_cost'] = may_see_cost


def scrub_cost(value):
    """
    Cost, profit and margin out of a JSON value, at any depth: the money keys
    go, and a log entry about costing goes whole (its text carries the
    amounts). Counts like costed_items_count stay.
    """
    if isinstance(value, dict):
        return {k: scrub_cost(v) for k, v in value.items()
                if not (COST_KEY.search(k) and not COST_KEY_KEEP.search(k))}
    if isinstance(value, list):
        return [scrub_cost(v) for v in value
                if not (isinstance(v, dict) and any(
                    isinstance(v.get(f), str) and COST_EVENT.search(v[f]) for f in COST_EVENT_FIELDS))]
    return value


@app.after_request
def hide_cost_from_sales(response):
    """
    One guard for every sales-side read, so no route can forget it: whoever may
    not see cost gets the response with it taken out.
    """
    if (request.path.startswith(COST_API_PREFIXES) and response.is_json
            and 'user_id' in session and not may_see_cost()):
        data = response.get_json(silent=True)
        if data is not None:
            response.set_data(app.json.dumps(scrub_cost(data)))
    return response


@app.before_request
def require_login():
    """
    Enforce session-based authentication for all endpoints except login and public endpoints.
    Redirects to login if required session variables are missing.
    """
    # List of endpoints that do NOT require login
    allowed_routes = [
        'login', 'static', 'firebase_messaging_sw',
        # The language is chosen on the login page too, before anyone signs in.
        'set_ui_language',
    ]
    
    # Allow static files, favicon, etc.
    if request.endpoint in allowed_routes or request.endpoint is None:
        return
    
    # Allow GET to root (/) for login page
    if request.path in ['/', '/login']:
        return
    
    # Check if all required session variables are present
    required_session_vars = ['user_id', 'mobile', 'email', 'username', 'name']
    
    for var in required_session_vars:
        if var not in session:
            # For API requests, return JSON error
            if request.path.startswith('/api/'):
                return jsonify({'error': 'Not authenticated'}), 401
            # For normal requests, redirect to login
            return redirect(url_for('login'))

    if session_permissions_are_stale():
        refresh_session_permissions()

    # Default deny. A route that carries no permission gate and is not on the
    # public list is refused outright, so a handler added without a decorator
    # fails closed in development instead of shipping open.
    view = app.view_functions.get(request.endpoint)
    if view is not None and request.endpoint not in PUBLIC_ENDPOINTS \
            and not getattr(view, '_perms', None):
        app.logger.warning('Ungated endpoint refused: %s (%s)', request.endpoint, request.path)
        if request.path.startswith('/api/'):
            return jsonify({'error': 'Forbidden'}), 403
        return abort(403)


