@app.route('/api/costing/queue', methods=['GET'])
@perm('costing.view')
def costing_queue():
    """
    Everything this person has a part in, in three lists.

    `mine`     items assigned to me that I have not had accepted
    `given`    items I assigned to somebody else, with their proposals
    `all`      everything, for whoever holds costing.view unrestricted
    """
    try:
        me = session.get('user_id')
        unrestricted = _costing_unrestricted('costing.view')
        conn, cur = connection()
        reports = _direct_report_ids(cur, me)

        params = []
        where = ""
        if not unrestricted:
            ids = sorted({me, *reports})
            placeholders = ",".join(["%s"] * len(ids))
            where = (" WHERE (a.assignee_id IN (%s) OR a.assigned_by IN (%s))"
                     % (placeholders, placeholders))
            params = ids + ids

        cur.execute("""
            SELECT a.id, a.item_id, a.request_id, a.assignee_id, a.assigned_by,
                   a.status, a.note, a.added_date,
                   u.name AS assignee_name, m.name AS assigned_by_name,
                   i.name AS item_name, i.qty, i.cost_per_item, i.total_cost,
                   i.unit, i.description AS item_description,
                   i.sell_type, i.rental_days,
                   r.title AS request_title, r.request_type, r.start_date,
                   c.client_name,
                   (SELECT COUNT(*) FROM negotiation_requests nr
                    WHERE nr.item_id = a.item_id
                      AND nr.status = 'pending_costing') AS awaiting_recost
            FROM costing_assignment a
            JOIN user u ON u.id = a.assignee_id
            JOIN user m ON m.id = a.assigned_by
            JOIN sales_request_items i ON i.id = a.item_id
            JOIN sales_request r ON r.id = a.request_id
            LEFT JOIN client c ON c.id = r.client_id
        """ + where + " ORDER BY a.added_date DESC", params)
        assignments = list(cur.fetchall())

        proposals = []
        if assignments:
            item_ids = sorted({a['item_id'] for a in assignments})
            placeholders = ",".join(["%s"] * len(item_ids))
            cur.execute("""
                SELECT p.id, p.item_id, p.assignment_id, p.author_id, p.amount,
                       p.notes, p.status, p.decided_at, p.decision_note,
                       p.added_date, a.assigned_by,
                       u.name AS author_name, d.name AS decided_by_name,
                       (SELECT COUNT(*) FROM costing_proposal_file f
                        WHERE f.proposal_id = p.id) AS file_count
                FROM costing_proposal p
                JOIN costing_assignment a ON a.id = p.assignment_id
                JOIN user u ON u.id = p.author_id
                LEFT JOIN user d ON d.id = p.decided_by
                WHERE p.item_id IN (%s)
                ORDER BY p.added_date
            """ % placeholders, item_ids)
            proposals = costing.visible_proposal_ids(
                list(cur.fetchall()), me, reports, unrestricted)

        cur.close()
        conn.close()

        def out_proposal(row):
            return {
                'id': row['id'], 'item_id': row['item_id'],
                'assignment_id': row['assignment_id'],
                'author_id': row['author_id'], 'author_name': row['author_name'],
                'amount': float(row['amount']),
                'notes': row['notes'], 'status': row['status'],
                'file_count': row['file_count'],
                'decided_by_name': row['decided_by_name'],
                'decision_note': row['decision_note'],
                'can_decide': bool(row['status'] == costing.PROPOSAL_SUBMITTED
                                   and (unrestricted or row['assigned_by'] == me)),
                'is_mine': row['author_id'] == me,
                'added_date': row['added_date'].strftime('%d %b %Y %H:%M')
                              if row['added_date'] else None,
            }

        by_item = {}
        for row in proposals:
            by_item.setdefault(row['item_id'], []).append(out_proposal(row))

        def out_assignment(row):
            return {
                'id': row['id'], 'item_id': row['item_id'],
                'request_id': row['request_id'], 'item_name': row['item_name'],
                'request_title': row['request_title'],
                'request_type': row['request_type'],
                'client_name': row['client_name'],
                'item_description': row['item_description'],
                'unit': row['unit'],
                'sell_type': row['sell_type'],
                'rental_days': row['rental_days'],
                'start_date': (row['start_date'].strftime('%d %b %Y')
                               if row['start_date'] else None),
                'qty': float(row['qty']) if row['qty'] is not None else None,
                'total_cost': (float(row['total_cost'])
                               if row['total_cost'] is not None else None),
                'cost_per_item': (float(row['cost_per_item'])
                                  if row['cost_per_item'] is not None else None),
                'assignee_id': row['assignee_id'],
                'assignee_name': row['assignee_name'],
                'assigned_by': row['assigned_by'],
                'assigned_by_name': row['assigned_by_name'],
                'status': row['status'], 'note': row['note'],
                # Sent back by Re-Pricing rather than costed for the first time.
                # Same workflow, but whoever proposes should know which it is.
                'awaiting_recost': bool(row['awaiting_recost']),
                'assigned_on': row['added_date'].strftime('%d %b %Y')
                               if row['added_date'] else None,
                'proposals': by_item.get(row['item_id'], []),
            }

        rows = [out_assignment(a) for a in assignments]
        return jsonify(
            success=True,
            me=me,
            can_assign=has('costing.assign'),
            can_propose=has('costing.propose'),
            mine=[r for r in rows if r['assignee_id'] == me],
            given=[r for r in rows if r['assigned_by'] == me],
            others=[r for r in rows
                    if r['assignee_id'] != me and r['assigned_by'] != me],
        )
    except HTTPException:
        raise
    except Exception as e:
        print("DEBUG: costing queue failed: %s" % e)
        return jsonify(success=False, error=str(e)), 500


@app.route('/api/costing/team', methods=['GET'])
@perm('costing.assign')
def costing_team():
    """
    Who this person may hand costing to: their own direct reports.

    `?leaders=1` narrows that to team leaders. A whole request goes to a leader
    and the leader splits its items among their own people, so offering members
    in that dialog invites the Head to skip a rung and take the split away from
    the person whose job it is.
    """
    try:
        me = session.get('user_id')
        leaders_only = request.args.get('leaders') == '1'
        conn, cur = connection()
        level_clause = " AND r.level = %s" if leaders_only else ""
        level_params = [rbac.LEVEL_TEAM_LEADER] if leaders_only else []
        if _costing_unrestricted('costing.assign'):
            # The Head may reach past their own reports, but the list stays
            # inside Operations rather than offering the whole company.
            cur.execute("""
                SELECT u.id, u.name, r.name AS role_name, r.level
                FROM user u
                LEFT JOIN rbac_role r ON r.id = u.rbac_role_id
                WHERE u.id != %s AND u.department_id = (
                    SELECT department_id FROM user WHERE id = %s)
                  AND u.is_active = 1
            """ + level_clause + """
                ORDER BY r.level, u.name
            """, [me, me] + level_params)
        else:
            cur.execute("""
                SELECT u.id, u.name, r.name AS role_name, r.level
                FROM user u
                LEFT JOIN rbac_role r ON r.id = u.rbac_role_id
                WHERE u.manager_id = %s AND u.is_active = 1
            """ + level_clause + """
                ORDER BY u.name
            """, [me] + level_params)
        people = list(cur.fetchall())
        cur.close()
        conn.close()
        return jsonify(success=True, people=people)
    except HTTPException:
        raise
    except Exception as e:
        return jsonify(success=False, error=str(e)), 500


@app.route('/api/costing/summary', methods=['GET'])
@perm('costing.view')
def costing_summary():
    """
    What is waiting for me, and where.

    Without this an assignment is invisible until somebody happens to open the
    right request's cost modal. The counts drive the badge on the menu, the
    banner on the operations pages and the per-row marks in the request list.
    """
    try:
        me = session.get('user_id')
        conn, cur = connection()

        # On my desk: open assignments where nothing of mine is accepted yet.
        cur.execute("""
            SELECT a.request_id, COUNT(*) AS n
            FROM costing_assignment a
            WHERE a.assignee_id = %s AND a.status = 'open'
            GROUP BY a.request_id
        """, (me,))
        mine = {row['request_id']: row['n'] for row in cur.fetchall()}

        # Waiting on me: live proposals from people I asked.
        cur.execute("""
            SELECT p.request_id, COUNT(*) AS n
            FROM costing_proposal p
            JOIN costing_assignment a ON a.id = p.assignment_id
            WHERE p.status = 'submitted' AND a.assigned_by = %s
            GROUP BY p.request_id
        """, (me,))
        decide = {row['request_id']: row['n'] for row in cur.fetchall()}

        # Everything still out, for the request list, whoever it is with.
        cur.execute("""
            SELECT request_id, COUNT(*) AS n
            FROM costing_assignment WHERE status = 'open'
            GROUP BY request_id
        """)
        out = {row['request_id']: row['n'] for row in cur.fetchall()}

        # Sent back by Pricing for a new cost. Operations work like any other,
        # so it is counted here rather than left to be found in a modal.
        cur.execute("""
            SELECT sri.request_id, COUNT(DISTINCT nr.item_id) AS n
            FROM negotiation_requests nr
            JOIN sales_request_items sri ON sri.id = nr.item_id
            WHERE nr.status = 'pending_costing'
            GROUP BY sri.request_id
        """)
        recost = {row['request_id']: row['n'] for row in cur.fetchall()}

        cur.close()
        conn.close()

        by_request = {}
        for request_id in set(list(mine) + list(decide) + list(out) + list(recost)):
            by_request[str(request_id)] = {
                'mine': mine.get(request_id, 0),
                'awaiting_decision': decide.get(request_id, 0),
                'open': out.get(request_id, 0),
                'recost': recost.get(request_id, 0),
            }
        return jsonify(success=True,
                       mine_total=sum(mine.values()),
                       awaiting_decision_total=sum(decide.values()),
                       open_total=sum(out.values()),
                       recost_total=sum(recost.values()),
                       by_request=by_request)
    except HTTPException:
        raise
    except Exception as e:
        print("DEBUG: costing summary failed: %s" % e)
        return jsonify(success=False, error=str(e)), 500


@app.route('/api/costing/request/<int:request_id>', methods=['GET'])
@perm('costing.view')
def costing_for_request(request_id):
    """
    The costing state of every item on one request, in a single call.

    The operations request page opens a modal with all the items in it, so it
    asks once rather than once per item.
    """
    try:
        me = session.get('user_id')
        unrestricted = _costing_unrestricted('costing.view')
        conn, cur = connection()
        reports = _direct_report_ids(cur, me)

        cur.execute("""
            SELECT a.id, a.item_id, a.assignee_id, a.assigned_by, a.status, a.note,
                   a.added_date, u.name AS assignee_name, m.name AS assigned_by_name
            FROM costing_assignment a
            JOIN user u ON u.id = a.assignee_id
            JOIN user m ON m.id = a.assigned_by
            WHERE a.request_id = %s
            ORDER BY a.added_date
        """, (request_id,))
        assignments = list(cur.fetchall())

        cur.execute("""
            SELECT p.id, p.item_id, p.assignment_id, p.author_id, p.amount, p.notes,
                   p.status, p.decision_note, p.added_date, a.assigned_by,
                   u.name AS author_name, d.name AS decided_by_name,
                   (SELECT COUNT(*) FROM costing_proposal_file f
                    WHERE f.proposal_id = p.id) AS file_count
            FROM costing_proposal p
            JOIN costing_assignment a ON a.id = p.assignment_id
            JOIN user u ON u.id = p.author_id
            LEFT JOIN user d ON d.id = p.decided_by
            WHERE p.request_id = %s
            ORDER BY p.added_date
        """, (request_id,))
        proposals = costing.visible_proposal_ids(
            list(cur.fetchall()), me, reports, unrestricted)
        cur.close()
        conn.close()

        items = {}
        for row in assignments:
            entry = items.setdefault(row['item_id'], {'assignments': [], 'proposals': []})
            entry['assignments'].append({
                'id': row['id'], 'assignee_id': row['assignee_id'],
                'assignee_name': row['assignee_name'],
                'assigned_by': row['assigned_by'],
                'assigned_by_name': row['assigned_by_name'],
                'status': row['status'], 'note': row['note'],
                'mine': row['assignee_id'] == me,
                'assigned_on': row['added_date'].strftime('%d %b %Y')
                               if row['added_date'] else None,
            })
        for row in proposals:
            entry = items.setdefault(row['item_id'], {'assignments': [], 'proposals': []})
            entry['proposals'].append({
                'id': row['id'], 'author_name': row['author_name'],
                'author_id': row['author_id'], 'amount': float(row['amount']),
                'notes': row['notes'], 'status': row['status'],
                'file_count': row['file_count'],
                'decided_by_name': row['decided_by_name'],
                # The reason was already being read out of the database and
                # then dropped here, so a rejected author saw the word
                # "rejected" and nothing that told them what to change.
                'decision_note': row['decision_note'],
                'is_mine': row['author_id'] == me,
                'can_decide': bool(row['status'] == costing.PROPOSAL_SUBMITTED
                                   and (unrestricted or row['assigned_by'] == me)),
                'added_date': row['added_date'].strftime('%d %b %Y %H:%M')
                              if row['added_date'] else None,
            })

        return jsonify(success=True, request_id=request_id, items=items,
                       can_assign=has('costing.assign'),
                       can_propose=has('costing.propose'),
                       can_cost_direct=has('sales_item.cost_direct'))
    except HTTPException:
        raise
    except Exception as e:
        print("DEBUG: costing for request failed: %s" % e)
        return jsonify(success=False, error=str(e)), 500


@app.route('/api/costing/items', methods=['GET'])
@perm('costing.assign')
def costing_items():
    """
    Items that could be sent out for costing.

    Uncosted ones first, because that is what somebody opening this list is
    looking for; a costed item is still offered so a cost can be revisited.
    """
    search = (request.args.get('q') or '').strip()
    try:
        conn, cur = connection()
        sql = """
            SELECT i.id, i.name, i.qty, i.cost_per_item, i.request_id,
                   r.title AS request_title,
                   (SELECT COUNT(*) FROM costing_assignment a
                    WHERE a.item_id = i.id AND a.status = 'open') AS open_assignments,
                   (SELECT COUNT(*) FROM negotiation_requests nr
                    WHERE nr.item_id = i.id
                      AND nr.status = 'pending_costing') AS awaiting_recost
            FROM sales_request_items i
            JOIN sales_request r ON r.id = i.request_id
            WHERE r.status != 'cancelled'
        """
        params = []
        if search:
            sql += " AND (i.name LIKE %s OR r.title LIKE %s OR i.request_id = %s)"
            params += ['%' + search + '%', '%' + search + '%',
                       search if search.isdigit() else 0]
        # An item Pricing sent back for a new cost is the most urgent thing on
        # this list, so it sorts above even the uncosted ones.
        sql += """
            ORDER BY (SELECT COUNT(*) FROM negotiation_requests nr
                      WHERE nr.item_id = i.id AND nr.status = 'pending_costing') DESC,
                     (i.cost_per_item IS NOT NULL AND i.cost_per_item > 0),
                     i.id DESC
            LIMIT 60
        """
        cur.execute(sql, params)
        items = [{
            'id': row['id'], 'name': row['name'],
            'qty': float(row['qty']) if row['qty'] is not None else None,
            'cost_per_item': (float(row['cost_per_item'])
                              if row['cost_per_item'] is not None else None),
            'request_id': row['request_id'],
            'request_title': row['request_title'],
            'open_assignments': row['open_assignments'],
            'awaiting_recost': bool(row['awaiting_recost']),
        } for row in cur.fetchall()]
        cur.close()
        conn.close()
        return jsonify(success=True, items=items)
    except HTTPException:
        raise
    except Exception as e:
        return jsonify(success=False, error=str(e)), 500


@app.route('/api/costing/assign', methods=['POST'])
@perm('costing.assign')
def costing_assign():
    """Put one item on one or more people's desks. Re-asking reopens the row."""
    data = request.get_json(silent=True) or request.form or {}
    # One item or several: picking eleven items in the modal should be one
    # dialog and one round trip, not eleven of each.
    raw_items = data.get('item_ids')
    if raw_items is None and data.get('item_id') is not None:
        raw_items = [data.get('item_id')]
    item_ids = []
    for raw in (raw_items or []):
        try:
            item_ids.append(int(raw))
        except (TypeError, ValueError):
            continue
    if not item_ids:
        return jsonify(success=False, error='Pick an item'), 400
    assignee_ids = data.get('assignee_ids') or []
    if not isinstance(assignee_ids, list) or not assignee_ids:
        return jsonify(success=False, error='Pick at least one person'), 400
    note = (data.get('note') or '').strip()[:500] or None

    me = session.get('user_id')
    try:
        conn, cur = connection()
        items = []
        for item_id in item_ids:
            item = _costing_item(cur, item_id)
            if not item:
                cur.close()
                conn.close()
                return jsonify(success=False, error='No such item'), 404
            items.append(item)

        reports = _direct_report_ids(cur, me)
        unrestricted = _costing_unrestricted('costing.assign')
        assigned = []
        for raw in assignee_ids:
            try:
                assignee_id = int(raw)
            except (TypeError, ValueError):
                continue
            costing.check_assignment(me, assignee_id, reports, unrestricted)
            for item in items:
                cur.execute("""
                    INSERT INTO costing_assignment (item_id, request_id, assignee_id,
                                                    assigned_by, status, note)
                    VALUES (%s, %s, %s, %s, 'open', %s)
                    ON DUPLICATE KEY UPDATE status = 'open',
                                            assigned_by = VALUES(assigned_by),
                                            note = VALUES(note)
                """, (item['id'], item['request_id'], assignee_id, me, note))
                _costing_log(cur, item['id'], item['request_id'], 'assigned', me,
                             detail='assigned to user %d' % assignee_id)
            assigned.append(assignee_id)

        conn.commit()
        cur.close()
        conn.close()
        if assigned and items:
            notify_users(
                assigned,
                'Costing assigned: %d item(s)' % len(items),
                '%s on request #%d %s with you for costing.'
                % (', '.join(i['name'] or 'an item' for i in items[:3]) +
                   ('' if len(items) <= 3 else ' and %d more' % (len(items) - 3)),
                   items[0]['request_id'],
                   'is' if len(items) == 1 else 'are'),
                link='/operation_request?request=%d' % items[0]['request_id'])
        return jsonify(success=True, item_id=item_ids[0], item_ids=item_ids,
                       items=len(items), assigned=assigned)
    except costing.CostingError as e:
        return jsonify(success=False, error=str(e)), 403
    except HTTPException:
        raise
    except Exception as e:
        print("DEBUG: costing assign failed: %s" % e)
        return jsonify(success=False, error=str(e)), 500


@app.route('/api/costing/assign-request', methods=['POST'])
@perm('costing.assign')
def costing_assign_request():
    """
    Hand a whole sales request to one or more team leaders.

    The Operations Head does not pick items: a request arrives, it goes to a
    leader, and the leader splits it among their own people. That split is the
    per-item assignment that already exists, so this fans out to one row per
    item and every rule below it -- direct reports only, the asker decides --
    keeps working untouched.

    Items that already carry a cost are left alone unless Pricing has sent them
    back, so re-assigning a part-costed request does not reopen finished work.
    """
    data = request.get_json(silent=True) or request.form or {}
    try:
        request_id = int(data.get('request_id'))
    except (TypeError, ValueError):
        return jsonify(success=False, error='Pick a request'), 400
    assignee_ids = data.get('assignee_ids') or []
    if not isinstance(assignee_ids, list) or not assignee_ids:
        return jsonify(success=False, error='Pick at least one person'), 400
    note = (data.get('note') or '').strip()[:500] or None
    # The Head may want the lot, including what is already costed.
    include_costed = bool(data.get('include_costed'))

    me = session.get('user_id')
    try:
        conn, cur = connection()
        cur.execute("SELECT id, title FROM sales_request WHERE id = %s", (request_id,))
        sales_request = cur.fetchone()
        if not sales_request:
            cur.close()
            conn.close()
            return jsonify(success=False, error='No such request'), 404

        cur.execute("""
            SELECT i.id, i.name, i.cost_per_item,
                   (SELECT COUNT(*) FROM negotiation_requests nr
                    WHERE nr.item_id = i.id AND nr.status = 'pending_costing')
                       AS awaiting_recost
            FROM sales_request_items i
            WHERE i.request_id = %s
            ORDER BY i.id
        """, (request_id,))
        all_items = list(cur.fetchall())
        if not all_items:
            cur.close()
            conn.close()
            return jsonify(success=False, error='That request has no items'), 400

        wanted = [row for row in all_items
                  if include_costed
                  or row['awaiting_recost']
                  or row['cost_per_item'] is None
                  or float(row['cost_per_item']) == 0]
        skipped = len(all_items) - len(wanted)
        if not wanted:
            cur.close()
            conn.close()
            return jsonify(success=False,
                           error='Every item on this request is already costed.'), 400

        reports = _direct_report_ids(cur, me)
        unrestricted = _costing_unrestricted('costing.assign')
        assigned = []
        for raw in assignee_ids:
            try:
                assignee_id = int(raw)
            except (TypeError, ValueError):
                continue
            costing.check_assignment(me, assignee_id, reports, unrestricted)
            for item in wanted:
                cur.execute("""
                    INSERT INTO costing_assignment (item_id, request_id, assignee_id,
                                                    assigned_by, status, note)
                    VALUES (%s, %s, %s, %s, 'open', %s)
                    ON DUPLICATE KEY UPDATE status = 'open',
                                            assigned_by = VALUES(assigned_by),
                                            note = VALUES(note)
                """, (item['id'], request_id, assignee_id, me, note))
                _costing_log(cur, item['id'], request_id, 'assigned', me,
                             detail='whole request assigned to user %d' % assignee_id)
            assigned.append(assignee_id)

        conn.commit()
        cur.close()
        conn.close()

        # Tell them, and say where the work is. Without the link the tray sends
        # people hunting for the request that landed on them.
        notify_users(
            assigned,
            'Costing assigned: request #%d' % request_id,
            '%d item(s) on "%s" are with you for costing.'
            % (len(wanted), sales_request['title'] or ('Request #%d' % request_id)),
            link='/operation_request?request=%d' % request_id)

        return jsonify(success=True, request_id=request_id, assigned=assigned,
                       items=len(wanted), skipped_costed=skipped)
    except costing.CostingError as e:
        return jsonify(success=False, error=str(e)), 403
    except HTTPException:
        raise
    except Exception as e:
        print("DEBUG: costing assign-request failed: %s" % e)
        return jsonify(success=False, error=str(e)), 500


@app.route('/api/costing/assignments/<int:assignment_id>/withdraw', methods=['POST'])
@perm('costing.assign')
def costing_withdraw(assignment_id):
    """Take an item back off somebody's desk. The row stays, the trail stays."""
    me = session.get('user_id')
    try:
        conn, cur = connection()
        cur.execute("SELECT * FROM costing_assignment WHERE id = %s", (assignment_id,))
        row = cur.fetchone()
        if not row:
            cur.close()
            conn.close()
            return jsonify(success=False, error='No such assignment'), 404
        if row['assigned_by'] != me and not _costing_unrestricted('costing.assign'):
            cur.close()
            conn.close()
            return jsonify(success=False,
                           error='Only the person who assigned it can withdraw it.'), 403

        cur.execute("UPDATE costing_assignment SET status = 'withdrawn' WHERE id = %s",
                    (assignment_id,))
        _costing_log(cur, row['item_id'], row['request_id'],
                     'assignment_withdrawn', me,
                     detail='withdrawn from user %d' % row['assignee_id'])
        conn.commit()
        cur.close()
        conn.close()
        return jsonify(success=True)
    except HTTPException:
        raise
    except Exception as e:
        return jsonify(success=False, error=str(e)), 500


@app.route('/api/costing/proposals', methods=['POST'])
@perm('costing.propose')
def costing_propose():
    """Put up a costing proposal for an item that is on my desk."""
    data = request.get_json(silent=True) or request.form or {}
    try:
        assignment_id = int(data.get('assignment_id'))
        amount = costing.parse_amount(data.get('amount'))
    except (TypeError, ValueError) as e:
        return jsonify(success=False, error=str(e) or 'Enter an amount'), 400
    notes = (data.get('notes') or '').strip() or None

    me = session.get('user_id')
    try:
        conn, cur = connection()
        cur.execute("SELECT * FROM costing_assignment WHERE id = %s", (assignment_id,))
        assignment = cur.fetchone()
        if not assignment:
            cur.close()
            conn.close()
            return jsonify(success=False, error='No such assignment'), 404
        if assignment['assignee_id'] != me:
            cur.close()
            conn.close()
            return jsonify(success=False, error='That item is not assigned to you.'), 403
        costing.check_proposal(assignment['status'])

        # Is this their first go at this item, or another one after a
        # decision? The person deciding should be told which.
        cur.execute("""
            SELECT COUNT(*) AS n FROM costing_proposal
            WHERE item_id = %s AND author_id = %s
        """, (assignment['item_id'], me))
        previous = cur.fetchone()['n']

        cur.execute("""
            INSERT INTO costing_proposal (item_id, request_id, assignment_id,
                                          author_id, amount, notes)
            VALUES (%s, %s, %s, %s, %s, %s)
        """, (assignment['item_id'], assignment['request_id'], assignment_id,
              me, amount, notes))
        proposal_id = cur.lastrowid
        _costing_log(cur, assignment['item_id'], assignment['request_id'],
                     'proposal_submitted', me, proposal_id=proposal_id,
                     amount=amount, detail=notes)

        cur.execute("""
            SELECT i.name AS item_name, u.name AS author_name
            FROM sales_request_items i, user u
            WHERE i.id = %s AND u.id = %s
        """, (assignment['item_id'], me))
        about = cur.fetchone() or {}

        conn.commit()
        cur.close()
        conn.close()

        # The person who asked for this costing decides it, and had no way of
        # knowing it had arrived: they found out by opening the page.
        notify_user(
            assignment['assigned_by'],
            ('New costing to decide: %s' if not previous
             else 'Costing re-submitted: %s') % (about.get('item_name') or 'an item'),
            '%s %s EGP %s for "%s" on request #%s.%s'
            % (about.get('author_name') or 'Somebody',
               'proposed' if not previous else 'sent a new price of',
               amount, about.get('item_name') or 'an item',
               assignment['request_id'],
               ' It is waiting for your decision.' if not previous
               else ' Their earlier one was decided; this replaces it.'),
            link='/operation_request?request=%d' % assignment['request_id'])

        return jsonify(success=True, proposal_id=proposal_id, amount=float(amount),
                       resubmission=bool(previous))
    except costing.CostingError as e:
        return jsonify(success=False, error=str(e)), 403
    except HTTPException:
        raise
    except Exception as e:
        print("DEBUG: costing propose failed: %s" % e)
        return jsonify(success=False, error=str(e)), 500


@app.route('/api/costing/proposals/<int:proposal_id>/files', methods=['POST'])
@perm('costing.propose')
def costing_proposal_files(proposal_id):
    """
    Attach quotations and photographs to a proposal.

    Same allowlist and size cap as the item attachments route: an upload path is
    a trust boundary and gets the same treatment wherever it appears.
    """
    me = session.get('user_id')
    allowed = {'pdf', 'jpg', 'jpeg', 'png', 'gif', 'bmp', 'webp',
               'xlsx', 'xls', 'csv', 'doc', 'docx'}
    max_size = 10 * 1024 * 1024

    try:
        files = request.files.getlist('files[]')
        if not files:
            return jsonify(success=False, error='No files provided'), 400

        conn, cur = connection()
        cur.execute("SELECT * FROM costing_proposal WHERE id = %s", (proposal_id,))
        proposal = cur.fetchone()
        if not proposal:
            cur.close()
            conn.close()
            return jsonify(success=False, error='No such proposal'), 404
        if proposal['author_id'] != me:
            cur.close()
            conn.close()
            return jsonify(success=False, error='That is not your proposal.'), 403
        if proposal['status'] != costing.PROPOSAL_SUBMITTED:
            cur.close()
            conn.close()
            return jsonify(success=False,
                           error='A proposal that has been decided cannot be changed.'), 400

        folder = 'uploads/costing/%d' % proposal_id
        os.makedirs(folder, exist_ok=True)
        saved = []
        for handle in files:
            if not handle or not handle.filename or '.' not in handle.filename:
                continue
            extension = handle.filename.rsplit('.', 1)[1].lower()
            if extension not in allowed:
                continue
            handle.seek(0, 2)
            size = handle.tell()
            handle.seek(0)
            if size > max_size:
                continue
            stamp = datetime.now().strftime('%Y%m%d_%H%M%S_%f')
            safe = secure_filename(handle.filename)
            path = os.path.join(folder, '%s_%s' % (stamp, safe))
            handle.save(path)
            cur.execute("""
                INSERT INTO costing_proposal_file (proposal_id, file_url,
                                                   original_name, file_type,
                                                   file_size, uploaded_by)
                VALUES (%s, %s, %s, %s, %s, %s)
            """, (proposal_id, '/' + path, handle.filename, extension, size, me))
            _costing_log(cur, proposal['item_id'], proposal['request_id'],
                         'file_attached', me, proposal_id=proposal_id,
                         detail=handle.filename)
            saved.append(handle.filename)

        conn.commit()
        cur.close()
        conn.close()
        if not saved:
            return jsonify(success=False,
                           error='Nothing was saved: check the file type and that it is under 10MB.'), 400
        return jsonify(success=True, saved=saved)
    except HTTPException:
        raise
    except Exception as e:
        print("DEBUG: costing upload failed: %s" % e)
        return jsonify(success=False, error=str(e)), 500


