@app.route('/api/costing/items/<int:item_id>/alternatives', methods=['POST'])
@perm('costing.propose', 'costing.assign')
def costing_add_alternative(item_id):
    """
    Put up a second way of doing this item: a picture and why.

    Sales say what the client asked for; costing often knows another way to
    build it. Said here it travels with the item, so pricing and the client are
    choosing between two options rather than reading about one in a note.

    Same allowlist and cap as every other upload on this page -- an upload path
    is a trust boundary and gets the same treatment wherever it appears.
    """
    me = session.get('user_id')
    allowed = {'jpg', 'jpeg', 'png', 'gif', 'bmp', 'webp'}
    max_size = 10 * 1024 * 1024
    comment = (request.form.get('comment') or '').strip()[:1000] or None
    label = (request.form.get('label') or '').strip()[:120] or None

    try:
        handle = request.files.get('image')
        if not handle or not handle.filename or '.' not in handle.filename:
            return jsonify(success=False, error='Pick an image of the alternative.'), 400
        extension = handle.filename.rsplit('.', 1)[1].lower()
        if extension not in allowed:
            return jsonify(success=False,
                           error='Images only: JPG, PNG, GIF, BMP or WEBP.'), 400
        handle.seek(0, 2)
        size = handle.tell()
        handle.seek(0)
        if size > max_size:
            return jsonify(success=False, error='That image is over 10MB.'), 400
        if not comment:
            return jsonify(success=False,
                           error='Say what the alternative is: the picture alone '
                                 'does not tell pricing why it is here.'), 400

        conn, cur = connection()
        item = _costing_item(cur, item_id)
        if not item:
            cur.close()
            conn.close()
            return jsonify(success=False, error='No such item'), 404

        folder = 'uploads/alternatives/%d' % item_id
        os.makedirs(folder, exist_ok=True)
        stamp = datetime.now().strftime('%Y%m%d_%H%M%S_%f')
        path = os.path.join(folder, '%s_%s' % (stamp, secure_filename(handle.filename)))
        handle.save(path)

        cur.execute("""
            INSERT INTO item_images (item_id, image_path, image_type, file_size,
                                     uploaded_by, is_alternative, alt_comment,
                                     alt_label)
            VALUES (%s, %s, %s, %s, %s, 1, %s, %s)
        """, (item_id, path, extension, size, me, comment, label))
        new_id = cur.lastrowid
        _costing_log(cur, item_id, item['request_id'], 'file_attached', me,
                     detail='alternative option: %s' % (label or comment)[:200])
        conn.commit()
        cur.close()
        conn.close()
        return jsonify(success=True, id=new_id, image_url='/' + path,
                       comment=comment, label=label)
    except HTTPException:
        raise
    except Exception as e:
        print("DEBUG: add alternative failed: %s" % e)
        return jsonify(success=False, error=str(e)), 500


@app.route('/api/costing/alternatives/<int:alternative_id>', methods=['DELETE'])
@perm('costing.propose', 'costing.assign')
def costing_delete_alternative(alternative_id):
    """Take back an alternative. Whoever put it up, or the Head."""
    me = session.get('user_id')
    try:
        conn, cur = connection()
        cur.execute("""
            SELECT id, item_id, uploaded_by, image_path, alt_label, alt_comment
            FROM item_images WHERE id = %s AND is_alternative = 1
        """, (alternative_id,))
        row = cur.fetchone()
        if not row:
            cur.close()
            conn.close()
            return jsonify(success=False, error='No such alternative'), 404
        if row['uploaded_by'] != me and not _costing_unrestricted('costing.assign'):
            cur.close()
            conn.close()
            return jsonify(success=False,
                           error='Only whoever added it can remove it.'), 403

        item = _costing_item(cur, row['item_id'])
        cur.execute("DELETE FROM item_images WHERE id = %s", (alternative_id,))
        if item:
            _costing_log(cur, row['item_id'], item['request_id'], 'file_removed', me,
                         detail='alternative option removed: %s'
                                % (row['alt_label'] or row['alt_comment'] or '')[:200])
        conn.commit()
        cur.close()
        conn.close()
        # The row is gone whatever happens to the file; a leftover image is
        # tidier than a dangling record.
        try:
            if row['image_path'] and os.path.exists(row['image_path']):
                os.remove(row['image_path'])
        except OSError as e:
            print("DEBUG: alternative file not removed: %s" % e)
        return jsonify(success=True)
    except HTTPException:
        raise
    except Exception as e:
        print("DEBUG: delete alternative failed: %s" % e)
        return jsonify(success=False, error=str(e)), 500


@app.route('/api/costing/proposals/<int:proposal_id>/decide', methods=['POST'])
@perm('costing.decide')
def costing_decide(proposal_id):
    """
    Accept or reject a proposal. Accepting writes the item's cost.

    The competing proposals are rejected in the same transaction, so an item
    never has two winners, and every one of those rejections is logged.
    """
    data = request.get_json(silent=True) or request.form or {}
    decision = (data.get('decision') or '').strip().lower()
    if decision not in ('accept', 'reject'):
        return jsonify(success=False, error='Decision must be accept or reject'), 400
    note = (data.get('note') or '').strip()[:500] or None
    me = session.get('user_id')

    try:
        conn, cur = connection()
        cur.execute("""
            SELECT p.*, a.assigned_by, u.name AS author_name
            FROM costing_proposal p
            JOIN costing_assignment a ON a.id = p.assignment_id
            JOIN user u ON u.id = p.author_id
            WHERE p.id = %s
        """, (proposal_id,))
        proposal = cur.fetchone()
        if not proposal:
            cur.close()
            conn.close()
            return jsonify(success=False, error='No such proposal'), 404

        costing.check_decision(proposal['status'], me, proposal['assigned_by'],
                               _costing_unrestricted('costing.decide'))

        if decision == 'reject':
            cur.execute("""
                UPDATE costing_proposal
                SET status = 'rejected', decided_by = %s, decided_at = NOW(),
                    decision_note = %s
                WHERE id = %s
            """, (me, note, proposal_id))
            _costing_log(cur, proposal['item_id'], proposal['request_id'],
                         'proposal_rejected', me, proposal_id=proposal_id,
                         amount=proposal['amount'], detail=note)
            cur.execute("SELECT name FROM sales_request_items WHERE id = %s",
                        (proposal['item_id'],))
            item_row = cur.fetchone() or {}
            conn.commit()
            cur.close()
            conn.close()

            # A decision the author is not told about is a decision they find
            # out about by chance. The reason travels with it, because "no"
            # without a reason is not something anybody can act on.
            notify_user(
                proposal['author_id'],
                'Costing declined: %s' % (item_row.get('name') or 'an item'),
                'Your price of EGP %s for "%s" on request #%s was declined by %s.%s '
                'The item is still with you: put up another one.'
                % (proposal['amount'], item_row.get('name') or 'an item',
                   proposal['request_id'], session.get('name') or 'your team leader',
                   (' Reason: %s.' % note) if note else ' No reason was given.'),
                link='/operation_request?request=%d' % proposal['request_id'])

            return jsonify(success=True, status='rejected')

        item = _costing_item(cur, proposal['item_id'])
        if not item:
            cur.close()
            conn.close()
            return jsonify(success=False, error='The item has gone'), 404

        cur.execute("""
            UPDATE costing_proposal
            SET status = 'accepted', decided_by = %s, decided_at = NOW(),
                decision_note = %s
            WHERE id = %s
        """, (me, note, proposal_id))

        # One winner per item: everything else still open loses, on the record.
        cur.execute("""
            SELECT id, author_id, amount FROM costing_proposal
            WHERE item_id = %s AND id != %s AND status = 'submitted'
        """, (proposal['item_id'], proposal_id))
        losers = list(cur.fetchall())
        for loser in losers:
            cur.execute("""
                UPDATE costing_proposal
                SET status = 'rejected', decided_by = %s, decided_at = NOW(),
                    decision_note = 'Another proposal was accepted'
                WHERE id = %s
            """, (me, loser['id']))
            _costing_log(cur, proposal['item_id'], proposal['request_id'],
                         'proposal_rejected', me, proposal_id=loser['id'],
                         amount=loser['amount'],
                         detail='another proposal was accepted')

        amount = proposal['amount']
        total = item_total_cost(item, amount)
        old_cost = item['cost_per_item']
        cur.execute("""
            UPDATE sales_request_items
            SET cost_per_item = %s, total_cost = %s
            WHERE id = %s
        """, (amount, total, proposal['item_id']))

        # The item's own history already exists and other pages read it, so the
        # accepted cost lands there too rather than only in the costing trail.
        log_item_change(
            proposal['request_id'], proposal['item_id'], item['name'],
            item['request_type'], 'ITEM_UPDATE', session.get('name') or 'Unknown',
            old_data={'cost_per_item': old_cost},
            new_data={'cost_per_item': amount},
            change_description='Costing proposal by %s accepted' % proposal['author_name'],
            conn=conn, cur=cur,
        )
        _costing_log(cur, proposal['item_id'], proposal['request_id'],
                     'proposal_accepted', me, proposal_id=proposal_id,
                     amount=amount,
                     detail='cost set from %s to %s' % (old_cost, amount))

        # Their work is done; the assignment closes rather than lingering open.
        cur.execute("""
            UPDATE costing_assignment SET status = 'closed'
            WHERE item_id = %s AND status = 'open'
        """, (proposal['item_id'],))

        # An item sent back for re-costing is finished the same way whichever
        # route the cost arrived by, so the negotiation moves on from here too.
        recosted = complete_recosting(
            cur, proposal['item_id'], amount, old_cost,
            session.get('name') or 'Operations', item_name=item['name'])
        changed_after_handoff = mark_cost_changed(cur, proposal['request_id'])
        handoff = pricing_state(cur, proposal['request_id'])

        conn.commit()
        cur.close()
        conn.close()
        if changed_after_handoff:
            notify_cost_changed(proposal['request_id'])
        elif handoff and handoff['all_costed']:
            notify_costing_complete(proposal['request_id'])

        # Everybody who put a price up on this item hears what happened to it.
        notify_user(
            proposal['author_id'],
            'Costing accepted: %s' % (item['name'] or 'an item'),
            'Your price of EGP %s for "%s" on request #%s was accepted by %s. '
            'It is now the item cost.'
            % (amount, item['name'] or 'an item', proposal['request_id'],
               session.get('name') or 'your team leader'),
            link='/operation_request?request=%d' % proposal['request_id'])
        losing_authors = sorted({row['author_id'] for row in losers
                                 if row['author_id'] != proposal['author_id']})
        if losing_authors:
            notify_users(
                losing_authors,
                'Costing closed: %s' % (item['name'] or 'an item'),
                'Another price was accepted for "%s" on request #%s, so yours '
                'was not taken forward.'
                % (item['name'] or 'an item', proposal['request_id']),
                link='/operation_request?request=%d' % proposal['request_id'])

        return jsonify(success=True, status='accepted', amount=float(amount),
                       total_cost=total, rejected=len(losers),
                       recosted_negotiation=recosted)
    except costing.CostingError as e:
        return jsonify(success=False, error=str(e)), 403
    except HTTPException:
        raise
    except Exception as e:
        print("DEBUG: costing decision failed: %s" % e)
        return jsonify(success=False, error=str(e)), 500


@app.route('/api/costing/items/<int:item_id>/log', methods=['GET'])
@perm('costing.view')
def costing_item_log(item_id):
    """The whole trail for one item, oldest first."""
    try:
        conn, cur = connection()
        cur.execute("""
            SELECT l.id, l.action, l.detail, l.amount, l.added_date,
                   l.proposal_id, u.name AS actor_name
            FROM costing_log l
            LEFT JOIN user u ON u.id = l.actor_id
            WHERE l.item_id = %s
            ORDER BY l.added_date, l.id
        """, (item_id,))
        entries = [{
            'action': row['action'],
            'detail': row['detail'],
            'amount': float(row['amount']) if row['amount'] is not None else None,
            'actor_name': row['actor_name'],
            'proposal_id': row['proposal_id'],
            'when': row['added_date'].strftime('%d %b %Y %H:%M')
                    if row['added_date'] else None,
        } for row in cur.fetchall()]
        cur.close()
        conn.close()
        return jsonify(success=True, entries=entries)
    except HTTPException:
        raise
    except Exception as e:
        return jsonify(success=False, error=str(e)), 500


# ---------------------------------------------------------------------------
# Department portals with nothing in them yet.
#
# Four cards on the home page pointed at '#': Marketing, Account Management, 2D
# and 3D Design. Each now lands on a real page of its own, gated by a permission
# only that department holds, so the page exists and is reachable before anyone
# decides what goes on it. Filling one in means changing its render_template
# call; nothing else here is per-department.
# ---------------------------------------------------------------------------

# ---------------------------------------------------------------------------
# What a team can actually do, on the team's own page
#
# Every one of these was reachable only from a navbar menu, which means it was
# reachable only by somebody who already knew it was there. A department's own
# page should say what that department does, so this is the one list of
# destinations and the pages render whichever of them the viewer may open.
#
# (label, description, icon, endpoint, permissions) -- any one permission is
# enough, and an action nobody may open is never drawn.
# ---------------------------------------------------------------------------

