@app.route('/api/sales-requests/items/<int:item_id>/attachments', methods=['POST'])
@perm('sales_request.edit')
def upload_item_attachments(item_id):
    """
    Upload multiple attachments (images/PDFs) for a specific item.
    Supports multiple file upload and stores them organized by item ID.
    """
    if 'user_id' not in session:
        return jsonify({'success': False, 'message': 'Not authenticated'}), 401
    
    try:
        # Check if files are provided
        if 'files[]' not in request.files:
            return jsonify({'success': False, 'message': 'No files provided'}), 400
        
        files = request.files.getlist('files[]')
        request_id = request.form.get('request_id', 'unknown')
        
        # Create item-specific upload directory
        upload_folder = f'uploads/items/{item_id}'
        os.makedirs(upload_folder, exist_ok=True)
        
        uploaded_files = []
        allowed_extensions = {'pdf', 'jpg', 'jpeg', 'png', 'gif', 'bmp', 'webp'}
        max_file_size = 10 * 1024 * 1024  # 10MB
        
        conn, cursor = connection()
        
        # Get item details for logging (item name, request type, request_id)
        cursor.execute("""
            SELECT sri.name as item_name, sri.request_id, 
                   sr.request_type, sr.title as request_title
            FROM sales_request_items sri
            JOIN sales_request sr ON sri.request_id = sr.id
            WHERE sri.id = %s
        """, (item_id,))
        item_info = cursor.fetchone()
        
        if not item_info:
            cursor.close()
            conn.close()
            return jsonify({'success': False, 'message': 'Item not found'}), 404
        
        actual_request_id = item_info['request_id']
        item_name = item_info['item_name']
        request_type = item_info['request_type'] or 'Unknown'
        
        for file in files:
            if file and file.filename:
                # Validate file extension
                if '.' not in file.filename:
                    continue
                
                file_ext = file.filename.rsplit('.', 1)[1].lower()
                if file_ext not in allowed_extensions:
                    print(f"Skipping file {file.filename} - invalid extension: {file_ext}")
                    continue
                
                # Validate file size
                file.seek(0, 2)  # Seek to end
                file_size = file.tell()
                file.seek(0)  # Reset to beginning
                
                if file_size > max_file_size:
                    print(f"Skipping file {file.filename} - size {file_size} exceeds 10MB")
                    continue
                
                # Generate unique filename with timestamp
                timestamp = datetime.now().strftime('%Y%m%d_%H%M%S_%f')
                safe_filename = secure_filename(file.filename)
                unique_filename = f"{timestamp}_{safe_filename}"
                file_path = os.path.join(upload_folder, unique_filename)
                
                # Save file to disk
                file.save(file_path)
                print(f"Saved file: {file_path} ({file_size} bytes)")
                
                # Insert record into item_images table
                cursor.execute("""
                    INSERT INTO item_images (item_id, image_path, image_type, file_size, uploaded_by, uploaded_at)
                    VALUES (%s, %s, %s, %s, %s, NOW())
                """, (item_id, file_path, file_ext, file_size, session.get('user_id')))
                
                uploaded_files.append({
                    'filename': unique_filename,
                    'original_name': file.filename,
                    'path': file_path,
                    'size': file_size,
                    'type': file_ext
                })
        
        conn.commit()
        
        # Update item_catalog with first image if this is an image file
        if uploaded_files:
            first_image = None
            image_extensions = ['jpg', 'jpeg', 'png', 'gif', 'bmp', 'webp']
            for uf in uploaded_files:
                if uf['type'] in image_extensions:
                    first_image = uf['path']
                    break
            
            if first_image:
                try:
                    # Get item details to find matching catalog entry
                    cursor.execute("""
                        SELECT name, unit, 
                               JSON_EXTRACT(attributes, '$.width') as width,
                               JSON_EXTRACT(attributes, '$.height') as height,
                               JSON_EXTRACT(attributes, '$.depth') as depth
                        FROM sales_request_items
                        WHERE id = %s
                    """, (item_id,))
                    item_details = cursor.fetchone()
                    
                    if item_details:
                        # Parse dimensions from JSON
                        width = float(item_details['width']) if item_details['width'] and str(item_details['width']).strip() not in ('', 'null', 'None', '"null"') else None
                        height = float(item_details['height']) if item_details['height'] and str(item_details['height']).strip() not in ('', 'null', 'None', '"null"') else None
                        depth = float(item_details['depth']) if item_details['depth'] and str(item_details['depth']).strip() not in ('', 'null', 'None', '"null"') else None
                        
                        # Update catalog entry with image (only if image_path is NULL)
                        cursor.execute("""
                            UPDATE item_catalog
                            SET image_path = %s
                            WHERE name = %s 
                            AND unit = %s
                            AND (width <=> %s) AND (height <=> %s) AND (depth <=> %s)
                            AND (image_path IS NULL OR image_path = '')
                        """, (first_image, item_details['name'], item_details['unit'], width, height, depth))
                        
                        if cursor.rowcount > 0:
                            print(f"DEBUG: Updated catalog entry with image: {first_image}")
                        
                        conn.commit()
                except Exception as catalog_err:
                    print(f"DEBUG: Could not update catalog with image: {catalog_err}")
        
        # Log each attachment upload using item-specific logging
        username = (session.get('name') or session.get('username') or 'Unknown')
        for uploaded_file in uploaded_files:
            file_info = {
                'filename': uploaded_file['original_name'],
                'size': uploaded_file['size'],
                'type': uploaded_file['type'],
                'path': uploaded_file['path']
            }
            
            log_item_change(
                request_id=actual_request_id,
                item_id=item_id,
                item_name=item_name,
                request_type=request_type,
                action_type='ATTACHMENT_ADD',
                action_by=username,
                old_data=None,
                new_data=file_info,
                change_description=f"Added attachment '{uploaded_file['original_name']}' ({uploaded_file['size']} bytes)"
            )
        
        cursor.close()
        conn.close()
        
        return jsonify({
            'success': True,
            'uploaded_files': uploaded_files,
            'upload_count': len(uploaded_files),
            'item_id': item_id,
            'message': f'Successfully uploaded {len(uploaded_files)} file(s)'
        })
        
    except Exception as e:
        print(f"Error uploading item attachments: {str(e)}")
        traceback.print_exc()
        return jsonify({
            'success': False,
            'error': str(e),
            'message': 'Failed to upload attachments'
        }), 500


@app.route('/api/sales-requests/items/<int:item_id>/attachments', methods=['GET'])
@perm('sales_request.view')
def get_item_attachments(item_id):
    """
    Retrieve all attachments for a specific item.
    Returns list of files with metadata and download URLs.
    """
    if 'user_id' not in session:
        return jsonify({'success': False, 'message': 'Not authenticated'}), 401
    
    try:
        conn, cursor = connection()
        
        cursor.execute("""
            SELECT id, image_path, image_type, file_size, uploaded_at, uploaded_by
            FROM item_images
            WHERE item_id = %s AND is_alternative = 0
            ORDER BY uploaded_at DESC
        """, (item_id,))
        
        rows = cursor.fetchall()
        attachments = []
        total_size = 0
        
        for row in rows:
            file_path = row['image_path']
            file_exists = os.path.exists(file_path)
            filename = os.path.basename(file_path)
            
            attachments.append({
                'id': row['id'],
                'path': file_path,
                'filename': filename,
                'type': row['image_type'],
                'size': row['file_size'],
                'size_mb': round(row['file_size'] / (1024 * 1024), 2) if row['file_size'] else 0,
                'uploaded_at': row['uploaded_at'].strftime('%Y-%m-%d %H:%M:%S') if row['uploaded_at'] else None,
                'uploaded_by': row['uploaded_by'],
                'exists': file_exists,
                'url': f'/uploads/items/{item_id}/{filename}' if file_exists else None,
                'is_image': row['image_type'] in ['jpg', 'jpeg', 'png', 'gif', 'bmp', 'webp'],
                'is_pdf': row['image_type'] == 'pdf'
            })
            total_size += row['file_size'] or 0
        
        cursor.close()
        conn.close()
        
        return jsonify({
            'success': True,
            'attachments': attachments,
            'total_count': len(attachments),
            'total_size': total_size,
            'total_size_mb': round(total_size / (1024 * 1024), 2),
            'item_id': item_id
        })
        
    except Exception as e:
        print(f"Error fetching item attachments: {str(e)}")
        traceback.print_exc()
        return jsonify({
            'success': False,
            'error': str(e)
        }), 500


@app.route('/api/sales-requests/items/<int:item_id>/attachments/<int:attachment_id>', methods=['DELETE'])
@perm('sales_request.edit')
def delete_item_attachment(item_id, attachment_id):
    """
    Delete a specific attachment from an item.
    Removes both database record and physical file.
    """
    if 'user_id' not in session:
        return jsonify({'success': False, 'message': 'Not authenticated'}), 401
    
    try:
        conn, cursor = connection()
        
        # Get file path and item details before deleting
        cursor.execute("""
            SELECT ii.image_path, ii.file_size, ii.image_type,
                   sri.name as item_name, sri.request_id,
                   sr.request_type, sr.title as request_title
            FROM item_images ii
            JOIN sales_request_items sri ON ii.item_id = sri.id
            JOIN sales_request sr ON sri.request_id = sr.id
            WHERE ii.id = %s AND ii.item_id = %s
        """, (attachment_id, item_id))
        
        result = cursor.fetchone()
        if not result:
            cursor.close()
            conn.close()
            return jsonify({'success': False, 'message': 'Attachment not found'}), 404
        
        file_path = result['image_path']
        item_name = result['item_name']
        request_id = result['request_id']
        request_type = result['request_type'] or 'Unknown'
        file_size = result['file_size']
        file_type = result['image_type']
        
        # Delete from database
        cursor.execute("DELETE FROM item_images WHERE id = %s", (attachment_id,))
        conn.commit()
        
        # Log the deletion using item-specific logging
        username = (session.get('name') or session.get('username') or 'Unknown')
        filename = os.path.basename(file_path)
        file_info = {
            'filename': filename,
            'size': file_size,
            'type': file_type,
            'path': file_path
        }
        
        log_item_change(
            request_id=request_id,
            item_id=item_id,
            item_name=item_name,
            request_type=request_type,
            action_type='ATTACHMENT_REMOVE',
            action_by=username,
            old_data=file_info,
            new_data=None,
            change_description=f"Removed attachment '{filename}' ({file_size} bytes)"
        )
        
        cursor.close()
        conn.close()
        
        # Delete physical file
        if os.path.exists(file_path):
            os.remove(file_path)
            print(f"Deleted file: {file_path}")
            
            # Remove directory if empty
            dir_path = os.path.dirname(file_path)
            if os.path.exists(dir_path) and not os.listdir(dir_path):
                os.rmdir(dir_path)
                print(f"Removed empty directory: {dir_path}")
        
        return jsonify({
            'success': True,
            'message': 'Attachment deleted successfully',
            'attachment_id': attachment_id,
            'item_id': item_id
        })
        
    except Exception as e:
        print(f"Error deleting item attachment: {str(e)}")
        traceback.print_exc()
        return jsonify({
            'success': False,
            'error': str(e),
            'message': 'Failed to delete attachment'
        }), 500

# Uploaded files. nginx used to serve uploads/ straight off the disk to anyone
# holding a link; now every file comes through here, behind the login, and
# only to people who may see the record it belongs to.
UPLOADS_DIR = os.path.join(os.path.dirname(os.path.abspath(__file__)), 'uploads')

# Desks that work on any request's items (costing, pricing, operations, client
# approval). Their own pages are gated by holding the permission, not by who
# owns the request, so their files are too.
ITEM_FILE_DESKS = ('costing.view', 'sales_item.cost', 'sales_item.price', 'approved_item.view',
                   'client_approval.view', 'negotiation.view', 'supplier_report.view')
UPLOAD_MIMETYPES = {
    'pdf': 'application/pdf', 'jpg': 'image/jpeg', 'jpeg': 'image/jpeg', 'png': 'image/png',
    'gif': 'image/gif', 'bmp': 'image/bmp', 'webp': 'image/webp', 'heic': 'image/heic',
}


def _request_file_allowed(cur, request_id):
    """May the caller see files of this sales request (or of an unknown one, when None)?"""
    if any(has(code) for code in ITEM_FILE_DESKS):
        return True
    if not has('sales_request.view'):
        return False
    if request_id is None:
        # The record is gone or the file predates its table: what is left is
        # who may see requests at all.
        return True
    cur.execute("SELECT owner_user_id FROM sales_request WHERE id = %s", (request_id,))
    row = cur.fetchone()
    return row is None or _scope_covers('sales_request.view', row['owner_user_id'])


def upload_access_allowed(cur, parts):
    """`parts` is the path under uploads/, split on '/'. True when the caller may read it."""
    folder = parts[0] if parts else ''
    owner_id = int(parts[1]) if len(parts) > 2 and parts[1].isdigit() else None
    if folder == 'companies':
        return has('company.view') or has('client.view')
    if folder in ('items', 'alternatives'):
        request_id = None
        if owner_id is not None:
            cur.execute("SELECT request_id FROM sales_request_items WHERE id = %s", (owner_id,))
            row = cur.fetchone()
            request_id = row['request_id'] if row else None
        return _request_file_allowed(cur, request_id)
    if folder == 'costing':
        # A costing proposal's files are supplier quotations: cost, so only
        # the desks that see cost (Gamal, 2026-10-28). Seeing the request was
        # enough before, which let an Account Manager open one by its link.
        if not (has('costing.view') or may_see_cost()):
            return False
        request_id = None
        if owner_id is not None:
            cur.execute("SELECT request_id FROM costing_proposal WHERE id = %s", (owner_id,))
            row = cur.fetchone()
            request_id = row['request_id'] if row else None
        return _request_file_allowed(cur, request_id)
    if folder == 'sales_requests':
        return _request_file_allowed(cur, owner_id)
    if folder == 'design' and owner_id is not None:
        cur.execute("SELECT created_by, designer_id, status FROM design_request WHERE id = %s", (owner_id,))
        row = cur.fetchone()
        return bool(row) and design_request_visible(row)
    return False


@app.route('/uploads/<path:subpath>')
@perm('sales_request.view', 'company.view', 'client.view', *ITEM_FILE_DESKS, *DESIGN_PAGE_PERMS)
def serve_upload(subpath):
    """Any file under uploads/, to whoever may see the record it belongs to."""
    root = os.path.realpath(UPLOADS_DIR)
    path = os.path.realpath(os.path.join(root, subpath))
    if not path.startswith(root + os.sep) or not os.path.isfile(path):
        abort(404)
    conn, cur = connection()
    try:
        allowed = upload_access_allowed(cur, os.path.relpath(path, root).split(os.sep))
    finally:
        cur.close()
        conn.close()
    if not allowed:
        abort(403)
    ext = path.rsplit('.', 1)[-1].lower() if '.' in path else ''
    mimetype = UPLOAD_MIMETYPES.get(ext)
    response = send_file(path, mimetype=mimetype or 'application/octet-stream',
                         as_attachment=mimetype is None, conditional=True)
    # Private to this browser: a shared cache must not hand it to someone else.
    response.headers['Cache-Control'] = 'private, max-age=3600'
    return response

