@app.route('/api/client-approval/items/<int:item_id>/approve', methods=['POST'])
@perm('client_approval.decide')
def approve_item(item_id):
    """Approve an item (can be used by admin or when client approves)"""
    if 'user_id' not in session:
        return jsonify({'success': False, 'error': 'Not authenticated'}), 401
    
    try:
        data = request.get_json()
        feedback = data.get('feedback', '')
        user_id = session.get('user_id')
        user_name = session.get('name', 'Unknown')
        
        conn, cur = connection()

        if item_outside_decide_scope(cur, item_id):
            cur.close()
            conn.close()
            return jsonify({'success': False, 'error': DECIDE_OUTSIDE_SCOPE}), 403
        
        # Get item details
        cur.execute("""
            SELECT i.*, sr.client_id
            FROM sales_request_items i
            INNER JOIN sales_request sr ON i.request_id = sr.id
            WHERE i.id = %s
        """, (item_id,))
        
        item = cur.fetchone()
        
        if not item:
            cur.close()
            conn.close()
            return jsonify({
                'success': False,
                'error': 'Item not found'
            }), 404
        
        # Update item status
        cur.execute("""
            UPDATE sales_request_items
            SET approval_status = 'approved',
                client_approval_date = NOW(),
                client_feedback = %s
            WHERE id = %s
        """, (feedback, item_id))
        
        # Log the approval
        cur.execute("""
            INSERT INTO item_client_approval_log
            (item_id, request_id, action_type, action_by, previous_status, new_status, notes)
            VALUES (%s, %s, 'approved', %s, %s, 'approved', %s)
        """, (
            item_id,
            item['request_id'],
            user_id,
            item['approval_status'] or 'submitted',
            feedback
        ))
        
        # Log in main change log
        log_item_change(
            request_id=item['request_id'],
            item_id=item_id,
            item_name=item['name'],
            request_type=item.get('request_type', 'General'),
            action_type='CLIENT_APPROVED',
            action_by=user_name,
            change_description=f"[Client Approval] Item '{item['name']}' approved by client" + (f". Feedback: {feedback}" if feedback else ""),
            conn=conn,
            cur=cur
        )
        
        # Update request's overall approval stage
        update_request_approval_stage(item['request_id'], conn, cur)
        
        conn.commit()

        # A client's yes is where Operations' work starts, and nothing told
        # them: the item simply appeared on the Approved Items page for
        # whoever happened to open it. The whole team hears now.
        try:
            notify_users(operations_team_ids(cur),
                         'Client approved: %s' % item['name'],
                         'The client approved "%s" on request #%s. It is ready for '
                         'Operations to source and deliver.' % (item['name'], item['request_id']),
                         link='/approved-items?request=%s' % item['request_id'])
        except Exception as notify_error:
            print(f"Approval notification failed: {notify_error}")

        cur.close()
        conn.close()
        
        return jsonify({
            'success': True,
            'message': 'Item approved successfully'
        })
        
    except Exception as e:
        print(f"Error approving item: {str(e)}")
        return jsonify({
            'success': False,
            'error': str(e)
        }), 500

