@app.route('/api/mention-users', methods=['GET'])
def mention_users():
    """
    Who can be tagged in a comment.

    The comment box was reading `/api/users`, which is the account-management
    list and is gated on `user.view` -- an admin permission. Everyone else got
    a 403, the list stayed empty, and typing `@` did nothing at all. Tagging a
    colleague is not administering them, so it has its own endpoint: names,
    roles and departments, and nothing else. No mobile, no email, no password
    state.
    """
    try:
        conn, cur = connection()
        # Inside a chat, the people in that chat and nobody else: tagging
        # someone who cannot read it tells them about a message they cannot open.
        only = None
        if request.args.get('thread'):
            only = chat_members(cur, *chat_thread_or_403(cur, request.args['thread']))
            if not only:
                return jsonify(success=True, users=[])
        cur.execute("""
            SELECT u.id, u.name, r.name AS role_name, d.name AS department_name
            FROM user u
            LEFT JOIN rbac_role r ON r.id = u.rbac_role_id
            LEFT JOIN department d ON d.id = u.department_id
            WHERE u.is_active = 1""" + (" AND u.id IN (" + ",".join(["%s"] * len(only)) + ")" if only else "") + """
            ORDER BY d.name, r.level, u.name
        """, only or ())
        people = [{'id': row['id'], 'name': row['name'],
                   'role_name': row['role_name'] or '',
                   'department_name': row['department_name'] or ''}
                  for row in cur.fetchall()]
        cur.close()
        conn.close()
        return jsonify(success=True, users=people)
    except HTTPException:
        raise
    except Exception as e:
        print("DEBUG: mention users failed: %s" % e)
        return jsonify(success=False, error=str(e)), 500


@app.route('/api/sales/requests/<int:request_id>/comments', methods=['GET'])
@perm('sales_request.comment')
def get_sales_request_comments(request_id):
    """Get all comments for a sales request with mentions"""
    if 'user_id' not in session:
        return jsonify({'success': False, 'error': 'Not authenticated'}), 401
    
    try:
        conn, cur = connection()
        
        # Get filter parameters
        source_filter = request.args.get('source', '')
        show_notes = request.args.get('show_notes', 'true').lower() == 'true'
        
        # Build query
        query = """
            SELECT 
                c.id,
                c.request_id,
                c.comment_text,
                c.source,
                c.is_note,
                c.parent_comment_id,
                c.created_at,
                c.updated_at,
                c.user_id,
                u.name as user_name,
                u.mobile as user_mobile,
                (SELECT COUNT(*) FROM sales_request_comment_mentions WHERE comment_id = c.id) as mention_count,
                (SELECT GROUP_CONCAT(mu.name SEPARATOR ', ') 
                 FROM sales_request_comment_mentions m 
                 JOIN user mu ON m.mentioned_user_id = mu.id 
                 WHERE m.comment_id = c.id) as mentioned_users
            FROM sales_request_comments c
            JOIN user u ON c.user_id = u.id
            WHERE c.request_id = %s AND c.is_deleted = FALSE
        """
        
        params = [request_id]
        
        if source_filter:
            query += " AND c.source = %s"
            params.append(source_filter)
        
        if not show_notes:
            query += " AND c.is_note = FALSE"
        
        query += " ORDER BY c.created_at DESC, c.id DESC"

        if not chat_may_open(cur, 'sr', request_id):
            cur.close()
            conn.close()
            return jsonify({'success': False, 'error': 'This chat is not yours to read'}), 403

        cur.execute(query, params)
        comments = list(cur.fetchall())
        thread = 'sr:%d' % request_id
        # The chat drawer, while this chat is on screen: I have seen it.
        if request.args.get('seen') == '1' and comments:
            chat_mark_seen(cur, thread, session['user_id'], max(c['id'] for c in comments))
            conn.commit()
        members = chat_members(cur, 'sr', request_id) if request.args.get('receipts') == '1' else None
        chat_decorate(cur, thread, comments, members)
        
        # Get my mentions count
        cur.execute("""
            SELECT COUNT(*) as unread_mentions
            FROM sales_request_comment_mentions m
            JOIN sales_request_comments c ON m.comment_id = c.id
            WHERE m.mentioned_user_id = %s 
            AND m.is_read = FALSE
            AND c.request_id = %s
            AND c.is_deleted = FALSE
        """, (session['user_id'], request_id))
        
        unread_mentions = cur.fetchone()['unread_mentions']
        
        cur.close()
        conn.close()
        
        return jsonify({
            'success': True,
            'comments': comments,
            'unread_mentions': unread_mentions
        })
        
    except Exception as e:
        print(f"Error fetching comments: {str(e)}")
        return jsonify({'success': False, 'error': str(e)}), 500


@app.route('/api/sales/requests/<int:request_id>/comments', methods=['POST'])
@perm('sales_request.comment')
def add_sales_request_comment(request_id):
    """Add a comment/note to a sales request with @mention support"""
    if 'user_id' not in session:
        return jsonify({'success': False, 'error': 'Not authenticated'}), 401
    
    try:
        data, upload = chat_request_payload()
        comment_text = (data.get('comment_text') or '').strip()
        if data.get('sticker_id') and not upload:
            data['kind'] = 'sticker'
            comment_text = CHAT_PLACEHOLDER['sticker']
        if upload and not comment_text:
            comment_text = CHAT_PLACEHOLDER.get(data.get('kind'), '')
        source = data.get('source', 'general')
        is_note = data.get('is_note', False)
        parent_comment_id = data.get('parent_comment_id') or data.get('reply_to')
        mentioned_user_ids = data.get('mentioned_users', [])  # List of user IDs
        
        if not comment_text:
            return jsonify({'success': False, 'error': 'Comment text is required'}), 400
        
        # Validate source
        valid_sources = ['general', 'client_approval_page', 'costing', 'selling_price', 
                        'operations', 'logistics', 'design', 'production']
        if source not in valid_sources:
            source = 'general'
        
        conn, cur = connection()
        user_id = session['user_id']
        user_name = session.get('name', 'Unknown User')
        
        # Verify request exists
        cur.execute("SELECT id, title FROM sales_request WHERE id = %s", (request_id,))
        request_info = cur.fetchone()
        
        if not request_info:
            cur.close()
            conn.close()
            return jsonify({'success': False, 'error': 'Request not found'}), 404
        if not chat_may_open(cur, 'sr', request_id):
            cur.close()
            conn.close()
            return jsonify({'success': False, 'error': 'This chat is not yours to write in'}), 403
        
        # A reply quotes a message of this same chat, or nothing.
        parent_comment_id = chat_reply_target(cur, 'sr', request_id, parent_comment_id)

        # Insert comment
        cur.execute("""
            INSERT INTO sales_request_comments 
            (request_id, user_id, comment_text, source, is_note, parent_comment_id)
            VALUES (%s, %s, %s, %s, %s, %s)
        """, (request_id, user_id, comment_text, source, is_note, parent_comment_id))
        
        comment_id = cur.lastrowid
        if upload or data.get('sticker_id'):
            error = (chat_save_attachment(cur, 'sr:%d' % request_id, comment_id, upload,
                                          data.get('kind'), data.get('duration_ms'))
                     if upload else chat_attach_sticker(cur, 'sr:%d' % request_id, comment_id, data.get('sticker_id')))
            if error:
                conn.rollback()
                cur.close()
                conn.close()
                return jsonify({'success': False, 'error': error}), 400
        chat_mark_seen(cur, 'sr:%d' % request_id, user_id, comment_id)
        
        # Process mentions.
        #
        # This used to INSERT INTO `notifications`, a MySQL table that does not
        # exist on this system -- notifications live in Mongo and are written
        # by notify_users(). The insert raised, the except swallowed it, and
        # nobody was ever told they had been mentioned.
        notification_sent_to = []
        mentioned = []
        # @all tags everyone who is in this request's chat.
        if chat_mentions_all(comment_text, mentioned_user_ids):
            mentioned_user_ids = [u for u in chat_members(cur, 'sr', request_id) if u != user_id]
        for mentioned_user_id in (mentioned_user_ids or []):
            try:
                mentioned_user_id = int(mentioned_user_id)
            except (TypeError, ValueError):
                continue
            try:
                cur.execute("""
                    INSERT INTO sales_request_comment_mentions 
                    (comment_id, mentioned_user_id)
                    VALUES (%s, %s)
                    ON DUPLICATE KEY UPDATE comment_id = comment_id
                """, (comment_id, mentioned_user_id))
                cur.execute("SELECT name, mobile FROM user WHERE id = %s",
                            (mentioned_user_id,))
                mentioned_user = cur.fetchone()
                if mentioned_user:
                    mentioned.append(mentioned_user_id)
                    notification_sent_to.append(mentioned_user['name'])
            except Exception as mention_error:
                print(f"Error processing mention for user {mentioned_user_id}: {str(mention_error)}")

        # Everyone with a part in this request hears about it, not only the
        # people named with an @: a comment on a request nobody is told about
        # is a comment nobody reads.
        audience = sales_request_audience(cur, request_id, exclude=[user_id] + mentioned)
        excerpt = comment_text[:120] + ('...' if len(comment_text) > 120 else '')
        # Opens the chat itself (in place when the app is already open).
        deep_link = '/home?chat=sr:%d' % request_id
        if mentioned:
            notify_users(
                mentioned,
                '%s mentioned you: request #%d' % (user_name, request_id),
                '%s &mdash; "%s"' % (request_info.get('title') or 'Sales request', excerpt),
                link=deep_link)
        if audience:
            notify_users(
                audience,
                'New %s on request #%d' % ('note' if is_note else 'comment', request_id),
                '%s on "%s": "%s"'
                % (user_name, request_info.get('title') or 'a sales request', excerpt),
                link=deep_link)
        
        # Log the comment in change log
        source_labels = {
            'general': 'General',
            'client_approval': 'Client Approval',
            'costing': 'Costing',
            'selling_price': 'Selling Price',
            'operations': 'Operations',
            'logistics': 'Logistics',
            'design': 'Design',
            'production': 'Production'
        }
        
        comment_type = "Note" if is_note else "Comment"
        description = f"{comment_type} added in {source_labels.get(source, source)}: {comment_text[:100]}{'...' if len(comment_text) > 100 else ''}"
        
        log_request_change(
            request_id=request_id,
            action_type='comment_added',
            action_by=user_name,
            change_description=description,
            conn=conn,
            cur=cur
        )
        
        conn.commit()
        
        # Get the created comment with user info
        cur.execute("""
            SELECT 
                c.id,
                c.comment_text,
                c.source,
                c.is_note,
                c.created_at,
                u.name as user_name
            FROM sales_request_comments c
            JOIN user u ON c.user_id = u.id
            WHERE c.id = %s
        """, (comment_id,))
        
        created_comment = cur.fetchone()
        
        cur.close()
        conn.close()
        
        return jsonify({
            'success': True,
            'message': f'{comment_type} added successfully',
            'comment': created_comment,
            'notifications_sent': len(notification_sent_to),
            'notified_users': notification_sent_to
        })
        
    except Exception as e:
        print(f"Error adding comment: {str(e)}")
        return jsonify({'success': False, 'error': str(e)}), 500


@app.route('/api/sales/requests/comments/<int:comment_id>', methods=['PUT'])
@perm('sales_request.comment')
def update_sales_request_comment(comment_id):
    """Update a comment (only by the author)"""
    if 'user_id' not in session:
        return jsonify({'success': False, 'error': 'Not authenticated'}), 401
    
    try:
        data = request.get_json()
        comment_text = data.get('comment_text', '').strip()
        
        if not comment_text:
            return jsonify({'success': False, 'error': 'Comment text is required'}), 400
        
        conn, cur = connection()
        user_id = session['user_id']
        
        # Verify ownership
        cur.execute("""
            SELECT user_id, request_id FROM sales_request_comments 
            WHERE id = %s AND is_deleted = FALSE
        """, (comment_id,))
        
        comment = cur.fetchone()
        
        if not comment:
            cur.close()
            conn.close()
            return jsonify({'success': False, 'error': 'Comment not found'}), 404
        
        if comment['user_id'] != user_id:
            cur.close()
            conn.close()
            return jsonify({'success': False, 'error': 'Unauthorized'}), 403
        
        # Update comment
        cur.execute("""
            UPDATE sales_request_comments 
            SET comment_text = %s, updated_at = NOW()
            WHERE id = %s
        """, (comment_text, comment_id))
        
        conn.commit()
        cur.close()
        conn.close()
        
        return jsonify({
            'success': True,
            'message': 'Comment updated successfully'
        })
        
    except Exception as e:
        print(f"Error updating comment: {str(e)}")
        return jsonify({'success': False, 'error': str(e)}), 500


@app.route('/api/sales/requests/comments/<int:comment_id>', methods=['DELETE'])
@perm('sales_request.comment')
def delete_sales_request_comment(comment_id):
    """Soft delete a comment (only by author or admin)"""
    if 'user_id' not in session:
        return jsonify({'success': False, 'error': 'Not authenticated'}), 401
    
    try:
        conn, cur = connection()
        user_id = session['user_id']
        user_roles = session.get('roles', [])
        
        # Get comment info
        cur.execute("""
            SELECT user_id, request_id FROM sales_request_comments 
            WHERE id = %s AND is_deleted = FALSE
        """, (comment_id,))
        
        comment = cur.fetchone()
        
        if not comment:
            cur.close()
            conn.close()
            return jsonify({'success': False, 'error': 'Comment not found'}), 404
        
        # Check permission (author or admin)
        if comment['user_id'] != user_id and 'admin' not in user_roles:
            cur.close()
            conn.close()
            return jsonify({'success': False, 'error': 'Unauthorized'}), 403
        
        # Soft delete
        cur.execute("""
            UPDATE sales_request_comments 
            SET is_deleted = TRUE, deleted_at = NOW(), deleted_by = %s
            WHERE id = %s
        """, (user_id, comment_id))
        
        conn.commit()
        cur.close()
        conn.close()
        
        return jsonify({
            'success': True,
            'message': 'Comment deleted successfully'
        })
        
    except Exception as e:
        print(f"Error deleting comment: {str(e)}")
        return jsonify({'success': False, 'error': str(e)}), 500


