@app.route('/api/chat/sr-list', methods=['GET'])
@perm('sales_request.view')
def get_chat_sr_list():
    """
    Global chat list for the slide-in chat drawer.
    Returns every sales request that has at least one comment, along with the
    latest message preview, total message count, and how many mentions of the
    current user are still unread in that request.
    """
    if 'user_id' not in session:
        return jsonify({'success': False, 'error': 'Not authenticated'}), 401

    try:
        conn, cur = connection()
        user_id = session['user_id']

        scope_sql, scope_params = (('', []) if has('chat.all') else
                                   scope_clause('sales_request.view', 'sr.owner_user_id'))
        # The same people chat_may_open lets in: inside the comment scope, or
        # working the request (costing assignee or assigner), or already in
        # its thread. Without it an Operations member's list was every request
        # (view scope 'all') and every one of them answered 403.
        if has('sales_request.comment') and not has('chat.all'):
            own_sql, own_params = scope_clause('sales_request.comment', 'sr.owner_user_id')
            if own_sql:
                inner = own_sql[len(' AND '):]
                scope_sql = (" AND (" + inner + " OR sr.id IN (SELECT request_id FROM costing_assignment"
                             " WHERE status <> 'withdrawn' AND (assignee_id = %s OR assigned_by = %s))"
                             " OR sr.id IN (SELECT request_id FROM sales_request_comments"
                             " WHERE user_id = %s AND is_deleted = 0))")
                scope_params = own_params + [user_id, user_id, user_id]
            else:
                scope_sql, scope_params = '', []

        cur.execute(
            """
            SELECT
                sr.id            AS request_id,
                sr.title         AS title,
                cl.client_name   AS client_name,
                comp.company_name AS company_name,
                COALESCE(stats.total_messages, 0) AS total_messages,
                stats.last_message_at,
                lm.comment_text  AS last_message_text,
                lm.user_id       AS last_message_user_id,
                lu.name          AS last_message_user_name,
                COALESCE(unread.unread_mentions, 0) AS unread_mentions,
                sr.created_at    AS sr_created_at
            FROM sales_request sr
            LEFT JOIN (
                SELECT request_id,
                       COUNT(*)        AS total_messages,
                       MAX(created_at) AS last_message_at,
                       MAX(id)         AS last_comment_id
                FROM sales_request_comments
                WHERE is_deleted = 0
                GROUP BY request_id
            ) stats ON stats.request_id = sr.id
            LEFT JOIN sales_request_comments lm ON lm.id = stats.last_comment_id
            LEFT JOIN user lu ON lu.id = lm.user_id
            LEFT JOIN client cl ON cl.id = sr.client_id
            LEFT JOIN company comp ON comp.id = sr.company_id
            LEFT JOIN (
                SELECT c.request_id,
                       COUNT(*) AS unread_mentions
                FROM sales_request_comment_mentions m
                JOIN sales_request_comments c ON c.id = m.comment_id
                WHERE m.mentioned_user_id = %s
                  AND m.is_read = 0
                  AND c.is_deleted = 0
                GROUP BY c.request_id
            ) unread ON unread.request_id = sr.id
            WHERE 1=1 """ + scope_sql + """
            ORDER BY COALESCE(stats.last_message_at, sr.created_at) DESC
            LIMIT 500
            """,
            [user_id] + scope_params
        )
        rows = cur.fetchall() or []

        chats = []
        total_unread = 0
        for r in rows:
            unread = int(r.get('unread_mentions') or 0)
            total_unread += unread
            preview = (r.get('last_message_text') or '')
            if len(preview) > 120:
                preview = preview[:117] + '...'
            last_at = r.get('last_message_at')
            chats.append({
                'request_id': r.get('request_id'),
                'title': r.get('title') or '',
                'client_name': r.get('client_name') or '',
                'company_name': r.get('company_name') or '',
                'total_messages': int(r.get('total_messages') or 0),
                'last_message_text': preview,
                'last_message_user': r.get('last_message_user_name') or '',
                'last_message_at': last_at.strftime('%Y-%m-%d %H:%M:%S') if last_at else None,
                'sr_created_at': r['sr_created_at'].strftime('%Y-%m-%d %H:%M:%S') if r.get('sr_created_at') else None,
                'unread_mentions': unread,
            })

        cur.close()
        conn.close()

        return jsonify({
            'success': True,
            'chats': chats,
            'total_unread': total_unread,
        })

    except Exception as e:
        print(f"Error fetching chat SR list: {str(e)}")
        return jsonify({'success': False, 'error': str(e)}), 500


# ---- group chats --------------------------------------------------------------
# Three rooms beside the per-request chats. Who is in a room follows the
# person's current role level and department, so there is no member list to
# keep: someone who moves to Operations is in the Operations room the next
# time the drawer polls.
CHAT_ROOMS = {
    'managers':   {'title': 'Managers',   'icon': 'fa-user-tie'},
    'operations': {'title': 'Operations', 'icon': 'fa-cogs'},
    'sales':      {'title': 'Sales',      'icon': 'fa-chart-line'},
}
_ROOM_MEMBERS_SQL = {
    # Executive and Head / Manager level.
    'managers': "r.level <= 1",
    'operations': "d.code = 'operations'",
    # Nobody active sits in Sales itself; Account Management is who sells.
    'sales': "d.code IN ('sales', 'account')",
}


def chat_everywhere():
    """Who is in every chat and group whatever their department: chat.all,
    held by the CEO (Beshoy, 2026-10-29) and anyone given it."""
    return set(users_holding('chat.all', include_root=True))


def chat_room_rule_members(cur, room):
    """The ones the room's rule brings in (and the CEO): nobody can remove these."""
    cur.execute("""SELECT u.id FROM user u LEFT JOIN rbac_role r ON r.id = u.rbac_role_id
                   LEFT JOIN department d ON d.id = u.department_id
                   WHERE u.is_active = 1 AND """ + _ROOM_MEMBERS_SQL[room])
    return {row['id'] for row in cur.fetchall()} | chat_everywhere()


def chat_room_added(cur, room):
    """The ones added by hand (chat_group_member), active only."""
    cur.execute("""SELECT m.user_id FROM chat_group_member m JOIN user u ON u.id = m.user_id
                   WHERE m.room = %s AND u.is_active = 1""", (room,))
    return {row['user_id'] for row in cur.fetchall()}


def chat_room_members(cur, room):
    return sorted(chat_room_rule_members(cur, room) | chat_room_added(cur, room))


def chat_rooms_for(cur, user_id):
    """The rooms this person belongs to, in CHAT_ROOMS order."""
    if user_id in chat_everywhere():
        return list(CHAT_ROOMS)
    cur.execute("""SELECT r.level, d.code FROM user u LEFT JOIN rbac_role r ON r.id = u.rbac_role_id
                   LEFT JOIN department d ON d.id = u.department_id
                   WHERE u.id = %s AND u.is_active = 1""", (user_id,))
    me = cur.fetchone()
    if not me:
        return []
    cur.execute("SELECT room FROM chat_group_member WHERE user_id = %s", (user_id,))
    added = {row['room'] for row in cur.fetchall()}
    rooms = []
    if me['level'] is not None and me['level'] <= 1:
        rooms.append('managers')
    if me['code'] == 'operations':
        rooms.append('operations')
    if me['code'] in ('sales', 'account'):
        rooms.append('sales')
    return [room for room in CHAT_ROOMS if room in set(rooms) | added]


def _room_or_403(cur, room):
    if room not in CHAT_ROOMS:
        abort(404)
    if room not in chat_rooms_for(cur, session.get('user_id')):
        abort(403)


@app.route('/api/chat/groups', methods=['GET'])
def chat_groups():
    """My rooms, each with its last message and how many I have not read."""
    if 'user_id' not in session:
        return jsonify(success=False, error='Not authenticated'), 401
    me = session['user_id']
    conn, cur = connection()
    try:
        groups = []
        for room in chat_rooms_for(cur, me):
            cur.execute("""SELECT m.id, m.body, m.created_at, u.name FROM group_chat_message m
                           JOIN user u ON u.id = m.user_id
                           WHERE m.room = %s AND m.is_deleted = 0 ORDER BY m.id DESC LIMIT 1""", (room,))
            last = cur.fetchone()
            cur.execute("""SELECT COUNT(*) AS n FROM group_chat_message m
                           WHERE m.room = %s AND m.is_deleted = 0 AND m.user_id <> %s
                             AND m.id > COALESCE((SELECT MAX(upto_id) FROM chat_seen
                                                  WHERE thread = %s AND user_id = %s), 0)""",
                        (room, me, 'g:' + room, me))
            unread = cur.fetchone()['n']
            groups.append({
                'room': room, 'title': CHAT_ROOMS[room]['title'], 'icon': CHAT_ROOMS[room]['icon'],
                'members': len(chat_room_members(cur, room)),
                'last_message_text': (last['body'][:117] + '...') if last and len(last['body']) > 120 else (last['body'] if last else ''),
                'last_message_user': last['name'] if last else '',
                'last_message_at': last['created_at'].strftime('%Y-%m-%d %H:%M:%S') if last else None,
                'unread': unread,
            })
        return jsonify(success=True, groups=groups, total_unread=sum(g['unread'] for g in groups))
    finally:
        cur.close()
        conn.close()


@app.route('/api/chat/groups/<room>/messages', methods=['GET'])
def chat_group_messages(room):
    """
    The latest 200 messages, newest first (the drawer reverses them), with
    their photos / voice notes and my ticks. `?seen=1` (the drawer, while the
    room is on screen) records that I have seen up to the newest.
    """
    if 'user_id' not in session:
        return jsonify(success=False, error='Not authenticated'), 401
    conn, cur = connection()
    try:
        _room_or_403(cur, room)
        cur.execute("""SELECT m.id, m.body AS comment_text, m.created_at, m.user_id, u.name AS user_name,
                              m.reply_to_id
                       FROM group_chat_message m JOIN user u ON u.id = m.user_id
                       WHERE m.room = %s AND m.is_deleted = 0 ORDER BY m.id DESC LIMIT 200""", (room,))
        rows = list(cur.fetchall())
        thread = 'g:' + room
        if request.args.get('seen') == '1' and rows:
            chat_mark_seen(cur, thread, session['user_id'], rows[0]['id'])
            conn.commit()
        members = chat_room_members(cur, room)
        chat_decorate(cur, thread, rows, members)
        for row in rows:
            row['created_at'] = row['created_at'].strftime('%Y-%m-%d %H:%M:%S')
        return jsonify(success=True, comments=rows, room=room, title=CHAT_ROOMS[room]['title'],
                       members=len(members))
    finally:
        cur.close()
        conn.close()


@app.route('/api/chat/groups/<room>/messages', methods=['POST'])
def chat_group_post(room):
    if 'user_id' not in session:
        return jsonify(success=False, error='Not authenticated'), 401
    data, upload = chat_request_payload()
    text = (data.get('comment_text') or data.get('text') or '').strip()
    if data.get('sticker_id') and not upload:
        data['kind'] = 'sticker'
        text = CHAT_PLACEHOLDER['sticker']
    if upload and not text:
        text = CHAT_PLACEHOLDER.get(data.get('kind'), '')
    if not text:
        return jsonify(success=False, error='Write something first'), 400
    me = session['user_id']
    conn, cur = connection()
    try:
        _room_or_403(cur, room)
        reply_to = chat_reply_target(cur, 'g', room, data.get('reply_to'))
        cur.execute("INSERT INTO group_chat_message (room, user_id, body, reply_to_id) VALUES (%s, %s, %s, %s)",
                    (room, me, text[:4000], reply_to))
        message_id = cur.lastrowid
        if upload or data.get('sticker_id'):
            error = (chat_save_attachment(cur, 'g:' + room, message_id, upload, data.get('kind'), data.get('duration_ms'))
                     if upload else chat_attach_sticker(cur, 'g:' + room, message_id, data.get('sticker_id')))
            if error:
                conn.rollback()
                return jsonify(success=False, error=error), 400
        # Their own message is seen by definition.
        chat_mark_seen(cur, 'g:' + room, me, message_id)
        members = set(chat_room_members(cur, room))
        conn.commit()
    finally:
        cur.close()
        conn.close()
    # A mention is a notification, as in a request chat; only room members.
    if chat_mentions_all(text, data.get('mentioned_users')):
        mentioned = sorted(u for u in members if u != me)
    else:
        mentioned = [int(u) for u in (data.get('mentioned_users') or []) if str(u).isdigit()
                     and int(u) in members and int(u) != me]
    if mentioned:
        name = session.get('name') or 'Someone'
        notify_users(mentioned, '%s mentioned you: %s group' % (name, CHAT_ROOMS[room]['title']),
                     '%s: "%s"' % (name, text[:140]), link='/home?chat=g:%s' % room)
    return jsonify(success=True, id=message_id)


@app.route('/api/chat/groups/<room>/read', methods=['POST'])
def chat_group_read(room):
    if 'user_id' not in session:
        return jsonify(success=False, error='Not authenticated'), 401
    me = session['user_id']
    conn, cur = connection()
    try:
        _room_or_403(cur, room)
        cur.execute("SELECT COALESCE(MAX(id), 0) AS n FROM group_chat_message WHERE room = %s", (room,))
        chat_mark_seen(cur, 'g:' + room, me, cur.fetchone()['n'])
        conn.commit()
        return jsonify(success=True)
    finally:
        cur.close()
        conn.close()


# ---- chat: who is in a thread, photos, voice notes, seen ---------------------
# A thread is 'sr:<request id>' (the request's chat) or 'g:<room>' (a group).
#
# Who is in a request's chat: everyone who may write in it -- holds the comment
# permission and either sees requests of this owner or has a part in this one
# (raised it, costs it, assigned it, already wrote in it). The @ list, the
# "seen by" list and the ticks all read the same members, so the three agree.
CHAT_MEDIA_MAX_BYTES = 16 * 1024 * 1024
CHAT_IMAGE_TYPES = {'image/jpeg': 'jpg', 'image/png': 'png', 'image/webp': 'webp', 'image/gif': 'gif'}
CHAT_VOICE_TYPES = {'audio/webm': 'webm', 'audio/ogg': 'ogg', 'audio/mp4': 'm4a', 'audio/x-m4a': 'm4a',
                    'audio/aac': 'aac', 'audio/mpeg': 'mp3', 'audio/wav': 'wav', 'audio/x-wav': 'wav'}
CHAT_PLACEHOLDER = {'image': '\U0001F4F7 Photo', 'voice': '\U0001F3A4 Voice note', 'sticker': '\u2728 Sticker'}
CHAT_STICKER_MAX_BYTES = 1024 * 1024
CHAT_STICKER_TYPES = {'image/png': 'png', 'image/webp': 'webp', 'image/gif': 'gif', 'image/jpeg': 'jpg'}


def chat_thread(thread):
    """('sr', request_id) or ('g', room) from 'sr:12' / 'g:sales'; 404 otherwise."""
    kind, _, key = (thread or '').partition(':')
    if kind == 'sr' and key.isdigit():
        return 'sr', int(key)
    if kind == 'g' and key in CHAT_ROOMS:
        return 'g', key
    abort(404)


def _scope_reaches(scope, person, owner):
    """Does `scope`, held by `person`, reach a request owned by `owner`? Rows have id, department_id, manager_id."""
    if scope == 'all':
        return True
    if not owner or not scope:
        return False
    if owner['id'] == person['id']:
        return True
    if scope == 'team':
        return owner['manager_id'] == person['id']
    if scope == 'department':
        return bool(person['department_id']) and owner['department_id'] == person['department_id']
    return False


def chat_members(cur, kind, key):
    """Active user ids in this thread."""
    if kind == 'g':
        return chat_room_members(cur, key)
    cur.execute("""SELECT u.id, u.department_id, u.manager_id FROM sales_request sr
                   JOIN user u ON u.id = sr.owner_user_id WHERE sr.id = %s""", (key,))
    owner = cur.fetchone()
    involved = set(sales_request_audience(cur, key))
    cur.execute("SELECT id, department_id, manager_id FROM user WHERE is_active = 1")
    members = []
    # ponytail: one load_permissions per active user (15 today); a role-level
    # cache is the upgrade when the company grows past a few hundred.
    for person in cur.fetchall():
        perms = load_permissions(person['id'])[0]
        if 'sales_request.comment' not in perms:
            continue
        # Comment scope, as in chat_may_open: who may write here, not who may read the request.
        if person['id'] in involved or _scope_reaches(perms.get('sales_request.comment'), person, owner):
            members.append(person['id'])
    return sorted(set(members) | chat_everywhere())


def chat_may_open(cur, kind, key):
    """The signed-in person may read and write in this thread."""
    me = session.get('user_id')
    if kind == 'g':
        return key in chat_rooms_for(cur, me)
    if has('chat.all'):
        return True
    if not has('sales_request.comment'):
        return False
    cur.execute("SELECT owner_user_id FROM sales_request WHERE id = %s", (key,))
    row = cur.fetchone()
    if not row:
        return False
    # The comment scope, not the view scope: an Operations member sees every
    # request (to cost it) but talks only on the ones they work, which the
    # audience below covers -- assigned, assigner, or already in the thread.
    # Every other role holds comment at the same scope as view.
    if _scope_covers('sales_request.comment', row['owner_user_id']):
        return True
    return me in sales_request_audience(cur, key)


def chat_thread_or_403(cur, thread):
    kind, key = chat_thread(thread)
    if not chat_may_open(cur, kind, key):
        abort(403)
    return kind, key


def chat_mark_seen(cur, thread, user_id, upto_id):
    """Move this person's "seen up to" forward; never back."""
    if not upto_id:
        return
    cur.execute("SELECT COALESCE(MAX(upto_id), 0) AS n FROM chat_seen WHERE thread = %s AND user_id = %s",
                (thread, user_id))
    if upto_id > cur.fetchone()['n']:
        cur.execute("INSERT IGNORE INTO chat_seen (thread, user_id, upto_id) VALUES (%s, %s, %s)",
                    (thread, user_id, upto_id))


def chat_seen_upto(cur, thread):
    cur.execute("SELECT user_id, MAX(upto_id) AS upto FROM chat_seen WHERE thread = %s GROUP BY user_id",
                (thread,))
    return {row['user_id']: row['upto'] for row in cur.fetchall()}


MENTION_ALL = re.compile(r'(^|\s)@(all|everyone)(?=$|[\s.,!?;:)\]}])', re.I)


def chat_mentions_all(text, mentioned):
    """True when the message tags everyone in the chat (@all, or the picker's 'all')."""
    return 'all' in [str(u).lower() for u in (mentioned or [])] or bool(MENTION_ALL.search(text or ''))


def chat_reply_target(cur, kind, key, message_id):
    """The id being replied to when it is a live message of this chat; None otherwise."""
    try:
        message_id = int(message_id)
    except (TypeError, ValueError):
        return None
    if kind == 'sr':
        cur.execute("SELECT id FROM sales_request_comments WHERE id = %s AND request_id = %s AND is_deleted = 0",
                    (message_id, key))
    else:
        cur.execute("SELECT id FROM group_chat_message WHERE id = %s AND room = %s AND is_deleted = 0",
                    (message_id, key))
    return message_id if cur.fetchone() else None


def chat_reply_previews(cur, thread, ids):
    """{id: {id, user_id, user_name, text, kind}} for the messages being quoted."""
    ids = sorted({i for i in ids if i})
    if not ids:
        return {}
    marks = ",".join(["%s"] * len(ids))
    if thread.startswith('sr:'):
        cur.execute("SELECT c.id, c.user_id, u.name, c.comment_text AS body, c.is_deleted FROM sales_request_comments c "
                    "JOIN user u ON u.id = c.user_id WHERE c.id IN (" + marks + ")", ids)
    else:
        cur.execute("SELECT m.id, m.user_id, u.name, m.body, m.is_deleted FROM group_chat_message m "
                    "JOIN user u ON u.id = m.user_id WHERE m.id IN (" + marks + ")", ids)
    rows = {r['id']: r for r in cur.fetchall()}
    cur.execute("SELECT message_id, MIN(kind) AS kind FROM chat_attachment WHERE thread = %s AND message_id IN ("
                + marks + ") GROUP BY message_id", [thread] + ids)
    kinds = {r['message_id']: r['kind'] for r in cur.fetchall()}
    out = {}
    for i, r in rows.items():
        text = '' if r['is_deleted'] else (r['body'] or '')
        if kinds.get(i) and text in CHAT_PLACEHOLDER.values():
            text = ''
        out[i] = {'id': i, 'user_id': r['user_id'], 'user_name': r['name'], 'text': text[:200],
                  'kind': kinds.get(i), 'deleted': bool(r['is_deleted'])}
    return out


def chat_decorate(cur, thread, messages, members=None):
    """
    Add each message's photos / voice notes and, on my own messages, the ticks:
    'sent' (nobody else has seen it), 'seen_some', 'seen_all'.
    """
    ids = [m['id'] for m in messages]
    by_message = {}
    if ids:
        cur.execute("SELECT id, message_id, kind, mime, duration_ms, width, height FROM chat_attachment "
                    "WHERE thread = %s AND message_id IN (" + ",".join(["%s"] * len(ids)) + ")",
                    [thread] + ids)
        for row in cur.fetchall():
            by_message.setdefault(row['message_id'], []).append({
                'id': row['id'], 'kind': row['kind'], 'mime': row['mime'],
                'url': '/api/chat/media/%d' % row['id'], 'duration_ms': row['duration_ms'],
                'width': row['width'], 'height': row['height']})
    me = session.get('user_id')
    upto = chat_seen_upto(cur, thread) if members is not None else {}
    reply_key = 'parent_comment_id' if thread.startswith('sr:') else 'reply_to_id'
    quoted = chat_reply_previews(cur, thread, [m.get(reply_key) for m in messages])
    for m in messages:
        m['reply'] = quoted.get(m.get(reply_key))
        m['attachments'] = by_message.get(m['id'], [])
        # The text under a photo; '' when the stored text is only the
        # "Photo" / "Voice note" stand-in that lists and older screens show.
        text = m.get('comment_text') or ''
        m['caption'] = '' if m['attachments'] and text in CHAT_PLACEHOLDER.values() else text
        if members is not None and m.get('user_id') == me:
            others = [u for u in members if u != me]
            seen = sum(1 for u in others if upto.get(u, 0) >= m['id'])
            m['receipt'] = 'seen_all' if others and seen == len(others) else ('seen_some' if seen else 'sent')
            m['seen_count'], m['member_count'] = seen, len(others)
    return messages


def chat_save_attachment(cur, thread, message_id, upload, kind, duration_ms=None):
    """
    Store one photo or voice note for a message. Returns an error string, or None.

    Photos are checked to be images (Pillow) and kept as sent -- the browser
    already shrank them. Voice notes are turned into AAC (.m4a) when they are
    not already, because Safari on an iPhone plays neither WebM nor Ogg.
    """
    import subprocess
    import uuid
    from PIL import Image
    mime = (upload.mimetype or '').split(';')[0].strip().lower()
    types = CHAT_IMAGE_TYPES if kind == 'image' else CHAT_VOICE_TYPES if kind == 'voice' else None
    if not types or mime not in types:
        return 'Only photos and voice notes can be sent here'
    data = upload.read(CHAT_MEDIA_MAX_BYTES + 1)
    if not data:
        return 'The file is empty'
    if len(data) > CHAT_MEDIA_MAX_BYTES:
        return 'Files up to 16 MB'
    slug = thread.replace(':', '-')
    folder = os.path.join(UPLOADS_DIR, 'chat', slug)
    os.makedirs(folder, exist_ok=True)
    name = uuid.uuid4().hex
    path = os.path.join(folder, '%s.%s' % (name, types[mime]))
    with open(path, 'wb') as handle:
        handle.write(data)
    width = height = None
    if kind == 'image':
        try:
            with Image.open(path) as img:
                img.verify()
            with Image.open(path) as img:
                width, height = img.size
        except Exception:
            os.remove(path)
            return 'That photo could not be read'
    elif types[mime] != 'm4a':
        out = os.path.join(folder, name + '.m4a')
        try:
            subprocess.run(['ffmpeg', '-nostdin', '-loglevel', 'error', '-y', '-i', path, '-vn',
                            '-c:a', 'aac', '-b:a', '64k', out], check=True, timeout=90)
            os.remove(path)
            path, mime = out, 'audio/mp4'
        except Exception as e:
            # Kept as recorded: every browser but Safari still plays it.
            print("DEBUG: voice note transcode failed: %s" % e)
            if os.path.exists(out):
                os.remove(out)
    try:
        duration_ms = int(duration_ms) if duration_ms not in (None, '') else None
    except (TypeError, ValueError):
        duration_ms = None
    cur.execute("""INSERT INTO chat_attachment (thread, message_id, user_id, kind, path, mime, bytes,
                                                duration_ms, width, height)
                   VALUES (%s, %s, %s, %s, %s, %s, %s, %s, %s, %s)""",
                (thread, message_id, session['user_id'], kind,
                 os.path.relpath(path, UPLOADS_DIR), mime, os.path.getsize(path),
                 duration_ms, width, height))
    return None


def chat_request_payload():
    """The posted message, from JSON or from a multipart form carrying a file."""
    if request.files:
        form = request.form
        try:
            mentioned = json.loads(form.get('mentioned_users') or '[]')
        except ValueError:
            mentioned = []
        return {'comment_text': form.get('comment_text') or '', 'source': form.get('source') or 'general',
                'is_note': form.get('is_note') in ('1', 'true'), 'mentioned_users': mentioned,
                'kind': form.get('kind'), 'duration_ms': form.get('duration_ms'),
                'reply_to': form.get('reply_to'), 'sticker_id': form.get('sticker_id')}, request.files.get('file')
    return (request.get_json(silent=True) or {}), None


@app.route('/api/chat/thread/<thread>/members', methods=['GET'])
def chat_thread_members(thread):
    """Who is in this chat: the @ list and the member list in the header."""
    if 'user_id' not in session:
        return jsonify(success=False, error='Not authenticated'), 401
    conn, cur = connection()
    try:
        kind, key = chat_thread_or_403(cur, thread)
        ids = chat_members(cur, kind, key)
        # In a group, who was added by hand (and so can be taken out again).
        added = chat_room_added(cur, key) - chat_room_rule_members(cur, key) if kind == 'g' else set()
        people = []
        if ids:
            cur.execute("""SELECT u.id, u.name, r.name AS role_name, d.name AS department_name FROM user u
                           LEFT JOIN rbac_role r ON r.id = u.rbac_role_id
                           LEFT JOIN department d ON d.id = u.department_id
                           WHERE u.id IN (""" + ",".join(["%s"] * len(ids)) + ") ORDER BY u.name", ids)
            people = [{'id': p['id'], 'name': p['name'], 'role_name': p['role_name'] or '',
                       'department_name': p['department_name'] or '',
                       'is_me': p['id'] == session['user_id'], 'added': p['id'] in added}
                      for p in cur.fetchall()]
        return jsonify(success=True, members=people,
                       can_manage=kind == 'g' and has('chat.group_members'))
    finally:
        cur.close()
        conn.close()


@app.route('/api/chat/groups/<room>/members', methods=['POST'])
@perm('chat.group_members')
def chat_group_add_members(room):
    """Add people to a group on top of its rule; they are told and the group appears for them."""
    if room not in CHAT_ROOMS:
        abort(404)
    data = request.get_json(silent=True) or {}
    ids = sorted({int(u) for u in (data.get('user_ids') or []) if str(u).isdigit()})
    if not ids or len(ids) > 100:
        return jsonify(success=False, error='Pick one to 100 people.'), 400
    conn, cur = connection()
    try:
        marks = ','.join(['%s'] * len(ids))
        cur.execute("SELECT id FROM user WHERE is_active = 1 AND id IN (%s)" % marks, ids)
        live = [row['id'] for row in cur.fetchall()]
        already = set(chat_room_members(cur, room))
        new = [u for u in live if u not in already]
        for user_id in new:
            cur.execute("INSERT IGNORE INTO chat_group_member (room, user_id, added_by) VALUES (%s, %s, %s)",
                        (room, user_id, session['user_id']))
        conn.commit()
    finally:
        cur.close()
        conn.close()
    if new:
        notify_users(new, 'You were added to the %s group' % CHAT_ROOMS[room]['title'],
                     '%s added you to the %s group chat.' % (session.get('name') or 'Someone', CHAT_ROOMS[room]['title']),
                     link='/home?chat=g:%s' % room, category='announcement')
    return jsonify(success=True, added=len(new))


@app.route('/api/chat/groups/<room>/members/<int:user_id>', methods=['DELETE'])
@perm('chat.group_members')
def chat_group_remove_member(room, user_id):
    """Take out someone who was added by hand; the rule's members stay."""
    if room not in CHAT_ROOMS:
        abort(404)
    conn, cur = connection()
    try:
        if user_id in chat_room_rule_members(cur, room):
            return jsonify(success=False, error='They are in this group by their role or department.'), 400
        cur.execute("DELETE FROM chat_group_member WHERE room = %s AND user_id = %s", (room, user_id))
        removed = cur.rowcount
        conn.commit()
    finally:
        cur.close()
        conn.close()
    return jsonify(success=bool(removed), error=None if removed else 'Not in this group.'), (200 if removed else 404)


@app.route('/api/chat/thread/<thread>/messages/<int:message_id>/info', methods=['GET'])
def chat_message_info(thread, message_id):
    """Message info, as on WhatsApp: who has seen my message and when, and who not yet."""
    if 'user_id' not in session:
        return jsonify(success=False, error='Not authenticated'), 401
    me = session['user_id']
    conn, cur = connection()
    try:
        kind, key = chat_thread_or_403(cur, thread)
        if kind == 'sr':
            cur.execute("SELECT user_id, created_at FROM sales_request_comments WHERE id = %s AND request_id = %s "
                        "AND is_deleted = 0", (message_id, key))
        else:
            cur.execute("SELECT user_id, created_at FROM group_chat_message WHERE id = %s AND room = %s "
                        "AND is_deleted = 0", (message_id, key))
        msg = cur.fetchone()
        if not msg:
            abort(404)
        if msg['user_id'] != me:
            abort(403)
        members = [u for u in chat_members(cur, kind, key) if u != me]
        cur.execute("SELECT user_id, MIN(seen_at) AS at FROM chat_seen WHERE thread = %s AND upto_id >= %s "
                    "GROUP BY user_id", (thread, message_id))
        seen_at = {row['user_id']: row['at'] for row in cur.fetchall()}
        names = {}
        if members:
            cur.execute("SELECT id, name FROM user WHERE id IN (" + ",".join(["%s"] * len(members)) + ")", members)
            names = {row['id']: row['name'] for row in cur.fetchall()}
        seen = sorted(({'id': u, 'name': names.get(u, ''), 'at': seen_at[u].strftime('%Y-%m-%d %H:%M:%S')}
                       for u in members if u in seen_at), key=lambda x: x['at'])
        not_seen = sorted(({'id': u, 'name': names.get(u, '')} for u in members if u not in seen_at),
                          key=lambda x: x['name'])
        return jsonify(success=True, seen=seen, not_seen=not_seen,
                       sent_at=msg['created_at'].strftime('%Y-%m-%d %H:%M:%S'))
    finally:
        cur.close()
        conn.close()


@app.route('/api/chat/media/<int:attachment_id>', methods=['GET'])
def chat_media(attachment_id):
    """A chat photo or voice note, to whoever may read that chat."""
    if 'user_id' not in session:
        abort(401)
    conn, cur = connection()
    try:
        cur.execute("SELECT thread, path, mime FROM chat_attachment WHERE id = %s", (attachment_id,))
        row = cur.fetchone()
        if not row:
            abort(404)
        chat_thread_or_403(cur, row['thread'])
    finally:
        cur.close()
        conn.close()
    root = os.path.realpath(UPLOADS_DIR)
    path = os.path.realpath(os.path.join(root, row['path']))
    if not path.startswith(root + os.sep) or not os.path.isfile(path):
        abort(404)
    response = send_file(path, mimetype=row['mime'], conditional=True)
    response.headers['Cache-Control'] = 'private, max-age=86400'
    return response


# ---- muting a chat ---------------------------------------------------------------
# Per person and per chat, like WhatsApp: 8 hours, a week, or until unmuted.
# Muting silences the chat's message sound and pop-up and keeps a muted
# group's unread count out of the badge; an @mention still notifies.
CHAT_MUTE_HOURS = (8, 168)


def chat_mutes_for(cur, user_id):
    """{thread: 'until' text, or None for always} -- live mutes only."""
    cur.execute("SELECT thread, muted_until FROM chat_mute WHERE user_id = %s "
                "AND (muted_until IS NULL OR muted_until > NOW())", (user_id,))
    return {r['thread']: (r['muted_until'].strftime('%Y-%m-%d %H:%M:%S') if r['muted_until'] else None)
            for r in cur.fetchall()}


@app.route('/api/chat/mutes', methods=['GET'])
def chat_mutes():
    if 'user_id' not in session:
        return jsonify(success=False, error='Not authenticated'), 401
    conn, cur = connection()
    try:
        return jsonify(success=True, mutes=chat_mutes_for(cur, session['user_id']))
    finally:
        cur.close()
        conn.close()


@app.route('/api/chat/thread/<thread>/mute', methods=['POST'])
def chat_mute(thread):
    """{"hours": 8 | 168} mutes for that long, {"always": true} until unmuted, {"off": true} unmutes."""
    if 'user_id' not in session:
        return jsonify(success=False, error='Not authenticated'), 401
    data = request.get_json(silent=True) or {}
    me = session['user_id']
    conn, cur = connection()
    try:
        chat_thread_or_403(cur, thread)
        if data.get('off'):
            cur.execute("DELETE FROM chat_mute WHERE user_id = %s AND thread = %s", (me, thread))
        elif data.get('always'):
            cur.execute("""INSERT INTO chat_mute (user_id, thread, muted_until) VALUES (%s, %s, NULL)
                           ON DUPLICATE KEY UPDATE muted_until = NULL""", (me, thread))
        else:
            try:
                hours = int(data.get('hours'))
            except (TypeError, ValueError):
                hours = 0
            if hours not in CHAT_MUTE_HOURS:
                return jsonify(success=False, error='Mute for 8 hours, a week, or always'), 400
            cur.execute("""INSERT INTO chat_mute (user_id, thread, muted_until)
                           VALUES (%s, %s, NOW() + INTERVAL %s HOUR)
                           ON DUPLICATE KEY UPDATE muted_until = VALUES(muted_until)""", (me, thread, hours))
        conn.commit()
        return jsonify(success=True, mutes=chat_mutes_for(cur, me))
    finally:
        cur.close()
        conn.close()


# ---- stickers -----------------------------------------------------------------
# One pack for the whole company. Anyone may add a sticker (an image, or a
# photo already in a chat they can read) and remove their own; an admin may
# remove any. Sending one makes a chat attachment that points at the same
# file, so a sticker removed from the pack still shows where it was sent.

def chat_attach_sticker(cur, thread, message_id, sticker_id):
    try:
        sticker_id = int(sticker_id)
    except (TypeError, ValueError):
        return 'Pick a sticker'
    cur.execute("SELECT path, mime, bytes, width, height FROM chat_sticker WHERE id = %s AND is_deleted = 0",
                (sticker_id,))
    st = cur.fetchone()
    if not st:
        return 'That sticker has been removed'
    cur.execute("""INSERT INTO chat_attachment (thread, message_id, user_id, kind, path, mime, bytes, width, height)
                   VALUES (%s, %s, %s, 'sticker', %s, %s, %s, %s, %s)""",
                (thread, message_id, session['user_id'], st['path'], st['mime'], st['bytes'],
                 st['width'], st['height']))
    return None


def _store_sticker(cur, data, mime):
    """Check, save and register one sticker image. Returns (row dict, error)."""
    import uuid
    from PIL import Image
    if mime not in CHAT_STICKER_TYPES:
        return None, 'Stickers are PNG, WebP, GIF or JPEG images'
    if not data:
        return None, 'The file is empty'
    if len(data) > CHAT_STICKER_MAX_BYTES:
        return None, 'Stickers up to 1 MB'
    folder = os.path.join(UPLOADS_DIR, 'chat', 'stickers')
    os.makedirs(folder, exist_ok=True)
    path = os.path.join(folder, '%s.%s' % (uuid.uuid4().hex, CHAT_STICKER_TYPES[mime]))
    with open(path, 'wb') as handle:
        handle.write(data)
    try:
        with Image.open(path) as img:
            img.verify()
        with Image.open(path) as img:
            width, height = img.size
    except Exception:
        os.remove(path)
        return None, 'That image could not be read'
    cur.execute("""INSERT INTO chat_sticker (user_id, path, mime, bytes, width, height)
                   VALUES (%s, %s, %s, %s, %s, %s)""",
                (session['user_id'], os.path.relpath(path, UPLOADS_DIR), mime, len(data), width, height))
    return {'id': cur.lastrowid, 'url': '/api/chat/stickers/%d/image' % cur.lastrowid, 'mine': True,
            'width': width, 'height': height}, None


@app.route('/api/chat/stickers', methods=['GET'])
def chat_stickers():
    if 'user_id' not in session:
        return jsonify(success=False, error='Not authenticated'), 401
    me = session['user_id']
    conn, cur = connection()
    try:
        cur.execute("SELECT id, user_id, width, height FROM chat_sticker WHERE is_deleted = 0 ORDER BY id DESC LIMIT 300")
        rows = [{'id': r['id'], 'url': '/api/chat/stickers/%d/image' % r['id'], 'width': r['width'],
                 'height': r['height'], 'mine': r['user_id'] == me} for r in cur.fetchall()]
        return jsonify(success=True, stickers=rows, can_remove_any=has('user.create'))
    finally:
        cur.close()
        conn.close()


@app.route('/api/chat/stickers', methods=['POST'])
def chat_sticker_add():
    """Add a sticker: an uploaded image, or `from_attachment` (a photo in a chat I can read)."""
    if 'user_id' not in session:
        return jsonify(success=False, error='Not authenticated'), 401
    conn, cur = connection()
    try:
        upload = request.files.get('file')
        if upload:
            mime = (upload.mimetype or '').split(';')[0].strip().lower()
            data = upload.read(CHAT_STICKER_MAX_BYTES + 1)
        else:
            body = request.get_json(silent=True) or {}
            cur.execute("SELECT thread, path, mime, kind FROM chat_attachment WHERE id = %s",
                        (body.get('from_attachment'),))
            att = cur.fetchone()
            if not att or att['kind'] not in ('image', 'sticker'):
                return jsonify(success=False, error='Only a photo can become a sticker'), 400
            chat_thread_or_403(cur, att['thread'])
            source = os.path.realpath(os.path.join(UPLOADS_DIR, att['path']))
            if not source.startswith(os.path.realpath(UPLOADS_DIR) + os.sep) or not os.path.isfile(source):
                return jsonify(success=False, error='That photo is no longer there'), 404
            mime = att['mime']
            data = _sticker_from_photo(source)
            if data is not None:
                mime = 'image/webp'
            else:
                with open(source, 'rb') as handle:
                    data = handle.read(CHAT_STICKER_MAX_BYTES + 1)
        row, error = _store_sticker(cur, data, mime)
        if error:
            return jsonify(success=False, error=error), 400
        conn.commit()
        return jsonify(success=True, sticker=row)
    finally:
        cur.close()
        conn.close()


def _sticker_from_photo(path):
    """A chat photo shrunk to sticker size (512px, WebP); None to keep it as it is."""
    from PIL import Image
    try:
        with Image.open(path) as img:
            if getattr(img, 'is_animated', False):
                return None
            img.thumbnail((512, 512))
            buf = io.BytesIO()
            img.save(buf, 'WEBP', quality=85)
            return buf.getvalue()
    except Exception:
        return None


@app.route('/api/chat/stickers/<int:sticker_id>', methods=['DELETE'])
def chat_sticker_remove(sticker_id):
    if 'user_id' not in session:
        return jsonify(success=False, error='Not authenticated'), 401
    conn, cur = connection()
    try:
        cur.execute("SELECT user_id FROM chat_sticker WHERE id = %s AND is_deleted = 0", (sticker_id,))
        row = cur.fetchone()
        if not row:
            return jsonify(success=False, error='Sticker not found'), 404
        if row['user_id'] != session['user_id'] and not has('user.create'):
            return jsonify(success=False, error='Only whoever added a sticker, or an admin, can remove it'), 403
        # The file stays: messages that already carry it still show it.
        cur.execute("UPDATE chat_sticker SET is_deleted = 1 WHERE id = %s", (sticker_id,))
        conn.commit()
        return jsonify(success=True)
    finally:
        cur.close()
        conn.close()


@app.route('/api/chat/stickers/<int:sticker_id>/image', methods=['GET'])
def chat_sticker_image(sticker_id):
    if 'user_id' not in session:
        abort(401)
    conn, cur = connection()
    try:
        cur.execute("SELECT path, mime FROM chat_sticker WHERE id = %s", (sticker_id,))
        row = cur.fetchone()
    finally:
        cur.close()
        conn.close()
    if not row:
        abort(404)
    root = os.path.realpath(UPLOADS_DIR)
    path = os.path.realpath(os.path.join(root, row['path']))
    if not path.startswith(root + os.sep) or not os.path.isfile(path):
        abort(404)
    response = send_file(path, mimetype=row['mime'], conditional=True)
    response.headers['Cache-Control'] = 'private, max-age=604800'
    return response


@app.route('/api/chat/sr/<int:request_id>/mark-read', methods=['POST'])
@perm('sales_request.comment')
def mark_chat_sr_read(request_id):
    """Mark every mention of the current user as read for the given sales request.
    Called by the chat drawer when the user opens a chat thread.
    """
    if 'user_id' not in session:
        return jsonify({'success': False, 'error': 'Not authenticated'}), 401

    try:
        conn, cur = connection()
        user_id = session['user_id']
        if not chat_may_open(cur, 'sr', request_id):
            cur.close()
            conn.close()
            return jsonify({'success': False, 'error': 'This request is not yours to talk on.'}), 403
        cur.execute(
            """
            UPDATE sales_request_comment_mentions m
            JOIN sales_request_comments c ON c.id = m.comment_id
            SET m.is_read = 1, m.read_at = NOW()
            WHERE m.mentioned_user_id = %s
              AND m.is_read = 0
              AND c.request_id = %s
              AND c.is_deleted = 0
            """,
            (user_id, request_id)
        )
        affected = cur.rowcount
        cur.execute("SELECT COALESCE(MAX(id), 0) AS n FROM sales_request_comments WHERE request_id = %s "
                    "AND is_deleted = 0", (request_id,))
        chat_mark_seen(cur, 'sr:%d' % request_id, user_id, cur.fetchone()['n'])
        conn.commit()
        cur.close()
        conn.close()
        return jsonify({'success': True, 'marked_read': affected})
    except Exception as e:
        print(f"Error marking chat SR as read: {str(e)}")
        return jsonify({'success': False, 'error': str(e)}), 500


@app.route('/api/sales/my-mentions', methods=['GET'])
@perm('sales_request.comment')
def get_my_mentions():
    """Get all mentions for the current user across all requests"""
    if 'user_id' not in session:
        return jsonify({'success': False, 'error': 'Not authenticated'}), 401
    
    try:
        conn, cur = connection()
        user_id = session['user_id']
        
        # Get only unread or get all based on query param
        only_unread = request.args.get('only_unread', 'false').lower() == 'true'
        
        query = """
            SELECT 
                c.id as comment_id,
                c.request_id,
                c.comment_text,
                c.source,
                c.created_at,
                u.name as author_name,
                sr.title as request_title,
                m.is_read,
                m.read_at
            FROM sales_request_comment_mentions m
            JOIN sales_request_comments c ON m.comment_id = c.id
            JOIN user u ON c.user_id = u.id
            JOIN sales_request sr ON c.request_id = sr.id
            WHERE m.mentioned_user_id = %s AND c.is_deleted = FALSE
        """
        
        if only_unread:
            query += " AND m.is_read = FALSE"
        
        query += " ORDER BY c.created_at DESC LIMIT 50"
        
        cur.execute(query, (user_id,))
        mentions = cur.fetchall()
        
        cur.close()
        conn.close()
        
        return jsonify({
            'success': True,
            'mentions': mentions
        })
        
    except Exception as e:
        print(f"Error fetching mentions: {str(e)}")
        return jsonify({'success': False, 'error': str(e)}), 500


@app.route('/api/users/search', methods=['GET'])
@perm('sales_request.comment')
def search_users_for_mention():
    """Search users for @mention functionality"""
    if 'user_id' not in session:
        return jsonify({'success': False, 'error': 'Not authenticated'}), 401
    
    try:
        search_term = request.args.get('q', '').strip()
        
        # Allow empty search to show all users when @ is typed
        # if len(search_term) < 2:
        #     return jsonify({'success': True, 'users': []})
        
        conn, cur = connection()
        if (request.args.get('request_id') or '').isdigit():
            # The request's chat: its members only (the chat drawer's rule).
            kind, key = chat_thread_or_403(cur, 'sr:' + request.args['request_id'])
            members = [u for u in chat_members(cur, kind, key) if u != session['user_id']]
            if not members:
                return jsonify({'success': True, 'users': []})
            like = '%' + search_term + '%'
            cur.execute("SELECT id, name, mobile FROM user WHERE id IN (" + ",".join(["%s"] * len(members))
                        + ") AND (name LIKE %s OR mobile LIKE %s) ORDER BY name", members + [like, like])
            return jsonify({'success': True, 'users': list(cur.fetchall())})
        
        # If no search term, return all active users
        if not search_term:
            cur.execute("""
                SELECT 
                    id,
                    name,
                    mobile
                FROM user
                WHERE id != %s
                ORDER BY name
                LIMIT 50
            """, (session['user_id'],))
        else:
            # Search by name or mobile
            cur.execute("""
                SELECT 
                    id,
                    name,
                    mobile
                FROM user
                WHERE (name LIKE %s OR mobile LIKE %s)
                AND id != %s
                ORDER BY name
                LIMIT 20
            """, (f'%{search_term}%', f'%{search_term}%', session['user_id']))
        
        users = cur.fetchall()
        
        cur.close()
        conn.close()
        
        return jsonify({
            'success': True,
            'users': users
        })
        
    except HTTPException:
        raise
    except Exception as e:
        print(f"Error searching users: {str(e)}")
        return jsonify({'success': False, 'error': str(e)}), 500


