@app.route('/api/finance/payment-methods', methods=['POST'])
@perm('finance_master.edit')
def add_payment_method():
    """Add a new payment method"""
    if 'user_id' not in session:
        return jsonify({'success': False, 'error': 'Not authenticated'}), 401
    
    try:
        data = request.get_json()
        method_type, bank_name, account_number, error = payment_method_fields(data)
        if error:
            return jsonify({'success': False, 'error': error}), 400
        method_name = (data.get('method_name') or '').strip()
        if not method_name and method_type == 'bank':
            method_name = '%s %s' % (bank_name, account_number)
        if not method_name:
            return jsonify({'success': False, 'error': 'Cash name is required'}), 400
        description = data.get('description', '')
        opening_balance = float(data.get('opening_balance') or 0)

        conn, cur = connection()
        if payment_method_name_taken(cur, method_name):
            cur.close()
            conn.close()
            return jsonify({'success': False, 'error': 'A payment method named "%s" already exists. '
                            'Use a distinct name, e.g. with the bank: "%s CIB"' % (method_name, method_name)}), 400

        # The code is an internal key nobody types: derived from the name,
        # suffixed until it is free.
        base = re.sub(r'[^A-Z0-9]+', '_', method_name.upper()).strip('_')[:44] or 'METHOD'
        method_code, n = base, 1
        while True:
            cur.execute("SELECT id FROM payment_methods WHERE method_code = %s", (method_code,))
            if not cur.fetchone():
                break
            n += 1
            method_code = '%s_%d' % (base, n)
        
        cur.execute("""
            INSERT INTO payment_methods 
            (method_name, method_code, method_type, description, account_number, bank_name, 
             opening_balance, current_balance, created_by)
            VALUES (%s, %s, %s, %s, %s, %s, %s, %s, %s)
        """, (method_name, method_code, method_type, description, account_number, bank_name,
              opening_balance, 0, session.get('user_name')))
        
        method_id = cur.lastrowid
        
        # The opening money is the owners' capital: booked on 3101, it moves the balance.
        if opening_balance:
            _, capital_error = book_capital(cur, method_id, opening_balance, 'Opening balance - %s' % method_name)
            if capital_error:
                conn.rollback()
                return jsonify({'success': False, 'error': capital_error}), 400
        
        conn.commit()
        cur.close()
        conn.close()
        
        return jsonify({'success': True, 'message': 'Payment method added', 'id': method_id})
    except Exception as e:
        print(f"Error adding payment method: {str(e)}")
        return jsonify({'success': False, 'error': str(e)}), 500


