def accounts_report_frames(data):
    """[(sheet name, DataFrame)] for the workbook, names resolved on every row."""
    client_names = {c['id']: c['client_name'] for c in data['clients']}
    company_names = {c['id']: c['company_name'] for c in data['companies']}
    for row in data['requests'] + data['transactions']:
        row['client_name'] = client_names.get(row.get('client_id'))
        row['company_name'] = company_names.get(row.get('company_id'))
    frames = []
    for sheet, key, columns in ACCOUNTS_REPORT_SHEETS:
        rows = data[key]
        if key == 'unlinked' and not rows:
            continue
        frame = pd.DataFrame([[_json_ready([r])[0].get(src) for _, src in columns] for r in rows],
                             columns=[label for label, _ in columns])
        frames.append((sheet, frame))
    return frames


@app.route('/api/finance/accounts/report', methods=['GET'])
@perm('finance_report.view')
def finance_accounts_report():
    """The full Client Accounts workbook, for everything or one party, in a date range."""
    f = _accounts_filters(request.args)
    conn, cur = connection()
    try:
        data = client_accounts_data(cur, with_items=True, **f)
    finally:
        cur.close()
        conn.close()
    buffer = BytesIO()
    with ExcelWriter(buffer, engine='openpyxl') as writer:
        for sheet, frame in accounts_report_frames(data):
            frame.to_excel(writer, sheet_name=sheet, index=False)
            _autosize_worksheet(writer.sheets[sheet])
    buffer.seek(0)
    name = 'client_accounts'
    if f['company_id'] and data['companies']:
        name += '_' + re.sub(r'\W+', '_', data['companies'][0]['company_name'] or '')
    elif f['client_id'] and data['clients']:
        name += '_' + re.sub(r'\W+', '_', data['clients'][0]['client_name'] or '')
    return send_file(buffer, as_attachment=True,
                     mimetype='application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
                     download_name='%s_%s.xlsx' % (name, datetime.now().strftime('%Y%m%d_%H%M')))


@app.route('/api/finance/transactions/<int:trans_id>/link-request', methods=['POST'])
@perm('finance_txn.approve')
def link_finance_transaction_request(trans_id):
    """Attach a request, and so its client, to a transaction saved without one."""
    data = request.get_json(silent=True) or {}
    sr_id = str(data.get('sales_request_id') or '').strip().upper().replace('SR-', '')
    if not sr_id.isdigit():
        return jsonify(success=False, error='Choose the Sales Request'), 400
    conn, cur = connection()
    try:
        cur.execute("SELECT id, category_id, client_id, sales_request_id FROM finance_transactions "
                    "WHERE id = %s FOR UPDATE", (trans_id,))
        tx = cur.fetchone()
        if not tx:
            return jsonify(success=False, error='Transaction not found'), 404
        if tx['sales_request_id']:
            return jsonify(success=False,
                           error='Already linked to SR-%s' % tx['sales_request_id']), 400
        client_id, error = link_transaction_to_request(cur, tx['category_id'], tx['client_id'], int(sr_id))
        if error:
            return jsonify(success=False, error=error), 400
        cur.execute("UPDATE finance_transactions SET sales_request_id = %s, client_id = %s WHERE id = %s",
                    (int(sr_id), client_id, trans_id))
        cur.execute("""
            INSERT INTO finance_approval_log
            (transaction_id, action, action_by, action_by_user_id, notes, changes_json)
            VALUES (%s, 'modified', %s, %s, %s, %s)
        """, (trans_id, session.get('name') or session.get('username') or 'System',
              session.get('user_id'), 'Linked to SR-%s' % sr_id,
              json.dumps({'sales_request_id': [None, int(sr_id)],
                          'client_id': [tx['client_id'], client_id]})))
        conn.commit()
    finally:
        cur.close()
        conn.close()
    return jsonify(success=True, sales_request_id=int(sr_id), client_id=client_id)


# ----------------------- CLIENT INVOICES -----------------------
# The account manager drafts from a Sales Request and sends it to Finance;
# Finance posts it (which numbers it and puts it on the client's account) or
# returns it with a reason. Arithmetic: invoicing.py.

INVOICE_STAGES = ('draft', 'submitted', 'returned', 'posted', 'cancelled')
INVOICE_EDITABLE_BY_AUTHOR = ('draft', 'returned')


def _invoice_dict(row):
    """A client_invoice row (or line) ready for JSON."""
    from decimal import Decimal
    from datetime import date
    out = {}
    for key, value in dict(row).items():
        if isinstance(value, Decimal):
            value = float(value)
        elif isinstance(value, (datetime, date)):
            value = value.isoformat()
        out[key] = value
    return out


def _invoice_load(cur, invoice_id):
    cur.execute("""
        SELECT i.*, co.company_name, co.tax_number AS company_tax_number, co.address AS company_address,
               c.client_name, sr.title AS request_title, sr.owner_user_id AS request_owner,
               u.name AS created_by_name, u.mobile AS created_by_mobile,
               p.name AS posted_by_name, r.name AS returned_by_name
        FROM client_invoice i
        LEFT JOIN company co ON co.id = i.company_id
        LEFT JOIN client c ON c.id = i.client_id
        LEFT JOIN sales_request sr ON sr.id = i.sales_request_id
        LEFT JOIN user u ON u.id = i.created_by
        LEFT JOIN user p ON p.id = i.posted_by
        LEFT JOIN user r ON r.id = i.returned_by
        WHERE i.id = %s
    """, (invoice_id,))
    return cur.fetchone()


def _invoice_lines(cur, invoice_id):
    cur.execute("SELECT * FROM client_invoice_line WHERE invoice_id = %s ORDER BY line_no, id", (invoice_id,))
    return [_invoice_dict(r) for r in cur.fetchall()]


def _invoice_visible(inv):
    """Finance sees every invoice; the account side what its scope reaches."""
    if has('invoice.post'):
        return True
    if not has('invoice.view'):
        return False
    ids = visible_user_ids('invoice.view')
    return ids is None or inv['created_by'] in ids or inv.get('request_owner') in ids


def _catalog_by_code(cur):
    cur.execute("SELECT id, code, name_ar, name_en, is_active FROM invoice_catalog")
    return {r['code']: r for r in cur.fetchall()}


def _write_invoice_lines(cur, invoice_id, lines, vat_rate, profit_tax_rate, apply_profit_tax):
    """Replace the invoice's lines and totals from what was sent. Returns (totals, error).

    Every line is one of the request's client-approved items: what is billed is
    what the client approved, never a line typed in. Name and code (the item's
    id) both come from the request.
    """
    cur.execute("SELECT sales_request_id FROM client_invoice WHERE id = %s", (invoice_id,))
    sr_id = (cur.fetchone() or {}).get('sales_request_id')
    cur.execute("""SELECT id, name FROM sales_request_items
                   WHERE request_id = %s AND approval_status = 'approved'""", (sr_id,))
    sr_items = {r['id']: r['name'] for r in cur.fetchall()}
    clean, seen = [], set()
    for n, line in enumerate(lines or [], start=1):
        try:
            sri = int(line.get('sales_request_item_id') or 0)
        except (TypeError, ValueError):
            sri = 0
        if sri not in sr_items:
            return None, 'Line %d is not one of SR-%s\'s client-approved items' % (n, sr_id)
        if sri in seen:
            return None, 'Line %d: "%s" is on the invoice twice' % (n, sr_items[sri])
        seen.add(sri)
        # The item's code is its own id on the request: a serial nobody types
        # and nobody can get wrong.
        clean.append({
            'catalog_id': None,
            'item_code': sri,
            'name_ar': '',
            'name_en': '',
            'description': (sr_items[sri] or '')[:500] or None,
            'qty': line.get('qty') or 0,
            'unit_price': line.get('unit_price') or 0,
            'cash_discount': line.get('cash_discount') or 0,
            'sales_request_item_id': sri,
        })
    if not clean:
        return None, 'Add at least one line'
    try:
        totals = invoicing.compute_invoice(clean, vat_rate, profit_tax_rate, apply_profit_tax)
    except (ValueError, ArithmeticError) as e:
        return None, str(e)
    cur.execute("DELETE FROM client_invoice_line WHERE invoice_id = %s", (invoice_id,))
    for n, (line, figures) in enumerate(zip(clean, totals['lines']), start=1):
        cur.execute("""
            INSERT INTO client_invoice_line (invoice_id, line_no, catalog_id, item_code, name_ar, name_en,
                description, qty, unit_price, cash_discount, sales_value, vat, line_total, sales_request_item_id)
            VALUES (%s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s)
        """, (invoice_id, n, line['catalog_id'], line['item_code'], line['name_ar'], line['name_en'],
              line['description'], line['qty'], invoicing.money(line['unit_price']),
              invoicing.money(line['cash_discount']), figures['sales_value'], figures['vat'],
              figures['line_total'], line['sales_request_item_id']))
    cur.execute("""
        UPDATE client_invoice SET subtotal = %s, cash_discount_total = %s, vat_total = %s,
               profit_tax_total = %s, total = %s WHERE id = %s
    """, (totals['subtotal'], totals['cash_discount_total'], totals['vat_total'],
          totals['profit_tax_total'], totals['total'], invoice_id))
    return totals, None


INVOICE_SERIES_ID = {'invoice': 1, 'refund': 2}
CLIENT_PAYMENTS_CATEGORY = 1
CLIENT_REFUNDS_CATEGORY_CODE = 'CLIENT_REFUNDS'


def next_invoice_number(cur, kind='invoice'):
    """The next serial of this kind: after the highest used, and never below where Finance said it continues."""
    cur.execute("SELECT next_number FROM invoice_series WHERE id = %s FOR UPDATE", (INVOICE_SERIES_ID[kind],))
    row = cur.fetchone()
    floor = row['next_number'] if row else 1
    cur.execute("SELECT COALESCE(MAX(invoice_number), 0) AS n FROM client_invoice WHERE kind = %s", (kind,))
    return max(cur.fetchone()['n'] + 1, floor)


def invoice_label(inv):
    """'Invoice 2553' or 'Refund R-12'."""
    if inv.get('kind') == 'refund':
        return 'Refund R-%s' % inv.get('invoice_number')
    return 'Invoice %s' % inv.get('invoice_number')


def book_client_money(cur, transaction_type, amount, payment_method_id, category_id, client_id,
                      sales_request_id, reference, description, day=None, supplier_id=None, note=None):
    """
    An approved finance transaction for money a client paid (income) or was
    paid back (expense), the way Finance's own approval books one: the payment
    method's balance moves, with its history and the approval log. Returns
    (transaction_id, error).
    """
    amount = float(amount)
    cur.execute("SELECT id, method_name, current_balance, is_active FROM payment_methods WHERE id = %s FOR UPDATE",
                (payment_method_id,))
    pm = cur.fetchone()
    if not pm or not pm['is_active']:
        return None, 'Choose an active payment method'
    before = float(pm['current_balance'] or 0)
    if transaction_type == 'expense' and amount > before + 0.004:
        return None, 'Not enough in %s: %s available' % (pm['method_name'], f'{before:,.2f}')
    after = before + amount if transaction_type == 'income' else before - amount
    code = generate_transaction_code()
    cur.execute("SELECT id FROM finance_transactions WHERE transaction_code = %s", (code,))
    while cur.fetchone():
        code = generate_transaction_code()
        cur.execute("SELECT id FROM finance_transactions WHERE transaction_code = %s", (code,))
    cur.execute("SELECT COALESCE(MAX(serial_number), 0) + 1 AS n FROM finance_transactions WHERE serial_number IS NOT NULL")
    serial = cur.fetchone()['n']
    who, uid = session.get('name') or session.get('username') or 'System', session.get('user_id')
    cur.execute("""
        INSERT INTO finance_transactions
        (transaction_code, transaction_type, amount, payment_method_id, category_id, client_id, supplier_id,
         sales_request_id, description, reference_number, transaction_date, status, serial_number, added_by,
         added_by_user_id, approved_by, approved_by_user_id, approved_at, balance_before, balance_after)
        VALUES (%s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, 'approved', %s, %s, %s, %s, %s, NOW(), %s, %s)
    """, (code, transaction_type, amount, payment_method_id, category_id, client_id, supplier_id, sales_request_id,
          description, reference, day or datetime.now().date(), serial, who, uid, who, uid, before, after))
    trans_id = cur.lastrowid
    cur.execute("UPDATE payment_methods SET current_balance = %s, updated_at = NOW() WHERE id = %s", (after, payment_method_id))
    cur.execute("""INSERT INTO payment_method_balance_history
                   (payment_method_id, change_type, change_amount, previous_balance, new_balance, transaction_id, description, created_by)
                   VALUES (%s, %s, %s, %s, %s, %s, %s, %s)""",
                (payment_method_id, transaction_type, amount if transaction_type == 'income' else -amount,
                 before, after, trans_id, '%s %s' % (reference, code), who))
    cur.execute("""INSERT INTO finance_approval_log (transaction_id, action, action_by, action_by_user_id, notes, previous_status, new_status)
                   VALUES (%s, 'approved', %s, %s, %s, NULL, 'approved')""",
                (trans_id, who, uid, note or 'Booked when %s was posted' % reference))
    return trans_id, None


def book_capital(cur, method_id, change, reason):
    """
    An opening balance or balance adjustment on a payment method, booked as an
    approved transaction on 3101 (capital): money in when it rises, out when it
    falls. Returns (transaction_id, error).
    """
    cur.execute("SELECT id FROM finance_categories WHERE account_code = '3101'")
    capital = cur.fetchone()
    amount = abs(float(change))
    return book_client_money(cur, 'income' if change > 0 else 'expense', amount, method_id,
                             capital['id'] if capital else 4, None, None, reason[:100], reason[:500],
                             note='Capital: %s' % reason[:200])


def _refund_category_id(cur):
    cur.execute("SELECT id FROM finance_categories WHERE category_code = %s", (CLIENT_REFUNDS_CATEGORY_CODE,))
    row = cur.fetchone()
    return row['id'] if row else 17   # Other Expenses, if the category was ever removed


@app.route('/api/invoice-series', methods=['GET', 'POST'])
@perm('invoice.view', 'invoice_catalog.edit')
def invoice_series():
    """Read, or (Finance) set, the number the next invoice will take."""
    conn, cur = connection()
    try:
        if request.method == 'POST':
            if not has('invoice_catalog.edit'):
                abort(403)
            value = str((request.get_json(silent=True) or {}).get('next_number') or '').strip()
            if not value.isdigit() or int(value) < 1:
                return jsonify(success=False, error='Give a whole number'), 400
            cur.execute("SELECT COALESCE(MAX(invoice_number), 0) AS n FROM client_invoice WHERE kind = 'invoice'")
            used = cur.fetchone()['n']
            if int(value) <= used:
                return jsonify(success=False, error='Number %d is already used; the series is past it' % used), 400
            cur.execute("""INSERT INTO invoice_series (id, next_number, updated_by) VALUES (1, %s, %s)
                           ON DUPLICATE KEY UPDATE next_number = VALUES(next_number), updated_by = VALUES(updated_by)""",
                        (int(value), session.get('user_id')))
            conn.commit()
        number = next_invoice_number(cur, 'invoice')
        refund_number = next_invoice_number(cur, 'refund')
        conn.rollback()
    finally:
        cur.close()
        conn.close()
    return jsonify(success=True, next_number=number, next_refund_number=refund_number)


def _invoice_header(data):
    """(invoice_date, billing_month, apply_profit_tax, notes, error) from a request body."""
    try:
        invoice_date = datetime.strptime(str(data.get('invoice_date') or ''), '%Y-%m-%d').date()
    except ValueError:
        return None, None, None, None, 'Invoice date is required'
    month = str(data.get('billing_month') or invoice_date.strftime('%Y-%m'))[:7]
    if not re.fullmatch(r'\d{4}-\d{2}', month):
        return None, None, None, None, 'Billing month must be YYYY-MM'
    apply_tax = data.get('apply_profit_tax', True) not in (False, 0, '0', 'false')
    return invoice_date, month, apply_tax, (data.get('notes') or '').strip()[:2000] or None, None


