@app.route('/api/my-expenses', methods=['GET'])
@perm('expense.view')
def get_my_expenses():
    """Get current user's expense tracking records"""
    try:
        user_id = session.get('user_id')
        if not user_id:
            return jsonify({'success': False, 'error': 'Not logged in'}), 401
        
        conn, cur = connection()
        
        # Get user's current balance
        cur.execute("""
            SELECT COALESCE(balance, 0) as balance 
            FROM user_finance_balances 
            WHERE user_id = %s
        """, (user_id,))
        balance_row = cur.fetchone()
        current_balance = float(balance_row['balance']) if balance_row else 0
        
        # Get all expense records for user
        status_filter = request.args.get('status', '')
        query = """
            SELECT 
                uet.*,
                s.supplier_name as supplier_display,
                u.name as approved_by_name,
                c.client_name as client_name,
                comp.company_name as company_name
            FROM user_expense_tracking uet
            LEFT JOIN supplier s ON uet.supplier_id = s.id
            LEFT JOIN user u ON uet.approved_by = u.id
            LEFT JOIN client c ON uet.client_id = c.id
            LEFT JOIN company comp ON uet.company_id = comp.id
            WHERE uet.user_id = %s
        """
        params = [user_id]
        
        if status_filter:
            query += " AND uet.status = %s"
            params.append(status_filter)
        
        query += " ORDER BY uet.created_at DESC"
        cur.execute(query, params)
        expenses = with_expense_attachments(cur, list(cur.fetchall()))
        
        # Every expense not yet approved by Finance -- draft, with the manager or
        # with Finance -- is already off what the person holds.
        position = custody_position(cur, user_id)
        
        cur.close()
        conn.close()
        
        return jsonify({
            'success': True,
            'expenses': expenses,
            'current_balance': current_balance,
            'pending_total': position['awaiting'],
            'future_balance': position['available'],
            'stages': position['stages']
        })
    except Exception as e:
        import traceback
        traceback.print_exc()
        return jsonify({'success': False, 'error': str(e)}), 500


@app.route('/api/my-expenses', methods=['POST'])
@perm('expense.create')
def add_my_expense():
    """Add new expense tracking record"""
    try:
        user_id = session.get('user_id')
        if not user_id:
            return jsonify({'success': False, 'error': 'Not logged in'}), 401
        
        data = request.get_json()
        supplier_id = data.get('supplier_id')
        supplier_name = data.get('supplier_name', '')
        amount = float(data.get('amount', 0))
        description = data.get('description', '')
        expense_date = data.get('expense_date')
        sales_request_id = data.get('sales_request_id')
        client_id = data.get('client_id')
        company_id = data.get('company_id')
        
        if amount <= 0:
            return jsonify({'success': False, 'error': 'Amount must be greater than 0'}), 400
        
        if not expense_date:
            return jsonify({'success': False, 'error': 'Date is required'}), 400
        
        conn, cur = connection()
        
        # Generate tracking code
        import random
        tracking_code = f"EXP-{random.randint(10000, 99999)}"
        
        # Get current balance for calculation
        cur.execute("""
            SELECT COALESCE(balance, 0) as balance 
            FROM user_finance_balances 
            WHERE user_id = %s
        """, (user_id,))
        balance_row = cur.fetchone()
        current_balance = float(balance_row['balance']) if balance_row else 0
        
        # Calculate future balance after this expense
        cur.execute("""
            SELECT COALESCE(SUM(amount), 0) as pending_total
            FROM user_expense_tracking
            WHERE user_id = %s AND status IN ('draft', 'submitted', 'manager_approved')
        """, (user_id,))
        pending_row = cur.fetchone()
        pending_total = float(pending_row['pending_total']) if pending_row else 0
        
        balance_before = current_balance - pending_total
        balance_after = balance_before - amount
        
        # Insert expense record
        cur.execute("""
            INSERT INTO user_expense_tracking 
            (user_id, tracking_code, supplier_id, supplier_name, sales_request_id, client_id, company_id, amount, description, expense_date, status, balance_before, balance_after)
            VALUES (%s, %s, %s, %s, %s, %s, %s, %s, %s, %s, 'draft', %s, %s)
        """, (user_id, tracking_code, supplier_id, supplier_name, sales_request_id, client_id, company_id, amount, description, expense_date, balance_before, balance_after))
        
        expense_id = cur.lastrowid
        conn.commit()
        cur.close()
        conn.close()
        
        return jsonify({
            'success': True,
            'expense_id': expense_id,
            'tracking_code': tracking_code,
            'message': 'Expense added successfully'
        })
    except Exception as e:
        import traceback
        traceback.print_exc()
        return jsonify({'success': False, 'error': str(e)}), 500


@app.route('/api/my-expenses/<int:expense_id>', methods=['PUT'])
@perm('expense.edit')
def update_my_expense(expense_id):
    """Update expense tracking record (only draft status)"""
    try:
        user_id = session.get('user_id')
        if not user_id:
            return jsonify({'success': False, 'error': 'Not logged in'}), 401
        
        data = request.get_json()
        
        conn, cur = connection()
        
        # Check ownership and status
        cur.execute("""
            SELECT * FROM user_expense_tracking 
            WHERE id = %s AND user_id = %s AND status = 'draft'
        """, (expense_id, user_id))
        expense = cur.fetchone()
        
        if not expense:
            return jsonify({'success': False, 'error': 'Expense not found or cannot be edited'}), 404
        
        # Update fields
        supplier_id = data.get('supplier_id', expense['supplier_id'])
        supplier_name = data.get('supplier_name', expense['supplier_name'])
        amount = float(data.get('amount', expense['amount']))
        description = data.get('description', expense['description'])
        expense_date = data.get('expense_date', expense['expense_date'])
        sales_request_id = data.get('sales_request_id', expense['sales_request_id'])
        client_id = data.get('client_id', expense['client_id'])
        company_id = data.get('company_id', expense['company_id'])
        
        # Recalculate balances
        cur.execute("""
            SELECT COALESCE(balance, 0) as balance 
            FROM user_finance_balances 
            WHERE user_id = %s
        """, (user_id,))
        balance_row = cur.fetchone()
        current_balance = float(balance_row['balance']) if balance_row else 0
        
        cur.execute("""
            SELECT COALESCE(SUM(amount), 0) as pending_total
            FROM user_expense_tracking
            WHERE user_id = %s AND status IN ('draft', 'submitted', 'manager_approved') AND id != %s
        """, (user_id, expense_id))
        pending_row = cur.fetchone()
        pending_total = float(pending_row['pending_total']) if pending_row else 0
        
        balance_before = current_balance - pending_total
        balance_after = balance_before - amount
        
        cur.execute("""
            UPDATE user_expense_tracking 
            SET supplier_id = %s, supplier_name = %s, amount = %s, description = %s, 
                expense_date = %s, sales_request_id = %s, client_id = %s, company_id = %s,
                balance_before = %s, balance_after = %s
            WHERE id = %s
        """, (supplier_id, supplier_name, amount, description, expense_date, 
              sales_request_id, client_id, company_id,
              balance_before, balance_after, expense_id))
        
        conn.commit()
        cur.close()
        conn.close()
        
        return jsonify({'success': True, 'message': 'Expense updated successfully'})
    except Exception as e:
        return jsonify({'success': False, 'error': str(e)}), 500


@app.route('/api/my-expenses/<int:expense_id>', methods=['DELETE'])
@perm('expense.delete')
def delete_my_expense(expense_id):
    """Delete expense tracking record (only draft status)"""
    try:
        user_id = session.get('user_id')
        if not user_id:
            return jsonify({'success': False, 'error': 'Not logged in'}), 401
        
        conn, cur = connection()
        
        cur.execute("""
            DELETE FROM user_expense_tracking 
            WHERE id = %s AND user_id = %s AND status = 'draft'
        """, (expense_id, user_id))
        
        if cur.rowcount == 0:
            return jsonify({'success': False, 'error': 'Expense not found or cannot be deleted'}), 404
        
        conn.commit()
        cur.close()
        conn.close()
        # The rows went with the expense (ON DELETE CASCADE); the files go too.
        shutil.rmtree(os.path.join(EXPENSE_FILES_DIR, str(expense_id)), ignore_errors=True)
        
        return jsonify({'success': True, 'message': 'Expense deleted successfully'})
    except Exception as e:
        return jsonify({'success': False, 'error': str(e)}), 500


@app.route('/api/my-expenses/submit', methods=['POST'])
@perm('expense.submit')
def submit_my_expenses():
    """Submit all draft expenses for approval"""
    try:
        user_id = session.get('user_id')
        if not user_id:
            return jsonify({'success': False, 'error': 'Not logged in'}), 401
        
        conn, cur = connection()
        
        # Get all draft expenses
        cur.execute("""
            SELECT id, amount FROM user_expense_tracking 
            WHERE user_id = %s AND status = 'draft'
        """, (user_id,))
        drafts = cur.fetchall()
        
        if not drafts:
            return jsonify({'success': False, 'error': 'No draft expenses to submit'}), 400
        
        # Get current balance
        cur.execute("""
            SELECT COALESCE(balance, 0) as balance 
            FROM user_finance_balances 
            WHERE user_id = %s
        """, (user_id,))
        balance_row = cur.fetchone()
        current_balance = float(balance_row['balance']) if balance_row else 0
        
        # Check if total doesn't exceed balance
        total_amount = sum(float(d['amount']) for d in drafts)
        
        # Get already submitted expenses
        cur.execute("""
            SELECT COALESCE(SUM(amount), 0) as submitted_total
            FROM user_expense_tracking
            WHERE user_id = %s AND status = 'submitted'
        """, (user_id,))
        submitted_row = cur.fetchone()
        submitted_total = float(submitted_row['submitted_total']) if submitted_row else 0
        
        if total_amount + submitted_total > current_balance:
            return jsonify({
                'success': False, 
                'error': f'Total expenses ({total_amount + submitted_total:.2f}) exceed your balance ({current_balance:.2f})'
            }), 400
        
        # Update all drafts to submitted
        cur.execute("""
            UPDATE user_expense_tracking 
            SET status = 'submitted', submitted_at = NOW()
            WHERE user_id = %s AND status = 'draft'
        """, (user_id,))
        
        conn.commit()
        cur.close()
        conn.close()
        
        return jsonify({
            'success': True, 
            'message': f'{len(drafts)} expense(s) submitted for approval',
            'submitted_count': len(drafts)
        })
    except Exception as e:
        return jsonify({'success': False, 'error': str(e)}), 500


# ----------------------- EXPENSE ATTACHMENTS -----------------------
# Receipts and documents on a My Expenses line. Optional. Stored outside the
# nginx-served uploads/ tree (receipts are financial records) and read only
# through expense_attachment_file(), which checks who is asking.

EXPENSE_FILES_DIR = os.path.join(os.path.dirname(os.path.abspath(__file__)), 'private_uploads', 'expenses')
EXPENSE_FILE_TYPES = {
    'jpg': 'image/jpeg', 'jpeg': 'image/jpeg', 'png': 'image/png', 'webp': 'image/webp',
    'gif': 'image/gif', 'heic': 'image/heic', 'pdf': 'application/pdf',
    'doc': 'application/msword',
    'docx': 'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
    'xls': 'application/vnd.ms-excel',
    'xlsx': 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
}
EXPENSE_FILE_MAX_BYTES = 10 * 1024 * 1024
EXPENSE_FILES_PER_EXPENSE = 10
# Still the owner's to change: before Finance has decided.
EXPENSE_FILES_EDITABLE = ('draft', 'submitted', 'manager_approved')


def expense_attachments_for(cur, expense_ids):
    """{expense_id: [attachment, ...]} with the URL each one is read from."""
    ids = [int(i) for i in expense_ids if i]
    if not ids:
        return {}
    cur.execute("""
        SELECT id, expense_id, original_name, file_type, file_size, uploaded_at
        FROM expense_attachments WHERE expense_id IN (%s) ORDER BY id
    """ % ','.join(['%s'] * len(ids)), ids)
    out = {}
    for row in cur.fetchall():
        out.setdefault(row['expense_id'], []).append({
            'id': row['id'], 'name': row['original_name'], 'type': row['file_type'],
            'size': row['file_size'], 'is_image': (row['file_type'] or '').startswith('image/'),
            'url': '/api/expense-attachments/%d' % row['id'],
            'uploaded_at': row['uploaded_at'].isoformat() if row['uploaded_at'] else None,
        })
    return out


def with_expense_attachments(cur, expenses):
    """Each expense row gains an `attachments` list."""
    files = expense_attachments_for(cur, [e['id'] for e in expenses])
    for e in expenses:
        e['attachments'] = files.get(e['id'], [])
    return expenses


def _scope_covers(code, owner_user_id):
    """True when the caller holds `code` with a scope that reaches this owner."""
    if not has(code):
        return False
    ids = visible_user_ids(code)
    return ids is None or owner_user_id in ids


@app.route('/api/my-expenses/<int:expense_id>/attachments', methods=['POST'])
@perm('expense.create')
def upload_expense_attachments(expense_id):
    """Attach photos or documents to one of your own expenses."""
    me = session.get('user_id')
    files = [f for f in request.files.getlist('files') if f and f.filename]
    if not files:
        return jsonify(success=False, error='Choose at least one file'), 400
    conn, cur = connection()
    saved_paths = []
    try:
        cur.execute("SELECT id, user_id, status FROM user_expense_tracking WHERE id = %s FOR UPDATE",
                    (expense_id,))
        expense = cur.fetchone()
        if not expense or expense['user_id'] != me:
            return jsonify(success=False, error='Expense not found'), 404
        if expense['status'] not in EXPENSE_FILES_EDITABLE:
            return jsonify(success=False, error='Files can no longer be added: this expense is %s'
                           % expense['status']), 400
        cur.execute("SELECT COUNT(*) AS n FROM expense_attachments WHERE expense_id = %s", (expense_id,))
        if cur.fetchone()['n'] + len(files) > EXPENSE_FILES_PER_EXPENSE:
            return jsonify(success=False, error='At most %d files per expense'
                           % EXPENSE_FILES_PER_EXPENSE), 400

        checked = []
        for handle in files:
            ext = handle.filename.rsplit('.', 1)[-1].lower() if '.' in handle.filename else ''
            if ext not in EXPENSE_FILE_TYPES:
                return jsonify(success=False, error='"%s": only photos, PDF, Word or Excel files'
                               % handle.filename), 400
            handle.seek(0, os.SEEK_END)
            size = handle.tell()
            handle.seek(0)
            if size > EXPENSE_FILE_MAX_BYTES:
                return jsonify(success=False, error='"%s" is over 10MB' % handle.filename), 400
            checked.append((handle, ext, size))

        folder = os.path.join(EXPENSE_FILES_DIR, str(expense_id))
        os.makedirs(folder, exist_ok=True)
        for handle, ext, size in checked:
            stamp = datetime.now().strftime('%Y%m%d_%H%M%S_%f')
            safe = secure_filename(handle.filename) or ('file.' + ext)
            path = os.path.join(folder, '%s_%s' % (stamp, safe))
            handle.save(path)
            saved_paths.append(path)
            cur.execute("""
                INSERT INTO expense_attachments
                (expense_id, stored_path, original_name, file_type, file_size, uploaded_by)
                VALUES (%s, %s, %s, %s, %s, %s)
            """, (expense_id, path, handle.filename[:255], EXPENSE_FILE_TYPES[ext], size, me))
        conn.commit()
        attachments = expense_attachments_for(cur, [expense_id]).get(expense_id, [])
    except Exception:
        conn.rollback()
        # Nothing recorded, so nothing kept on disk either.
        for path in saved_paths:
            try:
                os.remove(path)
            except OSError:
                pass
        raise
    finally:
        cur.close()
        conn.close()
    return jsonify(success=True, attachments=attachments)


@app.route('/api/my-expenses/attachments/<int:attachment_id>', methods=['DELETE'])
@perm('expense.create')
def delete_expense_attachment(attachment_id):
    """Take a file back off one of your own expenses, before Finance decides."""
    me = session.get('user_id')
    conn, cur = connection()
    try:
        cur.execute("""
            SELECT ea.id, ea.stored_path, uet.user_id, uet.status
            FROM expense_attachments ea JOIN user_expense_tracking uet ON uet.id = ea.expense_id
            WHERE ea.id = %s
        """, (attachment_id,))
        row = cur.fetchone()
        if not row or row['user_id'] != me:
            return jsonify(success=False, error='File not found'), 404
        if row['status'] not in EXPENSE_FILES_EDITABLE:
            return jsonify(success=False, error='This expense is %s; its files are kept' % row['status']), 400
        cur.execute("DELETE FROM expense_attachments WHERE id = %s", (attachment_id,))
        conn.commit()
    finally:
        cur.close()
        conn.close()
    try:
        os.remove(row['stored_path'])
    except OSError:
        pass
    return jsonify(success=True)


@app.route('/api/expense-attachments/<int:attachment_id>', methods=['GET'])
@perm('expense.view', 'expense_tracking.view', 'sales_request.view')
def expense_attachment_file(attachment_id):
    """
    One receipt, to whoever may see the expense: its owner, an approver whose
    scope reaches the owner, or someone who may open the request it was spent on.
    """
    conn, cur = connection()
    try:
        cur.execute("""
            SELECT ea.stored_path, ea.original_name, ea.file_type, uet.user_id,
                   sr.owner_user_id AS request_owner, uet.sales_request_id
            FROM expense_attachments ea
            JOIN user_expense_tracking uet ON uet.id = ea.expense_id
            LEFT JOIN sales_request sr ON sr.id = uet.sales_request_id
            WHERE ea.id = %s
        """, (attachment_id,))
        row = cur.fetchone()
    finally:
        cur.close()
        conn.close()
    if not row:
        abort(404)
    allowed = (row['user_id'] == session.get('user_id')
               or _scope_covers('expense_tracking.view', row['user_id'])
               or (row['sales_request_id'] and _scope_covers('sales_request.view', row['request_owner'])))
    if not allowed:
        abort(403)
    path = os.path.realpath(row['stored_path'])
    if not path.startswith(os.path.realpath(EXPENSE_FILES_DIR) + os.sep) or not os.path.exists(path):
        abort(404)
    inline = (row['file_type'] or '').startswith('image/') or row['file_type'] == 'application/pdf'
    return send_file(path, mimetype=row['file_type'] or 'application/octet-stream',
                     as_attachment=not inline, download_name=row['original_name'])


@app.route('/api/sales/requests/<int:request_id>/expenses', methods=['GET'])
@perm('sales_request.view')
def sales_request_expenses(request_id):
    """What was spent on this request from My Expenses, with the receipts."""
    conn, cur = connection()
    try:
        cur.execute("SELECT owner_user_id FROM sales_request WHERE id = %s", (request_id,))
        sr = cur.fetchone()
        if not sr:
            return jsonify(success=False, error='Request not found'), 404
        assert_scope('sales_request.view', sr['owner_user_id'])
        # Drafts are still the spender's own notes; the request sees what was sent.
        cur.execute("""
            SELECT uet.id, uet.tracking_code, uet.amount, uet.description, uet.expense_date,
                   uet.status, uet.rejection_reason, uet.submitted_at,
                   COALESCE(s.supplier_name, s.company_name, uet.supplier_name) AS supplier,
                   u.name AS spent_by, u.mobile AS spent_by_mobile
            FROM user_expense_tracking uet
            JOIN user u ON u.id = uet.user_id
            LEFT JOIN supplier s ON s.id = uet.supplier_id
            WHERE uet.sales_request_id = %s AND uet.status <> 'draft'
            ORDER BY uet.expense_date DESC, uet.id DESC
        """, (request_id,))
        expenses = with_expense_attachments(cur, [dict(r) for r in cur.fetchall()])
    finally:
        cur.close()
        conn.close()
    totals = {'approved': 0.0, 'pending': 0.0, 'rejected': 0.0}
    for e in expenses:
        amount = float(e['amount'] or 0)
        e['amount'] = amount
        e['expense_date'] = e['expense_date'].isoformat() if e['expense_date'] else None
        e['submitted_at'] = e['submitted_at'].isoformat() if e['submitted_at'] else None
        key = 'approved' if e['status'] == 'approved' else 'rejected' if e['status'] == 'rejected' else 'pending'
        totals[key] += amount
    return jsonify(success=True, expenses=expenses, totals=totals,
                   files=sum(len(e['attachments']) for e in expenses))


@app.route('/api/finance/expense-approvals', methods=['GET'])
@perm('expense_tracking.view')
def get_expense_approvals():
    """Get all submitted expenses pending approval (admin/finance only)"""
    try:
        conn, cur = connection()
        
        status_filter = request.args.get('status', 'submitted')
        
        # Support fetching both submitted and manager_approved for finance page
        if status_filter == 'pending_finance':
            cur.execute("""
                SELECT 
                    uet.*,
                    u.name as user_name,
                    u.email as user_email,
                    s.supplier_name as supplier_display,
                    ufb.balance as user_current_balance,
                    approver.name as approved_by_name,
                    c.client_name as client_name,
                    comp.company_name as company_name
                FROM user_expense_tracking uet
                JOIN user u ON uet.user_id = u.id
                LEFT JOIN supplier s ON uet.supplier_id = s.id
                LEFT JOIN user_finance_balances ufb ON uet.user_id = ufb.user_id
                LEFT JOIN user approver ON uet.approved_by = approver.id
                LEFT JOIN client c ON uet.client_id = c.id
                LEFT JOIN company comp ON uet.company_id = comp.id
                WHERE uet.status IN ('submitted', 'manager_approved')
                ORDER BY uet.submitted_at DESC
            """)
        else:
            cur.execute("""
                SELECT 
                    uet.*,
                    u.name as user_name,
                    u.email as user_email,
                    s.supplier_name as supplier_display,
                    ufb.balance as user_current_balance,
                    approver.name as approved_by_name,
                    c.client_name as client_name,
                    comp.company_name as company_name
                FROM user_expense_tracking uet
                JOIN user u ON uet.user_id = u.id
                LEFT JOIN supplier s ON uet.supplier_id = s.id
                LEFT JOIN user_finance_balances ufb ON uet.user_id = ufb.user_id
                LEFT JOIN user approver ON uet.approved_by = approver.id
                LEFT JOIN client c ON uet.client_id = c.id
                LEFT JOIN company comp ON uet.company_id = comp.id
                WHERE uet.status = %s
                ORDER BY uet.submitted_at DESC
            """, (status_filter,))
        expenses = list(cur.fetchall())
        # A manager sees their own people's expenses; Finance sees everyone's.
        ids = visible_user_ids('expense_tracking.view')
        if ids is not None:
            expenses = [e for e in expenses if e['user_id'] in ids]
        expenses = with_expense_attachments(cur, expenses)
        
        # Get count by status
        cur.execute("""
            SELECT status, COUNT(*) as count 
            FROM user_expense_tracking 
            GROUP BY status
        """)
        status_counts = {row['status']: row['count'] for row in cur.fetchall()}
        
        cur.close()
        conn.close()
        
        return jsonify({
            'success': True,
            'expenses': expenses,
            'status_counts': status_counts
        })
    except Exception as e:
        return jsonify({'success': False, 'error': str(e)}), 500


@app.route('/api/finance/expense-approvals/<int:expense_id>/approve', methods=['POST'])
@perm('expense_tracking.approve_manager')
def approve_user_expense(expense_id):
    """Manager approval - sends to finance for final approval"""
    try:
        conn, cur = connection()
        data = request.get_json() or {}
        
        # Get expense details
        cur.execute("""
            SELECT * FROM user_expense_tracking 
            WHERE id = %s AND status = 'submitted'
        """, (expense_id,))
        expense = cur.fetchone()
        
        if not expense:
            return jsonify({'success': False, 'error': 'Expense not found or not pending approval'}), 404
        if not _scope_covers('expense_tracking.approve_manager', expense['user_id']):
            return jsonify({'success': False, 'error': 'This expense is not one of your team\'s'}), 403
        
        # Store requested amount and update with edited amount
        edited_amount = data.get('edited_amount')
        if edited_amount is not None:
            cur.execute("""
                UPDATE user_expense_tracking 
                SET requested_amount = amount, amount = %s
                WHERE id = %s
            """, (float(edited_amount), expense_id))
        
        # Update expense status to manager_approved (pending finance approval)
        cur.execute("""
            UPDATE user_expense_tracking 
            SET status = 'manager_approved', 
                manager_approved_by = %s, 
                manager_approved_at = NOW()
            WHERE id = %s
        """, (session.get('user_id'), expense_id))
        
        conn.commit()
        cur.close()
        conn.close()
        
        return jsonify({'success': True, 'message': 'Expense approved and sent to finance'})
        
    except Exception as e:
        print(f"Error approving expense: {e}")
        return jsonify({'success': False, 'error': str(e)}), 500


